CREATE OR REPLACE FUNCTION private.allocate_payment_lines(target_payment_id uuid, allocation_lines jsonb, actor_auth_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment public.payments%rowtype; item jsonb; obligation_id uuid; allocation_amount bigint; allocated_total bigint:=0; target_branch uuid; target_supplier uuid; target_employee uuid; outstanding bigint; available_before bigint; advance public.advances%rowtype; advance_left bigint:=0; unclassified_before bigint; consumed_part bigint; new_allocation_id uuid;
begin
  select * into payment from public.payments where id=target_payment_id for update;
  if payment.id is null then raise exception 'payment_not_found' using errcode='23503'; end if;
  available_before:=private.payment_available(payment.id);
  select * into advance from public.advances where payment_id=payment.id and reversal_of_advance_id is null for update;
  if advance.id is not null then advance_left:=private.advance_remaining(advance.id);end if;
  unclassified_before:=greatest(0,available_before-advance_left);
  if jsonb_typeof(allocation_lines) is distinct from 'array' or jsonb_array_length(allocation_lines)>50 then raise exception 'invalid_allocations' using errcode='22023'; end if;
  if jsonb_array_length(allocation_lines)<>(select count(distinct value->>'obligation_id') from jsonb_array_elements(allocation_lines)) then raise exception 'duplicate_allocation_target' using errcode='23505'; end if;
  if payment.direction='RECEIPT' then
   perform 1 from public.receivable_obligations where id in(select (value->>'obligation_id')::uuid from jsonb_array_elements(allocation_lines)) order by id for update;
  else
   perform 1 from public.payable_obligations where id in(select (value->>'obligation_id')::uuid from jsonb_array_elements(allocation_lines)) order by id for update;
  end if;
  for item in select value from jsonb_array_elements(allocation_lines) loop
    begin obligation_id:=(item->>'obligation_id')::uuid; allocation_amount:=(item->>'amount_vnd')::bigint; exception when others then raise exception 'invalid_allocation_line' using errcode='22023'; end;
    if allocation_amount<=0 then raise exception 'invalid_allocation_amount' using errcode='22023'; end if;
    if payment.direction='RECEIPT' then
      select branch_id,customer_id into target_branch,target_supplier from public.receivable_obligations where id=obligation_id for update;
      if not found or target_branch<>payment.branch_id or target_supplier<>payment.customer_id then raise exception 'allocation_scope_mismatch' using errcode='42501'; end if;
      outstanding:=private.current_receivable_outstanding(obligation_id);
      if allocation_amount>outstanding then raise exception 'allocation_exceeds_outstanding' using errcode='23514'; end if;
      insert into public.payment_allocations(payment_id,receivable_obligation_id,amount_delta_vnd,allocated_by) values(payment.id,obligation_id,allocation_amount,actor_auth_user_id) returning id into new_allocation_id;
    else
      select branch_id,supplier_id,employee_id into target_branch,target_supplier,target_employee from public.payable_obligations where id=obligation_id for update;
      if not found or target_branch<>payment.branch_id or target_supplier is distinct from payment.supplier_id or target_employee is distinct from payment.employee_id then raise exception 'allocation_scope_mismatch' using errcode='42501'; end if;
      outstanding:=private.current_payable_outstanding(obligation_id);
      if allocation_amount>outstanding then raise exception 'allocation_exceeds_outstanding' using errcode='23514'; end if;
      insert into public.payment_allocations(payment_id,payable_obligation_id,amount_delta_vnd,allocated_by) values(payment.id,obligation_id,allocation_amount,actor_auth_user_id) returning id into new_allocation_id;
    end if;
    consumed_part:=greatest(0,allocated_total+allocation_amount-unclassified_before)-greatest(0,allocated_total-unclassified_before);
    if consumed_part>0 then
     if advance.id is null then raise exception 'allocation_exceeds_payment_available' using errcode='23514';end if;
     insert into public.advance_allocations(branch_id,advance_id,payment_allocation_id,amount_delta_vnd,recorded_by)
     values(payment.branch_id,advance.id,new_allocation_id,consumed_part,actor_auth_user_id);
    end if;
    allocated_total:=allocated_total+allocation_amount;
  end loop;
  if allocated_total>available_before then raise exception 'allocation_exceeds_payment_available' using errcode='23514'; end if;
  return allocated_total;
end $function$

CREATE OR REPLACE FUNCTION private.assert_allocation_capacity(target_sales_order_line_id uuid, requested_base_quantity numeric, excluded_allocation_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare required_quantity numeric; allocated_quantity numeric;
begin
  select l.quantity * l.conversion_numerator / l.conversion_denominator into required_quantity
  from public.sales_order_lines l where l.id = target_sales_order_line_id for update;
  if not found then raise exception 'sales_order_line_not_found' using errcode = '23503'; end if;
  select coalesce(sum(a.allocated_base_quantity), 0) into allocated_quantity
  from public.supply_allocations a
  where a.sales_order_line_id = target_sales_order_line_id
    and (excluded_allocation_id is null or a.id <> excluded_allocation_id);
  if requested_base_quantity <= 0 or allocated_quantity + requested_base_quantity > required_quantity then
    raise exception 'supply_allocation_exceeds_need' using errcode = '23514';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION private.assert_commercial_line(target_branch_id uuid, target_customer_id uuid, line jsonb, actor_auth_user_id uuid)
 RETURNS TABLE(material_id uuid, material_name text, ordered_uom_id uuid, base_uom_id uuid, quantity numeric, conversion_numerator numeric, conversion_denominator numeric, rounding_mode text, unit_price_vnd bigint, line_total_vnd bigint, pricing_rule_id uuid, pricing_rule_version integer, price_source_type text, override_by uuid, override_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  requested_rule public.pricing_rules%rowtype;
  selected_material_group_id uuid;
  selected_customer_tier_code text;
begin
  material_id := (line->>'material_id')::uuid;
  ordered_uom_id := (line->>'ordered_uom_id')::uuid;
  perform private.require_quantity_lines(jsonb_build_array(line),array['quantity','conversion_numerator','conversion_denominator'],false);
  quantity := (line->>'quantity')::numeric;
  conversion_numerator := (line->>'conversion_numerator')::numeric;
  conversion_denominator := (line->>'conversion_denominator')::numeric;
  rounding_mode := line->>'rounding_mode';
  unit_price_vnd := (line->>'unit_price_vnd')::bigint;
  pricing_rule_id := nullif(line->>'pricing_rule_id', '')::uuid;
  pricing_rule_version := nullif(line->>'pricing_rule_version', '')::integer;
  price_source_type := line->>'price_source_type';
  override_reason := nullif(line->>'override_reason', '');
  override_by := case when price_source_type = 'MANUAL_APPROVED' then actor_auth_user_id else null end;

  select m.name, m.base_uom_id, m.group_id into material_name, base_uom_id, selected_material_group_id
  from public.materials m where m.id = material_id and m.active and m.sale_enabled;
  if not found or quantity <= 0 or unit_price_vnd <= 0 or conversion_numerator <= 0 or conversion_denominator <= 0
    or rounding_mode not in ('HALF_UP','DOWN') then
    raise exception 'invalid_commercial_line' using errcode = '22023';
  end if;

  if ordered_uom_id <> base_uom_id and not exists (
    select 1 from public.material_uom_conversions c
    where c.material_id = assert_commercial_line.material_id
      and c.from_uom_id = assert_commercial_line.ordered_uom_id
      and c.to_uom_id = assert_commercial_line.base_uom_id
      and c.active and c.settlement_allowed and c.effective_from <= now() and (c.effective_to is null or c.effective_to > now())
      and c.numerator = assert_commercial_line.conversion_numerator
      and c.denominator = assert_commercial_line.conversion_denominator
  ) then
    raise exception 'invalid_or_non_settlement_conversion' using errcode = '22023';
  end if;

  if ordered_uom_id = base_uom_id and (conversion_numerator <> 1 or conversion_denominator <> 1) then
    raise exception 'base_uom_conversion_must_be_one' using errcode = '22023';
  end if;

  if price_source_type = 'MANUAL_APPROVED' then
    if override_reason is null or char_length(override_reason) < 3 or not private.has_permission(target_branch_id, 'pricing.manage') then
      raise exception 'manual_price_requires_permission_and_reason' using errcode = '42501';
    end if;
  else
    select * into requested_rule from public.pricing_rules p
    where p.id = assert_commercial_line.pricing_rule_id
      and p.branch_id = target_branch_id
      and p.version = assert_commercial_line.pricing_rule_version
      and p.price_uom_id = assert_commercial_line.ordered_uom_id
      and p.unit_price_vnd = assert_commercial_line.unit_price_vnd
      and p.active
      and p.effective_from <= now() and (p.effective_to is null or p.effective_to > now());
    if not found then raise exception 'pricing_rule_snapshot_mismatch' using errcode = '22023'; end if;
    if requested_rule.source_type is distinct from price_source_type then raise exception 'pricing_source_snapshot_mismatch' using errcode='22023';end if;
    if private.preferred_commercial_price_rule(target_branch_id,target_customer_id,material_id,ordered_uom_id) is distinct from pricing_rule_id
    then raise exception 'pricing_rule_priority_mismatch' using errcode='22023';end if;
    select c.tier_code into selected_customer_tier_code
    from public.customers c where c.id = target_customer_id and c.branch_id = target_branch_id and c.active;
    if not found then raise exception 'invalid_customer' using errcode = '22023'; end if;
    if requested_rule.scope_type = 'CUSTOMER_MATERIAL' and (requested_rule.customer_id <> target_customer_id or requested_rule.material_id <> material_id) then
      raise exception 'pricing_scope_mismatch' using errcode = '22023';
    elsif requested_rule.scope_type = 'CUSTOMER_GROUP' and (requested_rule.customer_id <> target_customer_id or requested_rule.material_group_id <> selected_material_group_id) then
      raise exception 'pricing_scope_mismatch' using errcode = '22023';
    elsif requested_rule.scope_type = 'CUSTOMER_TIER' and (requested_rule.customer_tier_code is distinct from selected_customer_tier_code or requested_rule.material_id <> material_id) then
      raise exception 'pricing_scope_mismatch' using errcode = '22023';
    elsif requested_rule.scope_type = 'DEFAULT' and requested_rule.material_id <> material_id then
      raise exception 'pricing_scope_mismatch' using errcode = '22023';
    end if;
  end if;

  perform private.require_exact_quantity(quantity*conversion_numerator/conversion_denominator,false);
  line_total_vnd := round(quantity * unit_price_vnd)::bigint;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION private.assert_delivery_resources(target_delivery_id uuid, target_employee_id uuid, target_vehicle_id uuid, target_start timestamp with time zone, target_end timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.deliveries%rowtype; vehicle public.vehicles%rowtype; l public.delivery_lines%rowtype;
 load numeric:=0; factor numeric; conversion_count integer; work_id uuid;
begin
 select * into d from public.deliveries where id=target_delivery_id;
 if target_start is null or target_end is null or target_end<=target_start
 then raise exception 'delivery_schedule_window_required' using errcode='22023';end if;
 if not private.employee_can_report_work(target_employee_id,d.branch_id) then raise exception 'delivery_employee_cannot_report_work' using errcode='23503';end if;
 select id into work_id from public.work_items where delivery_id=d.id;
 perform private.assert_work_resources_available(coalesce(work_id,d.id),d.branch_id,target_employee_id,target_vehicle_id,null,target_start,target_end);
 -- The same employee/vehicle locks protect unpublished assignments and work assignments.
 if exists(select 1 from public.delivery_assignments a join public.deliveries other on other.id=a.delivery_id
  where a.superseded_at is null and other.id<>d.id and other.execution_state in('ASSIGNED','DISPATCHED','ARRIVED','RESULT_SUBMITTED')
  and (a.employee_id=target_employee_id or a.vehicle_id=target_vehicle_id)
  and tstzrange(other.scheduled_at,coalesce(other.scheduled_end_at,other.scheduled_at+interval '4 hours'),'[)')
    &&tstzrange(target_start,target_end,'[)'))
 then raise exception 'work_resource_schedule_collision' using errcode='23P01';end if;
 select * into vehicle from public.vehicles where id=target_vehicle_id;
 if vehicle.capacity_quantity is null or vehicle.capacity_uom_id is null or vehicle.capacity_verified_at is null or vehicle.capacity_verified_by is null or nullif(trim(vehicle.capacity_source_note),'') is null
 then raise exception 'vehicle_capacity_basis_missing' using errcode='23514';end if;
 perform private.require_exact_quantity(vehicle.capacity_quantity,false);
 for l in select * from public.delivery_lines where delivery_id=d.id loop
  if l.base_uom_id=vehicle.capacity_uom_id then factor:=1;
  else
   select count(*)::integer,min(c.numerator/c.denominator) into conversion_count,factor
   from public.material_uom_conversions c where c.active and c.from_uom_id=l.base_uom_id
    and c.to_uom_id=vehicle.capacity_uom_id and (c.material_id=l.material_id or c.material_id is null)
    and c.conversion_type in('EXACT','PACKAGING','MEASURED')
    and (c.conversion_type<>'MEASURED' or nullif(trim(c.source_note),'') is not null)
    and c.effective_from<=target_start and (c.effective_to is null or c.effective_to>target_start);
   if conversion_count<>1 or factor is null
   then raise exception 'vehicle_capacity_conversion_missing' using errcode='23514';end if;
  end if;
  load:=load+l.planned_base_quantity*factor;
 end loop;
 if load>vehicle.capacity_quantity then raise exception 'vehicle_capacity_exceeded' using errcode='23514';end if;
end $function$

CREATE OR REPLACE FUNCTION private.assert_preserved_commercial_line(line jsonb, original jsonb)
 RETURNS TABLE(material_id uuid, material_name text, ordered_uom_id uuid, base_uom_id uuid, quantity numeric, conversion_numerator numeric, conversion_denominator numeric, rounding_mode text, unit_price_vnd bigint, line_total_vnd bigint, pricing_rule_id uuid, pricing_rule_version integer, price_source_type text, override_by uuid, override_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.commercial_snapshot_matches(line,original) then raise exception 'commercial_snapshot_not_preserved' using errcode='22023';end if;
 perform private.require_quantity_lines(jsonb_build_array(line),array['quantity','conversion_numerator','conversion_denominator'],false);
 material_id:=(original->>'material_id')::uuid;material_name:=original->>'material_name_snapshot';
 ordered_uom_id:=(original->>'ordered_uom_id')::uuid;base_uom_id:=(original->>'base_uom_id')::uuid;
 quantity:=(line->>'quantity')::numeric;conversion_numerator:=(original->>'conversion_numerator')::numeric;conversion_denominator:=(original->>'conversion_denominator')::numeric;
 rounding_mode:=original->>'rounding_mode';unit_price_vnd:=(original->>'unit_price_vnd')::bigint;
 pricing_rule_id:=nullif(original->>'pricing_rule_id','')::uuid;pricing_rule_version:=nullif(original->>'pricing_rule_version','')::integer;
 price_source_type:=original->>'price_source_type';override_by:=nullif(original->>'override_by','')::uuid;override_reason:=original->>'override_reason';
 perform private.require_exact_quantity(quantity*conversion_numerator/conversion_denominator,false);
 line_total_vnd:=round(quantity*unit_price_vnd)::bigint;
 if line_total_vnd<=0 then raise exception 'invalid_preserved_commercial_total' using errcode='22023';end if;
 return next;
end
$function$

CREATE OR REPLACE FUNCTION private.assert_preserved_manual_commercial_line(line jsonb, original jsonb)
 RETURNS TABLE(material_id uuid, material_name text, ordered_uom_id uuid, base_uom_id uuid, quantity numeric, conversion_numerator numeric, conversion_denominator numeric, rounding_mode text, unit_price_vnd bigint, line_total_vnd bigint, pricing_rule_id uuid, pricing_rule_version integer, price_source_type text, override_by uuid, override_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if original is null or original->>'price_source_type' <> 'MANUAL_APPROVED'
    or line->>'source_line_id' is distinct from original->>'id'
    or line->>'material_id' is distinct from original->>'material_id'
    or line->>'ordered_uom_id' is distinct from original->>'ordered_uom_id'
    or line->>'unit_price_vnd' is distinct from original->>'unit_price_vnd'
    or line->>'override_reason' is distinct from original->>'override_reason'
    or line->>'price_source_type' <> 'MANUAL_APPROVED'
    or line->>'pricing_rule_id' is not null or line->>'pricing_rule_version' is not null
    or (line->>'conversion_numerator')::numeric is distinct from (original->>'conversion_numerator')::numeric
    or (line->>'conversion_denominator')::numeric is distinct from (original->>'conversion_denominator')::numeric
    or line->>'rounding_mode' is distinct from original->>'rounding_mode'
  then raise exception 'manual_price_change_requires_permission' using errcode = '42501'; end if;

  material_id := (original->>'material_id')::uuid;
  material_name := original->>'material_name_snapshot';
  ordered_uom_id := (original->>'ordered_uom_id')::uuid;
  base_uom_id := (original->>'base_uom_id')::uuid;
  quantity := (line->>'quantity')::numeric;
  conversion_numerator := (original->>'conversion_numerator')::numeric;
  conversion_denominator := (original->>'conversion_denominator')::numeric;
  rounding_mode := original->>'rounding_mode';
  unit_price_vnd := (original->>'unit_price_vnd')::bigint;
  pricing_rule_id := null;
  pricing_rule_version := null;
  price_source_type := 'MANUAL_APPROVED';
  override_by := (original->>'override_by')::uuid;
  override_reason := original->>'override_reason';
  if quantity <= 0 or override_by is null then raise exception 'invalid_preserved_manual_line' using errcode = '22023'; end if;
  line_total_vnd := round(quantity * unit_price_vnd)::bigint;
  if line_total_vnd <= 0 then raise exception 'invalid_preserved_manual_total' using errcode = '22023'; end if;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION private.assert_purchase_line(target_branch_id uuid, target_supplier_id uuid, line jsonb, actor_auth_user_id uuid)
 RETURNS TABLE(material_id uuid, material_name text, ordered_uom_id uuid, base_uom_id uuid, quantity numeric, conversion_numerator numeric, conversion_denominator numeric, rounding_mode text, unit_cost_vnd bigint, line_total_cost_vnd bigint, purchase_price_rule_id uuid, purchase_price_rule_version integer, price_source_type text, override_by uuid, override_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare selected_rule public.purchase_price_rules%rowtype;
begin
  material_id := (line->>'material_id')::uuid;
  ordered_uom_id := (line->>'ordered_uom_id')::uuid;
  perform private.require_quantity_lines(jsonb_build_array(line),array['quantity','conversion_numerator','conversion_denominator'],false);
  quantity := (line->>'quantity')::numeric;
  conversion_numerator := (line->>'conversion_numerator')::numeric;
  conversion_denominator := (line->>'conversion_denominator')::numeric;
  rounding_mode := line->>'rounding_mode';
  unit_cost_vnd := (line->>'unit_cost_vnd')::bigint;
  purchase_price_rule_id := nullif(line->>'purchase_price_rule_id', '')::uuid;
  purchase_price_rule_version := nullif(line->>'purchase_price_rule_version', '')::integer;
  price_source_type := line->>'price_source_type';
  override_reason := nullif(line->>'override_reason', '');
  override_by := case when price_source_type = 'MANUAL_APPROVED' then actor_auth_user_id else null end;

  select m.name, m.base_uom_id into material_name, base_uom_id
  from public.materials m where m.id = assert_purchase_line.material_id and m.active and m.purchase_enabled;
  if not found or quantity <= 0 or unit_cost_vnd <= 0 or conversion_numerator <= 0 or conversion_denominator <= 0
    or rounding_mode not in ('HALF_UP','DOWN') then
    raise exception 'invalid_purchase_line' using errcode = '22023';
  end if;
  if ordered_uom_id = base_uom_id and (conversion_numerator <> 1 or conversion_denominator <> 1) then
    raise exception 'base_uom_conversion_must_be_one' using errcode = '22023';
  end if;
  if ordered_uom_id <> base_uom_id and not exists (
    select 1 from public.material_uom_conversions c
    where c.material_id = assert_purchase_line.material_id
      and c.from_uom_id = assert_purchase_line.ordered_uom_id
      and c.to_uom_id = assert_purchase_line.base_uom_id
      and c.numerator = assert_purchase_line.conversion_numerator
      and c.denominator = assert_purchase_line.conversion_denominator
      and c.active and c.settlement_allowed and c.effective_from <= now()
      and (c.effective_to is null or c.effective_to > now())
  ) then raise exception 'invalid_purchase_conversion' using errcode = '22023'; end if;

  if price_source_type = 'MANUAL_APPROVED' then
    if override_reason is null or char_length(override_reason) < 3
      or not private.has_permission(target_branch_id, 'purchasing.price.manage') then
      raise exception 'manual_purchase_price_requires_permission_and_reason' using errcode = '42501';
    end if;
  else
    select * into selected_rule from public.purchase_price_rules r
    where r.id = assert_purchase_line.purchase_price_rule_id
      and r.branch_id = target_branch_id and r.supplier_id = target_supplier_id
      and r.material_id = assert_purchase_line.material_id
      and r.purchase_uom_id = assert_purchase_line.ordered_uom_id
      and r.unit_cost_vnd = assert_purchase_line.unit_cost_vnd
      and r.version = assert_purchase_line.purchase_price_rule_version
      and r.source_type = assert_purchase_line.price_source_type and r.active
      and r.effective_from <= now() and (r.effective_to is null or r.effective_to > now());
    if not found then raise exception 'purchase_price_snapshot_mismatch' using errcode = '22023'; end if;
    if exists(select 1 from public.purchase_price_rules p where p.branch_id=target_branch_id and p.supplier_id=target_supplier_id and p.material_id=assert_purchase_line.material_id and p.purchase_uom_id=assert_purchase_line.ordered_uom_id and p.active and p.effective_from<=now() and(p.effective_to is null or p.effective_to>now()) and p.version>selected_rule.version) then raise exception 'purchase_price_priority_mismatch' using errcode='22023';end if;
    if exists(select 1 from public.purchase_price_rules p where p.branch_id=target_branch_id and p.supplier_id=target_supplier_id and p.material_id=assert_purchase_line.material_id and p.purchase_uom_id=assert_purchase_line.ordered_uom_id and p.active and p.effective_from<=now() and(p.effective_to is null or p.effective_to>now()) and p.version=selected_rule.version and p.id<>selected_rule.id) then raise exception 'purchase_price_priority_ambiguous' using errcode='22023';end if;
  end if;
  perform private.require_exact_quantity(quantity*conversion_numerator/conversion_denominator,false);
  line_total_cost_vnd := round(quantity * unit_cost_vnd)::bigint;
  return next;
end
$function$

CREATE OR REPLACE FUNCTION private.assert_vehicle_actual_load(target_delivery_id uuid, loaded_lines jsonb, load_basis_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.deliveries%rowtype; a public.delivery_assignments%rowtype; v public.vehicles%rowtype;
 cargo record; total_load numeric:=0; conversion_count integer; numerator numeric; denominator numeric;
begin
 select * into d from public.deliveries where id=target_delivery_id;
 select * into a from public.delivery_assignments where delivery_id=d.id and superseded_at is null;
 if a.vehicle_id is null then return;end if;
 -- Every canonical loading path holds this mutex before touching warehouse custody.
 select * into v from public.vehicles where id=a.vehicle_id and branch_id=d.branch_id and active for update;
 if v.id is null then raise exception 'vehicle_not_available' using errcode='23503';end if;
 if v.capacity_quantity is null or v.capacity_uom_id is null or v.capacity_verified_at is null
  or v.capacity_verified_by is null or nullif(trim(v.capacity_source_note),'') is null
 then raise exception 'vehicle_capacity_basis_missing' using errcode='23514';end if;
 for cargo in
  select c.material_id,c.base_uom_id,c.base_quantity from private.vehicle_cargo_lines(v.id) c
  union all
  select l.material_id,l.base_uom_id,(i->>'loaded_base_quantity')::numeric
   from jsonb_array_elements(loaded_lines) i join public.delivery_lines l on l.id=(i->>'delivery_line_id')::uuid
   where l.delivery_id=d.id
 loop
  if cargo.base_quantity is null or cargo.base_quantity<0 then
   raise exception 'vehicle_cargo_source_requires_reconciliation' using errcode='23514';end if;
  if cargo.base_quantity=0 then continue;end if;
  if cargo.base_uom_id=v.capacity_uom_id then numerator:=1;denominator:=1;
  else
   select count(*)::integer,min(c.numerator),min(c.denominator) into conversion_count,numerator,denominator
    from public.material_uom_conversions c where c.active and c.from_uom_id=cargo.base_uom_id
     and c.to_uom_id=v.capacity_uom_id and (c.material_id=cargo.material_id or c.material_id is null)
     and c.conversion_type in('EXACT','PACKAGING','MEASURED')
     and (c.conversion_type<>'MEASURED' or nullif(trim(c.source_note),'') is not null)
     and c.effective_from<=load_basis_at and(c.effective_to is null or c.effective_to>load_basis_at);
   if conversion_count<>1 or numerator is null or denominator is null or numerator<=0 or denominator<=0
    then raise exception 'vehicle_capacity_conversion_missing' using errcode='23514';end if;
  end if;
  total_load:=total_load+cargo.base_quantity*numerator/denominator;
 end loop;
 if total_load>v.capacity_quantity then raise exception 'vehicle_actual_cargo_capacity_exceeded' using errcode='23514';end if;
end $function$

CREATE OR REPLACE FUNCTION private.assert_work_resources_available(target_work_item_id uuid, target_branch_id uuid, target_employee_id uuid, target_vehicle_id uuid, target_machine_id uuid, target_start timestamp with time zone, target_end timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.employees e
  where e.id = target_employee_id and e.active
    and exists (select 1 from public.employee_branch_access a where a.employee_id = e.id and a.branch_id = target_branch_id and a.active)
  for update;
  if not found then raise exception 'employee_not_eligible' using errcode = '23503'; end if;
  if target_vehicle_id is not null then
    perform 1 from public.vehicles where id = target_vehicle_id and branch_id = target_branch_id and active for update;
    if not found then raise exception 'vehicle_not_available' using errcode = '23503'; end if;
  end if;
  if target_machine_id is not null then
    perform 1 from public.machines where id = target_machine_id and branch_id = target_branch_id and active for update;
    if not found then raise exception 'machine_not_available' using errcode = '23503'; end if;
  end if;
  if target_start is null or target_end is null or target_end<=target_start then raise exception 'work_schedule_window_required' using errcode='22023';end if;
  if exists(select 1 from public.delivery_assignments a join public.deliveries d on d.id=a.delivery_id
    where a.superseded_at is null and d.execution_state in('ASSIGNED','DISPATCHED','ARRIVED','RESULT_SUBMITTED')
    and d.id is distinct from (select delivery_id from public.work_items where id=target_work_item_id)
    and d.id<>target_work_item_id and (a.employee_id=target_employee_id or a.vehicle_id=target_vehicle_id)
    and tstzrange(d.scheduled_at,coalesce(d.scheduled_end_at,d.scheduled_at+interval '4 hours'),'[)')&&tstzrange(target_start,target_end,'[)'))
  then raise exception 'work_resource_schedule_collision' using errcode='23P01';end if;
  if exists (
    select 1 from public.work_item_assignments a
    join public.work_items w on w.id = a.work_item_id
    where a.superseded_at is null and w.id <> target_work_item_id
      and w.execution_state in ('CLAIMED','IN_PROGRESS','BLOCKED')
      and tstzrange(w.scheduled_start, w.scheduled_end, '[)') && tstzrange(target_start, target_end, '[)')
      and (a.employee_id = target_employee_id
        or (target_vehicle_id is not null and a.vehicle_id = target_vehicle_id)
        or (target_machine_id is not null and a.machine_id = target_machine_id))
  ) then raise exception 'work_resource_schedule_collision' using errcode = '23P01'; end if;
end
$function$

CREATE OR REPLACE FUNCTION private.assign_employee_role(target_employee_id uuid, target_branch_id uuid, target_role_id uuid, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  access_id uuid;
begin
  if (select auth.uid()) is null or not private.has_permission(target_branch_id, 'roles.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if change_reason is null or char_length(change_reason) < 3 then
    raise exception 'change_reason_required' using errcode = '22023';
  end if;

  if not exists (select 1 from public.employees where id = target_employee_id and active)
    or not exists (select 1 from public.branches where id = target_branch_id and active)
    or not exists (select 1 from public.roles where id = target_role_id and active) then
    raise exception 'inactive_or_missing_assignment_target' using errcode = '23503';
  end if;

  select id into access_id
  from public.employee_branch_access
  where employee_id = target_employee_id and branch_id = target_branch_id and active
  for update;

  if access_id is not null then
    update public.employee_branch_access
      set active = false, revoked_at = now()
      where id = access_id;
  end if;

  insert into public.employee_branch_access(employee_id, branch_id, role_id)
  values (target_employee_id, target_branch_id, target_role_id)
  returning id into access_id;

  insert into public.audit_events(
    actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason
  ) values (
    (select auth.uid()), target_branch_id, 'employee.role.assign', 'employee_branch_access',
    access_id, operation_id, array['role_id'], change_reason
  );

  return access_id;
end
$function$

CREATE OR REPLACE FUNCTION private.audit_source_command_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b uuid; source_table text;
begin
 if new.command_name not in (
  'create_sales_order_draft','create_sales_order_from_quote','create_quote_draft','create_quote_revision',
  'create_purchase_order_draft','create_direct_purchase_from_sales_line','create_direct_purchase_from_sales_order',
  'create_linked_direct_drafts','upsert_supply_allocation','reserve_inventory','release_inventory_reservation',
  'create_delivery_from_allocations','create_delivery_from_allocation','verify_supplier_fulfillment',
  'record_compensation_basis','calculate_earning_event','assign_work_item','claim_work_item','start_work_item',
  'submit_work_result','submit_portal_work_result','verify_delivery_work_item','mark_delivery_arrived')
 then return new;end if;
 source_table:=case new.result_type
  when 'sales_order' then 'sales_orders' when 'quotation' then 'quotations'
  when 'purchase_order' then 'purchase_orders' when 'supply_allocation' then 'supply_allocations'
  when 'inventory_reservation' then 'inventory_reservations' when 'delivery' then 'deliveries'
  when 'supplier_fulfillment' then 'supplier_fulfillments' when 'compensation_basis' then 'compensation_manual_bases'
  when 'earning_event' then 'earning_events' when 'work_item' then 'work_items' else null end;
 if source_table is not null then
  execute format('select branch_id from public.%I where id=$1',source_table) into b using new.result_entity_id;
 elsif new.result_type='quotation_revision' then
  select q.branch_id into b from public.quotation_revisions r join public.quotations q on q.id=r.quotation_id where r.id=new.result_entity_id;
 elsif new.result_type='work_item_assignment' then
  select w.branch_id into b from public.work_item_assignments a join public.work_items w on w.id=a.work_item_id where a.id=new.result_entity_id;
 elsif new.result_type='work_item_result' then
  select w.branch_id into b from public.work_item_results r join public.work_items w on w.id=r.work_item_id where r.id=new.result_entity_id;
 elsif new.result_type='work_item_verification' then
  select w.branch_id into b from public.work_item_verifications v join public.work_items w on w.id=v.work_item_id where v.id=new.result_entity_id;
 end if;
 if b is null then raise exception 'command_audit_source_missing' using errcode='23514';end if;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
 values(new.actor_auth_user_id,b,'command.'||new.command_name,new.result_type,new.result_entity_id,new.operation_id,array['command_result']);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.begin_authorized_opening_import(package_id uuid, b uuid, run uuid, pkg jsonb, actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.operational_opening_packages%rowtype; actual text;
begin
 select state into actual from private.branch_operational_states where branch_id=b for share;
 select * into a from private.operational_opening_packages where id=package_id for update;
 if not found or a.branch_id is distinct from b or a.run_id is distinct from run
 or a.package_payload is distinct from pkg or a.actor_id is distinct from actor
 or a.approved_by is distinct from actor or a.approved_at is null or a.recovery_accepted_at is null
 then raise exception 'opening_authorization_binding_denied' using errcode='42501';end if;
 -- Exact committed retry is read-only. It never installs another write capability.
 if a.status in ('IMPORTED','RECONCILED') then return jsonb_build_object('completed',true,'result',a.result);end if;
 if actual is distinct from 'PENDING_OPENING' or a.status<>'APPROVED'
 or a.expires_at<=clock_timestamp()
 or not exists(select 1 from private.operational_recovery_checkpoints r where r.id=a.recovery_id and r.expires_at>clock_timestamp())
 then raise exception 'opening_authorization_unusable' using errcode='42501';end if;
 insert into private.operational_opening_executions(package_id,transaction_id)
 values(a.id,pg_current_xact_id()) on conflict do nothing;
 return jsonb_build_object('completed',false);
end $function$

CREATE OR REPLACE FUNCTION private.customer_order_payload(target_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  order_row record;
  member_role text;
  deliveries_json jsonb;
begin
  select * into order_row from public.sales_order_read o where o.id = target_order_id;
  if order_row.id is null then return null; end if;
  member_role := private.portal_customer_role(order_row.customer_id);

  select coalesce(jsonb_agg(
    private.customer_delivery_payload(d.id)
    order by d.created_at, d.id
  ), '[]'::jsonb)
  into deliveries_json
  from public.delivery_read d
  where d.sales_order_id = target_order_id;

  return jsonb_strip_nulls(jsonb_build_object(
    'id', order_row.id,
    'number', order_row.order_number,
    'state', order_row.commercial_state,
    'fulfillment_state', order_row.fulfillment_state,
    'payment_state', case when member_role in ('OWNER', 'FINANCE_CONTACT') then order_row.payment_state else null end,
    'ordered_at', coalesce(order_row.confirmed_at, order_row.created_at),
    'requested_delivery_date', order_row.requested_delivery_at,
    'total_amount_vnd', case when member_role in ('OWNER', 'FINANCE_CONTACT') then order_row.total_vnd else null end,
    'deliveries', deliveries_json
  ));
end
$function$

CREATE OR REPLACE FUNCTION private.delivery_cost_sources_complete(target_verification_id uuid, cutoff timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare verification_line record; confirmed_quantity numeric; required_quantity numeric; confirmed_cost bigint;
begin
 for verification_line in select v.*,l.source_mode,l.sales_order_line_id,l.supply_allocation_id
  from public.delivery_verification_lines v join public.delivery_lines l on l.id=v.delivery_line_id where v.delivery_verification_id=target_verification_id
 loop
  if verification_line.accepted_base_quantity=0 and verification_line.billable_base_quantity=0 then continue;end if;
  if verification_line.source_mode<>'SUPPLIER_DIRECT' then
   if verification_line.inventory_cost_vnd is null or(verification_line.accepted_base_quantity>0 and verification_line.inventory_cost_vnd<=0)
    or(verification_line.accepted_base_quantity>0 and verification_line.inventory_unit_cost_vnd_per_base is null)
   then return false;end if;
  else
   select coalesce(sum(fl.supplier_base_quantity),0),coalesce(sum(fl.payable_amount_vnd),0)::bigint into confirmed_quantity,confirmed_cost
    from public.supply_allocations sa join public.supplier_fulfillment_lines fl on fl.purchase_order_line_id=sa.purchase_order_line_id
     and fl.sales_order_line_id=verification_line.sales_order_line_id
    join public.supplier_fulfillments f on f.id=fl.supplier_fulfillment_id
    where sa.id=verification_line.supply_allocation_id and f.verified_at<=cutoff
     and exists(select 1 from public.direct_cost_entries dc where dc.supplier_fulfillment_id=f.id and dc.recorded_at<=cutoff);
   select coalesce(sum(greatest(v.accepted_base_quantity,v.billable_base_quantity)),0) into required_quantity
    from public.delivery_verification_lines v join public.delivery_verifications dv on dv.id=v.delivery_verification_id
    join public.delivery_lines l on l.id=v.delivery_line_id join public.supply_allocations other_sa on other_sa.id=l.supply_allocation_id
    where l.sales_order_line_id=verification_line.sales_order_line_id and dv.verified_at<=cutoff and l.source_mode='SUPPLIER_DIRECT'
     and other_sa.purchase_order_line_id=(select sa.purchase_order_line_id from public.supply_allocations sa where sa.id=verification_line.supply_allocation_id);
   confirmed_quantity:=confirmed_quantity-private.direct_source_retired_quantity((select sa.purchase_order_line_id from public.supply_allocations sa where sa.id=verification_line.supply_allocation_id),verification_line.sales_order_line_id,cutoff);
   required_quantity:=greatest(0,required_quantity-private.direct_source_retired_quantity((select sa.purchase_order_line_id from public.supply_allocations sa where sa.id=verification_line.supply_allocation_id),verification_line.sales_order_line_id,cutoff,'CUSTOMER_RETURN'));
   if confirmed_quantity<required_quantity or confirmed_cost<=0 then return false;end if;
  end if;
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.earning_payable_outstanding(target_earning_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare earning public.earning_events%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  select * into earning from public.earning_events where id = target_earning_id;
  if not found or (
    private.has_permission(earning.branch_id, 'compensation.read')
    or (earning.employee_id = private.current_employee_id() and private.has_permission(earning.branch_id, 'work.claim'))
  ) is not true then
    raise exception 'earning_read_forbidden' using errcode = '42501';
  end if;
  return coalesce(private.current_payable_outstanding(earning.payable_obligation_id), 0);
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_operational_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_value jsonb; previous jsonb; b uuid; p jsonb; kind text; parent_id uuid;
begin
 row_value=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 previous=case when tg_op='UPDATE' then to_jsonb(old) else null end;
 if tg_op='UPDATE' and row_value->>'branch_id' is distinct from previous->>'branch_id'
 then raise exception 'operational_branch_reassignment_forbidden' using errcode='42501';end if;
 b=(row_value->>'branch_id')::uuid;
 if tg_table_name='sales_orders' and row_value->>'commercial_state' in ('DRAFT','CANCELLED')
 and (tg_op<>'UPDATE' or previous->>'commercial_state' in ('DRAFT','CANCELLED')) then return new;end if;
 if tg_table_name='purchase_orders' and row_value->>'state' in ('DRAFT','CANCELLED')
 and (tg_op<>'UPDATE' or previous->>'state' in ('DRAFT','CANCELLED')) then return new;end if;
 if tg_table_name='expenses' and row_value->>'approval_state'='DRAFT'
 and (tg_op<>'UPDATE' or previous->>'approval_state'='DRAFT') then return new;end if;
 if tg_table_name='stock_counts' and row_value->>'state'<>'APPROVED'
 and (tg_op<>'UPDATE' or previous->>'state'<>'APPROVED') then return new;end if;
 if tg_table_name='supply_allocations'
 and (tg_op<>'UPDATE' or
  (row_value-array['allocated_base_quantity','version','updated_at'])
  is not distinct from (previous-array['allocated_base_quantity','version','updated_at']))
 and private.operational_direct_purchase_draft_allocation_allowed(row_value) then
  if tg_op='DELETE' then return old;end if;
  return new;
 end if;
 if b is null then
  if tg_table_name in ('payment_allocations') then select branch_id into b from public.payments where id=(row_value->>'payment_id')::uuid;
  elsif tg_table_name='receivable_adjustments' then select branch_id into b from public.receivable_obligations where id=(row_value->>'obligation_id')::uuid;
  elsif tg_table_name='payable_adjustments' then select branch_id into b from public.payable_obligations where id=(row_value->>'obligation_id')::uuid;
  elsif tg_table_name in ('delivery_handoffs','delivery_verifications') then select branch_id into b from public.deliveries where id=(row_value->>'delivery_id')::uuid;
  elsif tg_table_name='delivery_handoff_lines' then select d.branch_id into b from public.delivery_handoffs h join public.deliveries d on d.id=h.delivery_id where h.id=(row_value->>'delivery_handoff_id')::uuid;
  elsif tg_table_name='delivery_verification_lines' then select d.branch_id into b from public.delivery_verifications v join public.deliveries d on d.id=v.delivery_id where v.id=(row_value->>'delivery_verification_id')::uuid;
  elsif tg_table_name='purchase_receipt_lines' then select branch_id into b from public.purchase_receipts where id=(row_value->>'purchase_receipt_id')::uuid;
  elsif tg_table_name='supplier_fulfillment_lines' then select branch_id into b from public.supplier_fulfillments where id=(row_value->>'supplier_fulfillment_id')::uuid;
  elsif tg_table_name='work_item_verifications' then select branch_id into b from public.work_items where id=(row_value->>'work_item_id')::uuid;
  elsif tg_table_name='service_verifications' then select branch_id into b from public.service_jobs where id=(row_value->>'service_job_id')::uuid;
  end if;
 end if;
 -- Opening records always need a consumed-per-run manifest capability, even if SQL is owned by postgres.
 if tg_table_name in ('inventory_opening_sources','opening_balance_sources','cash_opening_balances') then
  if tg_op<>'INSERT' then raise exception 'opening_history_immutable' using errcode='42501';end if;
  p=coalesce(row_value->'payload',row_value->'import_payload');
  kind=case tg_table_name when 'inventory_opening_sources' then 'INVENTORY' when 'cash_opening_balances' then 'CASH' else 'FINANCE' end;
  perform private.require_authorized_opening(b,kind,p);
 elsif tg_table_name='inventory_movements' and row_value->>'movement_type'='OPENING' then
  parent_id=(row_value->>'source_inventory_opening_id')::uuid;
  if parent_id is null then raise exception 'opening_source_required' using errcode='42501';end if;
  execute 'select payload from public.inventory_opening_sources where id=$1 and branch_id=$2' into p using parent_id,b;
  perform private.require_authorized_opening(b,'INVENTORY',p);
  if tg_op<>'INSERT' or row_value->>'location_kind' is distinct from p->>'location_kind'
  or (row_value->>'material_id')::uuid is distinct from (p->>'material_id')::uuid
  or (row_value->>'base_uom_id')::uuid is distinct from (p->>'base_uom_id')::uuid
  or (row_value->>'warehouse_id')::uuid is distinct from (p->>'warehouse_id')::uuid
  or (row_value->>'base_quantity_delta')::numeric is distinct from (p->>'base_quantity')::numeric
  or (row_value->>'inventory_value_delta_vnd')::bigint is distinct from (p->>'value_vnd')::bigint
  then raise exception 'opening_movement_scope_denied' using errcode='42501';end if;
 elsif tg_table_name in ('receivable_obligations','payable_obligations') and row_value->>'opening_source_id' is not null then
  select to_jsonb(s)->'import_payload' into p from public.opening_balance_sources s
  where id=(row_value->>'opening_source_id')::uuid and branch_id=b;
  perform private.require_authorized_opening(b,'FINANCE',p);
  if tg_op<>'INSERT' or (row_value->>'original_amount_vnd')::bigint is distinct from (p->>'outstanding_vnd')::bigint
  or (tg_table_name='receivable_obligations' and (
   p->>'party_kind'<>'CUSTOMER' or (row_value->>'customer_id')::uuid is distinct from (p->>'party_id')::uuid
   or (row_value->>'site_id')::uuid is distinct from (p->>'site_id')::uuid
   or row_value->>'delivery_verification_id' is not null or row_value->>'service_verification_id' is not null))
  or (tg_table_name='payable_obligations' and (
   p->>'party_kind' not in ('SUPPLIER','EMPLOYEE')
   or coalesce(row_value->>'supplier_id',row_value->>'employee_id') is distinct from p->>'party_id'
   or row_value->>'purchase_receipt_id' is not null or row_value->>'supplier_fulfillment_id' is not null
   or row_value->>'expense_id' is not null or row_value->>'earning_event_id' is not null))
  then raise exception 'opening_obligation_scope_denied' using errcode='42501';end if;
 else perform private.require_active_operations(b);
 end if;
 if tg_op='DELETE' then return old;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.evidence_storage_object_exists(target_bucket text, target_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare present boolean;
begin
 if to_regclass('storage.objects') is null then return false;end if;
 execute 'select exists(select 1 from storage.objects where bucket_id=$1 and name=$2)' into present using target_bucket,target_path;
 return coalesce(present,false);
end $function$

CREATE OR REPLACE FUNCTION private.guard_advance_allocation_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.advances%rowtype; allocation public.payment_allocations%rowtype; original public.advance_allocations%rowtype;
begin
 select * into a from public.advances where id=new.advance_id;
 if a.id is null or a.reversal_of_advance_id is not null or a.branch_id<>new.branch_id then raise exception 'advance_source_invalid' using errcode='23514';end if;
 if new.amount_delta_vnd>0 then
  select * into allocation from public.payment_allocations where id=new.payment_allocation_id;
  if allocation.id is null or allocation.payment_id<>a.payment_id or allocation.amount_delta_vnd<new.amount_delta_vnd
   or new.amount_delta_vnd>private.advance_remaining(a.id) then raise exception 'advance_allocation_exceeds_source' using errcode='23514';end if;
 else
  select * into original from public.advance_allocations where id=new.reversal_of_advance_allocation_id;
  if original.id is null or original.advance_id<>new.advance_id or original.amount_delta_vnd<=0 or new.amount_delta_vnd<>-original.amount_delta_vnd
   or not exists(select 1 from public.payments p where p.id=new.source_reversal_payment_id and p.reversal_of_payment_id=a.payment_id)
   then raise exception 'advance_allocation_reversal_source_invalid' using errcode='23514';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_credit_allocation_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare credit_row public.customer_credits%rowtype; fund_row public.customer_credit_funds%rowtype;
 payment_row public.payments%rowtype; obligation_row public.receivable_obligations%rowtype;
begin
 if new.source_customer_credit_id is null and new.credit_offset_fund_id is null then return new;end if;
 select * into payment_row from public.payments where id=new.payment_id;
 if new.source_customer_credit_id is not null then
  select * into credit_row from public.customer_credits where id=new.source_customer_credit_id;
  if credit_row.id is null or credit_row.obligation_id is distinct from new.receivable_obligation_id
   or credit_row.approved_by is distinct from new.allocated_by or credit_row.customer_id is distinct from payment_row.customer_id
   or credit_row.branch_id is distinct from payment_row.branch_id or payment_row.direction<>'RECEIPT'
   or -new.amount_delta_vnd+coalesce((select -sum(a.amount_delta_vnd) from public.payment_allocations a where a.source_customer_credit_id=credit_row.id),0)>credit_row.amount_vnd
  then raise exception 'credit_allocation_source_invalid' using errcode='23514';end if;
 else
  select * into fund_row from public.customer_credit_funds where id=new.credit_offset_fund_id;
  select * into credit_row from public.customer_credits where id=fund_row.credit_id;
  select * into obligation_row from public.receivable_obligations where id=new.receivable_obligation_id;
  if fund_row.id is null or fund_row.source_payment_id is distinct from new.payment_id
   or obligation_row.customer_id is distinct from credit_row.customer_id or obligation_row.branch_id is distinct from credit_row.branch_id
   or new.amount_delta_vnd>private.customer_credit_fund_remaining(fund_row.id)
  then raise exception 'credit_offset_allocation_source_invalid' using errcode='23514';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_customer_credit_funding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.customer_credits%rowtype; a public.payment_allocations%rowtype; p public.payments%rowtype;
begin
 select * into c from public.customer_credits where id=new.credit_id for update;
 select * into a from public.payment_allocations where id=new.released_allocation_id;
 select * into p from public.payments where id=new.source_payment_id;
 if c.id is null or a.id is null or a.amount_delta_vnd<>-new.amount_vnd or a.reversal_of_allocation_id is null
  or a.payment_id<>p.id or a.receivable_obligation_id is distinct from c.obligation_id
  or p.direction<>'RECEIPT' or p.reversal_of_payment_id is not null or p.customer_id is distinct from c.customer_id or p.branch_id<>c.branch_id
  or exists(select 1 from public.payments r where r.reversal_of_payment_id=p.id)
  or new.amount_vnd+coalesce((select sum(f.amount_vnd) from public.customer_credit_funds f where f.credit_id=c.id),0)>c.amount_vnd
 then raise exception 'customer_credit_funding_source_invalid' using errcode='23514';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_customer_credit_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f public.customer_credit_funds%rowtype; c public.customer_credits%rowtype; p public.payments%rowtype;
 a public.payment_allocations%rowtype; o public.receivable_obligations%rowtype; original public.customer_credit_settlements%rowtype;
begin
 select * into f from public.customer_credit_funds where id=new.credit_fund_id;
 select * into c from public.customer_credits where id=f.credit_id;
 if f.id is null or c.id is null then raise exception 'customer_credit_settlement_source_invalid' using errcode='23514';end if;
 if new.amount_delta_vnd>0 then
  if new.amount_delta_vnd>private.customer_credit_fund_remaining(f.id) or new.amount_delta_vnd>private.customer_credit_remaining(c.id)
  then raise exception 'customer_credit_settlement_exceeds_remaining' using errcode='23514';end if;
  if new.settlement_kind='REFUND' then
   select * into p from public.payments where id=new.payment_id;
   if p.id is null or p.direction<>'DISBURSEMENT' or p.customer_id is distinct from c.customer_id or p.branch_id<>c.branch_id
    or p.customer_credit_refund_id is distinct from c.id or p.reversal_of_payment_id is not null
    or exists(select 1 from public.payments r where r.reversal_of_payment_id=p.id)
    or new.amount_delta_vnd+coalesce((select sum(s.amount_delta_vnd) from public.customer_credit_settlements s where s.payment_id=p.id),0)>p.amount_vnd
   then raise exception 'customer_credit_refund_payment_invalid' using errcode='23514';end if;
  else
   select * into a from public.payment_allocations where id=new.payment_allocation_id;
   select * into o from public.receivable_obligations where id=a.receivable_obligation_id;
   if a.id is null or a.payment_id<>f.source_payment_id or a.amount_delta_vnd<>new.amount_delta_vnd or a.reversal_of_allocation_id is not null
    or o.id is null or o.branch_id<>c.branch_id or o.customer_id is distinct from c.customer_id
   then raise exception 'customer_credit_offset_allocation_invalid' using errcode='23514';end if;
  end if;
 else
  select * into original from public.customer_credit_settlements where id=new.reversal_of_settlement_id;
  if original.id is null or original.amount_delta_vnd<=0 or new.credit_fund_id<>original.credit_fund_id
   or new.settlement_kind<>original.settlement_kind or new.amount_delta_vnd<>-original.amount_delta_vnd
  then raise exception 'customer_credit_reversal_source_invalid' using errcode='23514';end if;
  if new.settlement_kind='REFUND' then
   select * into p from public.payments where id=new.source_reversal_payment_id;
   if new.payment_id is distinct from original.payment_id or p.reversal_of_payment_id is distinct from original.payment_id
   then raise exception 'customer_credit_refund_reversal_invalid' using errcode='23514';end if;
  else
   select * into a from public.payment_allocations where id=new.payment_allocation_id;
   if a.id is null or a.reversal_of_allocation_id is distinct from original.payment_allocation_id
    or a.amount_delta_vnd<>new.amount_delta_vnd or new.source_reversal_payment_id is not null
   then raise exception 'customer_credit_offset_reversal_invalid' using errcode='23514';end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_partial_allocation_reversal()
