 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare original public.payment_allocations%rowtype; p public.payments%rowtype;
begin
 if new.reversal_of_allocation_id is null then return new;end if;
