 select * into old from public.inventory_opening_sources where branch_id=b and source_ref=p->>'source_ref';
 if found then
  if old.payload is distinct from p then raise exception 'opening_source_conflict' using errcode='PT409';end if;
  return old.id;
 end if;
 select * into strict m from public.materials where id=(p->>'material_id')::uuid;
 if m.base_uom_id is distinct from (p->>'base_uom_id')::uuid then raise exception 'opening_base_uom_mismatch' using errcode='23514';end if;
 if p->>'location_kind'='WAREHOUSE' and not exists(select 1 from public.warehouses where id=(p->>'warehouse_id')::uuid and branch_id=b)
 then raise exception 'opening_warehouse_branch_mismatch' using errcode='23514';end if;
 if (p->>'base_quantity')::numeric is distinct from (p->>'base_quantity')::numeric(20,6)
 or (p->>'unit_cost')::numeric is distinct from (p->>'unit_cost')::numeric(20,6)
 then raise exception 'opening_numeric_precision' using errcode='22003';end if;
 insert into public.inventory_opening_sources(branch_id,warehouse_id,material_id,base_uom_id,location_kind,custody_reference,
 source_ref,base_quantity,unit_cost_vnd_per_base,value_vnd,cutover_at,operation_id,actor_id,payload)
 values(b,(p->>'warehouse_id')::uuid,m.id,m.base_uom_id,p->>'location_kind',p->>'custody_reference',p->>'source_ref',
 (p->>'base_quantity')::numeric,(p->>'unit_cost')::numeric,(p->>'value_vnd')::bigint,(p->>'cutover_at')::timestamptz,operation,actor,p)
 returning id into result;
 if (p->>'base_quantity')::numeric>0 then
 insert into public.inventory_movements(branch_id,material_id,base_uom_id,location_kind,warehouse_id,movement_type,
 base_quantity_delta,inventory_value_delta_vnd,unit_cost_vnd_per_base,source_inventory_opening_id,occurred_at,recorded_by)
 values(b,m.id,m.base_uom_id,p->>'location_kind',(p->>'warehouse_id')::uuid,'OPENING',
 (p->>'base_quantity')::numeric,(p->>'value_vnd')::bigint,(p->>'unit_cost')::numeric,result,(p->>'cutover_at')::timestamptz,actor);
 end if;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,reason)
 values(actor,b,'inventory.opening.posted','inventory_opening',result,operation,'Explicit operational opening source');
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.post_recognized_earning(target_rule uuid, source_key text, work_verification uuid, sales_order uuid, allocation uuid, basis_amount bigint, amount bigint, source_actor uuid, reversed_earning uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.compensation_rules%rowtype; p public.compensation_recognition_policies%rowtype;
  original public.earning_events%rowtype; event_id uuid; payable_id uuid; adjustment_id uuid;
begin
  select * into r from public.compensation_rules where id=target_rule;
  select * into p from public.compensation_recognition_policies where rule_id=r.id;
  if p.rule_id is null or source_actor is null or source_actor<>(select auth.uid()) then raise exception 'invalid_recognition_source' using errcode='42501'; end if;
  if reversed_earning is not null then
    select * into original from public.earning_events where id=reversed_earning for update;
    if original.approval_state<>'APPROVED' or original.employee_id<>p.employee_id or original.rule_id<>r.id or amount>=0 then
      raise exception 'invalid_commission_reversal' using errcode='23514'; end if;
    payable_id:=original.payable_obligation_id;
    perform 1 from public.payable_obligations where id=payable_id for update;
    if payable_id is null or private.current_payable_outstanding(payable_id)+amount<0 then
      raise exception 'commission_reversal_exceeds_unpaid_earning' using errcode='PT409'; end if;
  end if;
  insert into public.earning_events(branch_id,employee_id,rule_id,rule_code_snapshot,rule_version_snapshot,
    earning_type,classification,work_item_verification_id,sales_order_id,payment_allocation_id,reverses_earning_event_id,
    source_key,basis_quantity,basis_amount_vnd,rate_vnd_per_unit_snapshot,rate_bps_snapshot,calculated_amount_vnd,created_by)
  values(r.branch_id,p.employee_id,r.id,r.code,r.version,r.earning_type,r.classification,work_verification,
    sales_order,allocation,reversed_earning,source_key,case when allocation is null then 1 else basis_amount end,
    basis_amount,r.rate_vnd_per_unit,r.rate_bps,amount,source_actor)
  on conflict on constraint earning_events_source_key_rule_id_employee_id_key do nothing returning id into event_id;
  if event_id is null then
    select e.id into event_id from public.earning_events e where e.rule_id=r.id and e.employee_id=p.employee_id and e.source_key=post_recognized_earning.source_key;
    return event_id;
  end if;
  if amount>0 then
    insert into public.payable_obligations(branch_id,employee_id,earning_event_id,original_amount_vnd,due_date,recorded_by)
      values(r.branch_id,p.employee_id,event_id,amount,(now() at time zone 'Asia/Ho_Chi_Minh')::date,source_actor) returning id into payable_id;
  else
    insert into public.payable_adjustments(obligation_id,amount_delta_vnd,reason,recorded_by)
      values(payable_id,amount,'Commission reversal of allocation '||original.payment_allocation_id::text,source_actor) returning id into adjustment_id;
  end if;
  update public.earning_events set approval_state='APPROVED',approved_amount_vnd=amount,approved_by=p.approved_by,
    approved_at=now(),version=version+1,payable_obligation_id=case when amount>0 then payable_id else null end,
    payable_adjustment_id=adjustment_id where id=event_id;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
    values(source_actor,r.branch_id,'earning.recognized','earning_event',event_id,event_id,array['source_key','calculated_amount_vnd','payable_effect']);
  return event_id;
end $function$

CREATE OR REPLACE FUNCTION private.post_typed_revenue_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare obligation_row public.receivable_obligations%rowtype; order_id uuid;
begin
 if new.adjustment_kind not in('RETURN','PRICE') then return new;end if;
 select * into obligation_row from public.receivable_obligations where id=new.obligation_id;
 if new.adjustment_kind='RETURN' and new.return_case_id is null then raise exception 'return_revenue_source_required' using errcode='23514';end if;
 if obligation_row.delivery_verification_id is not null then
  select d.sales_order_id into order_id from public.delivery_verifications v join public.deliveries d on d.id=v.delivery_id where v.id=obligation_row.delivery_verification_id;
 elsif obligation_row.service_verification_id is null then raise exception 'price_adjustment_billing_source_required' using errcode='23514';end if;
 insert into public.revenue_adjustments(branch_id,receivable_adjustment_id,sales_order_id,service_verification_id,adjustment_kind,amount_delta_vnd,recorded_by)
 values(obligation_row.branch_id,new.id,order_id,obligation_row.service_verification_id,new.adjustment_kind,new.amount_delta_vnd,new.recorded_by);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.recognize_ar_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment public.payments%rowtype; original public.earning_events%rowtype;
  source record; policy record; amount bigint; original_allocation public.payment_allocations%rowtype; released_basis bigint; desired_cumulative bigint; prior_reductions bigint;
begin
  if new.receivable_obligation_id is null then return new; end if;
  select * into payment from public.payments where id=new.payment_id;
  if new.allocated_by<>(select auth.uid()) then raise exception 'invalid_allocation_actor' using errcode='42501'; end if;
  if new.reversal_of_allocation_id is not null then
    select * into original from public.earning_events where payment_allocation_id=new.reversal_of_allocation_id;
    if original.id is null then return new;end if;
    select * into original_allocation from public.payment_allocations where id=new.reversal_of_allocation_id;
    if not exists(select 1 from public.payments p where p.id=original_allocation.payment_id and p.direction='RECEIPT'
      and p.customer_id=payment.customer_id and p.branch_id=payment.branch_id and original.branch_id=p.branch_id
      and original_allocation.receivable_obligation_id=new.receivable_obligation_id)
    then raise exception 'invalid_commission_reversal_source' using errcode='23514';end if;
    if payment.reversal_of_payment_id=original_allocation.payment_id then
      if not private.has_permission(payment.branch_id,'finance.payment.reverse') then raise exception 'forbidden' using errcode='42501';end if;
    elsif payment.id=original_allocation.payment_id and new.source_customer_credit_id is not null then
      if not private.has_permission(payment.branch_id,'finance.ar.adjust') then raise exception 'forbidden' using errcode='42501';end if;
    elsif payment.id=original_allocation.payment_id and original_allocation.credit_offset_fund_id is not null then
      if not private.has_permission(payment.branch_id,'finance.payment.reverse') then raise exception 'forbidden' using errcode='42501';end if;
    else raise exception 'invalid_commission_reversal_source' using errcode='23514';end if;
    select coalesce(-sum(a.amount_delta_vnd),0)::bigint into released_basis from public.payment_allocations a where a.reversal_of_allocation_id=original_allocation.id;
    desired_cumulative:=least(original.approved_amount_vnd,round(released_basis::numeric*original.approved_amount_vnd/original_allocation.amount_delta_vnd)::bigint);
    select(coalesce((select -sum(e.approved_amount_vnd) from public.earning_events e where e.reverses_earning_event_id=original.id),0)
      +coalesce((select sum(c.reduction_amount_vnd) from public.commission_reconciliation_cases c where c.original_earning_event_id=original.id),0))::bigint into prior_reductions;
    amount:=desired_cumulative-prior_reductions;
    if amount<=0 then return new;end if;
    perform 1 from public.payable_obligations where id=original.payable_obligation_id for update;
    if original.payable_obligation_id is not null and private.current_payable_outstanding(original.payable_obligation_id)>=amount then
      perform private.post_recognized_earning(original.rule_id,'AR_PAYMENT_ALLOCATION:'||new.id::text,null,
        original.sales_order_id,new.id,new.amount_delta_vnd,-amount,new.allocated_by,original.id);
    else
      insert into public.commission_reconciliation_cases(branch_id,employee_id,original_earning_event_id,source_payment_allocation_id,
        reduction_amount_vnd,reason,recorded_by) values(original.branch_id,original.employee_id,original.id,new.id,amount,
          'Hoa hồng đã trả hoặc không còn đủ nghĩa vụ chưa thanh toán; cần quyết định đối chiếu nguồn, không đảo toàn thu nhập',new.allocated_by);
      insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
        values(new.allocated_by,original.branch_id,'commission.reconciliation_required','earning_event',original.id,new.id,array['source_allocation','derived_reduction']);
    end if;
    return new;
  end if;
  if payment.direction<>'RECEIPT' or payment.reversal_of_payment_id is not null or new.amount_delta_vnd<=0 then return new; end if;
  select o.id sales_order_id,o.sales_owner_employee_id employee_id,o.branch_id,ro.customer_id into source
    from public.receivable_obligations ro join public.delivery_verifications v on v.id=ro.delivery_verification_id
    join public.deliveries d on d.id=v.delivery_id join public.sales_orders o on o.id=d.sales_order_id
    where ro.id=new.receivable_obligation_id and ro.branch_id=payment.branch_id and d.branch_id=ro.branch_id
      and o.branch_id=ro.branch_id and ro.customer_id=payment.customer_id and o.customer_id=ro.customer_id;
  if source.employee_id is null then return new; end if;
  select p.*,r.rate_bps into policy from public.compensation_recognition_policies p
    join public.compensation_rules r on r.id=p.rule_id
    where p.branch_id=source.branch_id and p.employee_id=source.employee_id and p.recognition_kind='AR_PAYMENT_ALLOCATION'
      and new.allocated_at>=p.effective_at and payment.effective_at>=p.effective_at
      and (new.allocated_at at time zone 'Asia/Ho_Chi_Minh')::date>=r.effective_from
      and (r.effective_to is null or (new.allocated_at at time zone 'Asia/Ho_Chi_Minh')::date<=r.effective_to);
  if policy.rule_id is null then return new; end if;
  if not private.has_permission(payment.branch_id,'finance.payment.post') then raise exception 'forbidden' using errcode='42501'; end if;
  amount:=round(new.amount_delta_vnd::numeric*policy.rate_bps/10000)::bigint;
  if amount<>0 then
    perform private.post_recognized_earning(policy.rule_id,'AR_PAYMENT_ALLOCATION:'||new.id::text,null,
      source.sales_order_id,new.id,new.amount_delta_vnd,amount,new.allocated_by);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.recognize_verified_work()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source record; policy record; amount bigint;
begin
  select v.id,v.verified_by,v.verified_at,a.employee_id into source
    from public.work_item_verifications v join public.work_item_results r on r.id=v.result_id
    join public.work_item_assignments a on a.id=r.assignment_id and a.work_item_id=new.id
    where v.work_item_id=new.id;
  if source.id is null then raise exception 'verified_work_source_required' using errcode='23503'; end if;
  select p.*,r.rate_vnd_per_unit into policy from public.compensation_recognition_policies p
    join public.compensation_rules r on r.id=p.rule_id
    where p.branch_id=new.branch_id and p.employee_id=source.employee_id and p.recognition_kind='WORK_ITEM_VERIFICATION'
      and source.verified_at>=p.effective_at
      and (source.verified_at at time zone 'Asia/Ho_Chi_Minh')::date>=r.effective_from
      and (r.effective_to is null or (source.verified_at at time zone 'Asia/Ho_Chi_Minh')::date<=r.effective_to);
  if policy.rule_id is null then return new; end if;
  if source.verified_by<>(select auth.uid()) or not
    ((new.delivery_id is not null and private.has_permission(new.branch_id,'work.verify'))
      or (new.service_job_id is not null and private.has_permission(new.branch_id,'service.verify'))) then
    raise exception 'forbidden_work_recognition' using errcode='42501'; end if;
  amount:=round(policy.rate_vnd_per_unit)::bigint;
  perform private.post_recognized_earning(policy.rule_id,'WORK_ITEM_VERIFICATION:'||source.id::text,source.id,
    null,null,null,amount,source.verified_by);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.reconcile_legacy_return_credit(target_case uuid, requested_credit bigint, reason text, op uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.return_cases%rowtype; v public.delivery_verification_lines%rowtype; l public.delivery_lines%rowtype;
 o public.receivable_obligations%rowtype; a public.receivable_adjustments%rowtype; credit uuid:=gen_random_uuid();
 customer uuid; payment_ids uuid[]; owed bigint; left_to_fund bigint; source record; available bigint; part bigint; release uuid; prior bigint;
begin
 select * into r from public.return_cases where id=target_case for update;
 select * into v from public.delivery_verification_lines where id=r.delivery_verification_line_id;
 select * into l from public.delivery_lines where id=v.delivery_line_id;
 select so.customer_id into customer from public.sales_orders so join public.deliveries d on d.sales_order_id=so.id where d.id=l.delivery_id;
 select * into o from public.receivable_obligations where delivery_verification_id=v.delivery_verification_id;
 if r.id is null or r.case_kind<>'CUSTOMER_RETURN' or r.state<>'RETURNED' or not private.has_permission(r.branch_id,'finance.ar.adjust')
 then raise exception 'return_not_adjustable' using errcode='42501';end if;
 if(select count(*) from public.receivable_adjustments where return_case_id=r.id)<>1
 then raise exception 'legacy_return_adjustment_sources_ambiguous' using errcode='55000';end if;
 select * into a from public.receivable_adjustments where return_case_id=r.id;
 if a.obligation_id is distinct from o.id or a.amount_delta_vnd>0 or requested_credit is distinct from -a.amount_delta_vnd
  or requested_credit>least(v.receivable_amount_vnd,round(r.base_quantity*l.unit_price_vnd*l.conversion_denominator/l.conversion_numerator)::bigint)
  or coalesce(length(trim(reason)),0) not between 3 and 500
 then raise exception 'legacy_return_credit_source_mismatch' using errcode='23514';end if;
 if exists(select 1 from public.customer_credits where return_case_id=r.id)
 then raise exception 'return_credit_already_decided' using errcode='55000';end if;
 select coalesce(array_agg(distinct pa.payment_id),array[]::uuid[]) into payment_ids from public.payment_allocations pa
  where pa.receivable_obligation_id=o.id and pa.amount_delta_vnd>0;
 perform 1 from public.payments p where p.id=any(payment_ids) order by p.id for update;
 perform 1 from public.receivable_obligations where id=o.id for update;
 if exists(select 1 from public.payment_allocations pa where pa.receivable_obligation_id=o.id and pa.amount_delta_vnd>0 and not(pa.payment_id=any(payment_ids)))
 then raise exception 'return_payment_sources_changed_retry' using errcode='PT409';end if;
 select coalesce(sum(c.approved_credit_vnd),0)::bigint into prior from public.customer_credits c join public.return_cases rc on rc.id=c.return_case_id
  where rc.delivery_verification_line_id=v.id;
 if prior+requested_credit>v.receivable_amount_vnd then raise exception 'return_credit_exceeds_source' using errcode='23514';end if;
 owed:=least(requested_credit,greatest(0,-private.current_receivable_outstanding(o.id)));left_to_fund:=owed;
 insert into public.customer_credits(id,branch_id,customer_id,return_case_id,obligation_id,receivable_adjustment_id,approved_credit_vnd,amount_vnd,reason,approved_by)
 values(credit,r.branch_id,customer,r.id,o.id,a.id,requested_credit,owed,trim(reason),auth.uid());
 for source in select pa.* from public.payment_allocations pa join public.payments p on p.id=pa.payment_id
  where pa.receivable_obligation_id=o.id and pa.amount_delta_vnd>0 and p.direction='RECEIPT' and p.reversal_of_payment_id is null
   and not exists(select 1 from public.payments reversal where reversal.reversal_of_payment_id=p.id)
  order by pa.payment_id,pa.id loop
  exit when left_to_fund=0;
  select(source.amount_delta_vnd+coalesce(sum(pa.amount_delta_vnd),0))::bigint into available from public.payment_allocations pa where pa.reversal_of_allocation_id=source.id;
  part:=least(left_to_fund,available);if part<=0 then continue;end if;
  insert into public.payment_allocations(payment_id,receivable_obligation_id,amount_delta_vnd,reversal_of_allocation_id,allocated_by,source_customer_credit_id)
  values(source.payment_id,o.id,-part,source.id,auth.uid(),credit) returning id into release;
  insert into public.customer_credit_funds(credit_id,source_payment_id,released_allocation_id,amount_vnd) values(credit,source.payment_id,release,part);
  left_to_fund:=left_to_fund-part;
 end loop;
 if left_to_fund<>0 then raise exception 'return_credit_payment_source_missing' using errcode='23514';end if;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
 values(auth.uid(),r.branch_id,'customer.credit_legacy_reconciled','customer_credit',credit,op,array['existing_return_adjustment','released_allocations','credit_funds'],trim(reason));
 insert into public.command_receipts values(op,auth.uid(),'adjust_return_receivable',
  private.command_payload_hash(jsonb_build_object('return_case_id',target_case,'amount',requested_credit,'reason',trim(reason))),
  'receivable_adjustment',a.id,now());
 return a.id;
end $function$

CREATE OR REPLACE FUNCTION private.record_independent_opening_readback(package_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.operational_opening_packages%rowtype; snapshot jsonb; result_id uuid;
begin
 select * into strict a from private.operational_opening_packages where id=package_id for update;
 if a.status not in ('IMPORTED','RECONCILED') or a.writer_txid is null or a.writer_txid=pg_current_xact_id()
 then raise exception 'independent_committed_readback_required' using errcode='42501';end if;
 snapshot=private.verify_opening_source_snapshot(a.id);
 insert into private.operational_opening_readbacks(package_id,reader_txid,snapshot_sha256)
 values(a.id,pg_current_xact_id(),encode(extensions.digest(convert_to(snapshot::text,'UTF8'),'sha256'),'hex'))
 on conflict on constraint operational_opening_readbacks_package_id_key do nothing;
 select id into result_id from private.operational_opening_readbacks where operational_opening_readbacks.package_id=a.id;
 return result_id;
end $function$

CREATE OR REPLACE FUNCTION private.record_storage_attestation(kind text, eid uuid, sha text, bytes bigint, actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old private.evidence_storage_attestations%rowtype;
begin select * into old from private.evidence_storage_attestations where namespace=kind and evidence_id=eid;
 if found then if old.checksum_sha256 is distinct from sha or old.byte_size is distinct from bytes then raise exception 'evidence_attestation_conflict' using errcode='23505';end if;return;end if;
 insert into private.evidence_storage_attestations(namespace,evidence_id,checksum_sha256,byte_size,verified_by) values(kind,eid,sha,bytes,actor);end $function$

CREATE OR REPLACE FUNCTION private.register_operational_opening_package(package_id uuid, b uuid, run uuid, pkg jsonb, source_bytes bytea, manifest jsonb, actor uuid, recovery uuid, expires timestamp with time zone, data_mode text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h text; item jsonb; existing private.operational_opening_packages%rowtype; actual text;
begin
 select state into actual from private.branch_operational_states where branch_id=b for update;
 if actual is distinct from 'PENDING_OPENING' then raise exception 'opening_requires_pending_state' using errcode='PT423';end if;
 if actor is null or run is null or package_id is null or pkg is null or source_bytes is null or manifest is null
 or jsonb_typeof(pkg) is distinct from 'object' or jsonb_typeof(manifest) is distinct from 'array'
 or jsonb_array_length(manifest)=0 or expires is null or expires<=clock_timestamp()
 or data_mode is null or data_mode not in ('REAL','QA_SYNTHETIC') then
  raise exception 'opening_package_invalid' using errcode='22023'; end if;
 if pkg->>'source_sha256' is distinct from encode(extensions.digest(source_bytes,'sha256'),'hex')
 then raise exception 'opening_source_hash_mismatch' using errcode='22023';end if;
 if not exists(select 1 from private.operational_recovery_checkpoints r where r.id=recovery
 and r.branch_id=b and r.verified_at<=clock_timestamp() and r.expires_at>=expires)
 then raise exception 'opening_recovery_not_verified' using errcode='42501';end if;
 for item in select value from jsonb_array_elements(manifest) loop
  if item->>'kind' is null or item->>'kind' not in ('INVENTORY','FINANCE','CASH')
  or jsonb_typeof(item->'payload') is distinct from 'object'
  or (item->'payload'->>'branch_id')::uuid is distinct from b
  or nullif(item->'payload'->>'source_ref','') is null
  then raise exception 'opening_manifest_scope_invalid' using errcode='22023';end if;
 end loop;
 if (select count(*) from jsonb_array_elements(manifest)) <>
 (select count(distinct (m->>'kind',m->'payload'->>'source_ref')) from jsonb_array_elements(manifest) m)
 then raise exception 'opening_manifest_duplicate_source' using errcode='22023';end if;
 h=encode(extensions.digest(convert_to(pkg::text,'UTF8'),'sha256'),'hex');
 select * into existing from private.operational_opening_packages where branch_id=b and run_id=run;
 if found then
  if existing.id<>package_id or existing.package_payload<>pkg or existing.source_manifest<>manifest
   or existing.actor_id<>actor or existing.recovery_id<>recovery or existing.expires_at<>expires
   or existing.data_mode<>data_mode
  then raise exception 'opening_run_payload_conflict' using errcode='PT409';end if;
  return existing.package_sha256;
 end if;
 insert into private.operational_opening_packages(id,branch_id,run_id,package_sha256,source_sha256,
 package_payload,source_manifest,actor_id,recovery_id,expires_at,data_mode)
 values(package_id,b,run,h,pkg->>'source_sha256',pkg,manifest,actor,recovery,expires,data_mode);
 return h;
end $function$

CREATE OR REPLACE FUNCTION private.require_quantity_lines(lines jsonb, fields text[], allow_zero boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; field text;
begin
 if lines is null or jsonb_typeof(lines) is distinct from 'array'
 or jsonb_array_length(lines) not between 1 and 50
 then raise exception 'quantity_lines_required' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(lines) loop
  if jsonb_typeof(item) is distinct from 'object' then raise exception 'quantity_line_invalid' using errcode='22023';end if;
  foreach field in array fields loop
   if item->>field is null or item->>field !~ '^[0-9]+([.][0-9]+)?$'
   then raise exception 'quantity_format_invalid' using errcode='22023';end if;
   perform private.require_exact_quantity((item->>field)::numeric,allow_zero);
  end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION private.reserve_fixture_credit(target_customer_id uuid, target_branch_id uuid, requested_amount_vnd bigint, fixture_source_key text, actor_auth_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  customer_limit bigint;
  current_exposure bigint;
  existing public.credit_commitments%rowtype;
  commitment_id uuid;
begin
  if requested_amount_vnd <= 0 then
    raise exception 'credit_amount_must_be_positive' using errcode = '22023';
  end if;

  select * into existing from public.credit_commitments
  where source_type = 'LOCAL_FIXTURE' and source_key = fixture_source_key;
  if found then
    if existing.customer_id <> target_customer_id or existing.branch_id <> target_branch_id or existing.amount_vnd <> requested_amount_vnd then
      raise exception 'credit_source_payload_conflict' using errcode = '23505';
    end if;
    return existing.id;
  end if;

  select credit_limit_vnd into customer_limit
  from public.customers
  where id = target_customer_id and branch_id = target_branch_id and active
  for update;

  if not found then raise exception 'customer_not_found_in_branch' using errcode = '23503'; end if;
  if customer_limit is null then raise exception 'credit_limit_not_approved' using errcode = '23514'; end if;

  if exists (
    select 1 from public.receivable_obligations o
    where o.customer_id = target_customer_id and o.due_date < current_date
      and private.current_receivable_outstanding(o.id) > 0
  ) then
    raise exception 'overdue_receivable_blocks_credit' using errcode = '23514';
  end if;

  select coalesce(exposure_vnd, 0) into current_exposure
  from public.customer_credit_exposure where customer_id = target_customer_id;
  if current_exposure + requested_amount_vnd > customer_limit then
    raise exception 'credit_limit_exceeded' using errcode = '23514';
  end if;

  insert into public.credit_commitments(branch_id, customer_id, source_type, source_key, amount_vnd, created_by)
  values (target_branch_id, target_customer_id, 'LOCAL_FIXTURE', fixture_source_key, requested_amount_vnd, actor_auth_user_id)
  returning id into commitment_id;
  return commitment_id;
end
$function$

CREATE OR REPLACE FUNCTION private.reserve_inventory_for_line(target_sales_order_line_id uuid, target_delivery_line_id uuid, target_warehouse_id uuid, requested_base_quantity numeric, actor_auth_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sale_line public.sales_order_lines%rowtype; sale_order public.sales_orders%rowtype;
  on_hand numeric; reserved numeric; reservation_id uuid;
begin
  select * into sale_line from public.sales_order_lines where id = target_sales_order_line_id for update;
  select * into sale_order from public.sales_orders where id = sale_line.sales_order_id;
  perform 1 from public.warehouses where id = target_warehouse_id and branch_id = sale_order.branch_id and active for update;
  if not found or requested_base_quantity <= 0 then raise exception 'invalid_inventory_reservation' using errcode = '22023'; end if;
  select coalesce(sum(base_quantity_delta), 0) into on_hand from public.inventory_movements
    where warehouse_id = target_warehouse_id and material_id = sale_line.material_id and location_kind = 'WAREHOUSE';
  select coalesce(sum(reserved_base_quantity), 0) into reserved from public.inventory_reservations
    where warehouse_id = target_warehouse_id and material_id = sale_line.material_id and state = 'ACTIVE';
  if on_hand - reserved < requested_base_quantity then raise exception 'insufficient_available_inventory' using errcode = '23514'; end if;
  insert into public.inventory_reservations(branch_id, warehouse_id, material_id, sales_order_line_id,
    delivery_line_id, reserved_base_quantity, created_by)
  values (sale_order.branch_id, target_warehouse_id, sale_line.material_id, target_sales_order_line_id,
    target_delivery_line_id, requested_base_quantity, actor_auth_user_id) returning id into reservation_id;
  return reservation_id;
end
$function$

CREATE OR REPLACE FUNCTION private.reserve_sales_order_credit(target_order_id uuid, actor_auth_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_row public.sales_orders%rowtype; total bigint; limit_value bigint; exposure bigint; existing public.credit_commitments%rowtype; commitment_id uuid;
begin
  select * into order_row from public.sales_orders where id = target_order_id;
  if not found then raise exception 'sales_order_not_found' using errcode = '23503'; end if;
  select coalesce(sum(line_total_vnd), 0)::bigint into total from public.sales_order_lines where sales_order_id = target_order_id;
  select * into existing from public.credit_commitments where sales_order_id = target_order_id;
  if found then if existing.amount_vnd <> total then raise exception 'credit_commitment_payload_conflict' using errcode = '23505'; end if; return existing.id; end if;
  select credit_limit_vnd into limit_value from public.customers where id = order_row.customer_id and branch_id = order_row.branch_id and active for update;
  if not found or limit_value is null then raise exception 'credit_limit_not_approved' using errcode = '23514'; end if;
  if exists (
    select 1 from public.receivable_obligations o
    where o.customer_id = order_row.customer_id and o.due_date < current_date
      and private.current_receivable_outstanding(o.id) > 0
  ) then
    raise exception 'overdue_receivable_blocks_credit' using errcode = '23514';
  end if;
  select coalesce(exposure_vnd, 0) into exposure from public.customer_credit_exposure where customer_id = order_row.customer_id;
  if exposure + total > limit_value then raise exception 'credit_limit_exceeded' using errcode = '23514'; end if;
  insert into public.credit_commitments(branch_id, customer_id, source_type, source_key, sales_order_id, amount_vnd, created_by)
  values (order_row.branch_id, order_row.customer_id, 'SALES_ORDER', target_order_id::text, target_order_id, total, actor_auth_user_id)
  returning id into commitment_id;
  return commitment_id;
end
$function$

CREATE OR REPLACE FUNCTION private.return_cost_portion(target_case_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.return_cases%rowtype;l public.delivery_lines%rowtype;v public.delivery_verification_lines%rowtype;
 source_quantity numeric;source_value bigint;prior_quantity numeric;prior_value bigint;portion bigint;purchase_line uuid;
begin
 select * into c from public.return_cases where id=target_case_id;
 select * into l from public.delivery_lines where id=c.delivery_line_id;
 select * into v from public.delivery_verification_lines where id=c.delivery_verification_line_id;
 if c.id is null or c.state<>'OPEN' or c.case_kind not in('CUSTOMER_RETURN','TRANSIT_REMAINDER') then raise exception 'return_cost_source_invalid' using errcode='23514';end if;
 if l.source_mode='SUPPLIER_DIRECT' then
  select purchase_order_line_id into purchase_line from public.supply_allocations where id=l.supply_allocation_id;
  -- All retirements from this purchase line share its original, recorded cost pool.
  -- Callers already lock their case/delivery; take this lock only afterwards.
  perform 1 from public.purchase_order_lines where id=purchase_line for update;
  select coalesce(sum(f.supplier_base_quantity),0),coalesce(sum(f.payable_amount_vnd),0)::bigint into source_quantity,source_value
   from public.supplier_fulfillment_lines f where f.purchase_order_line_id=purchase_line and f.sales_order_line_id=l.sales_order_line_id;
  select coalesce(sum(r.base_quantity),0) into prior_quantity from public.return_cases r
   join public.delivery_lines dl on dl.id=r.delivery_line_id join public.supply_allocations sa on sa.id=dl.supply_allocation_id
   where sa.purchase_order_line_id=purchase_line and dl.sales_order_line_id=l.sales_order_line_id and dl.source_mode='SUPPLIER_DIRECT'
    and r.state='RETURNED' and r.case_kind in('CUSTOMER_RETURN','TRANSIT_REMAINDER');
  select coalesce(-sum(d.amount_delta_vnd),0)::bigint into prior_value from public.direct_cost_entries d
   join public.return_cases r on r.id=d.return_case_id join public.delivery_lines dl on dl.id=r.delivery_line_id
   join public.supply_allocations sa on sa.id=dl.supply_allocation_id
   where sa.purchase_order_line_id=purchase_line and dl.sales_order_line_id=l.sales_order_line_id and dl.source_mode='SUPPLIER_DIRECT'
    and r.state='RETURNED' and r.case_kind in('CUSTOMER_RETURN','TRANSIT_REMAINDER') and d.cost_kind='RETURN_REVERSAL';
 else
  if c.case_kind<>'CUSTOMER_RETURN' then raise exception 'return_cost_source_invalid' using errcode='23514';end if;
  source_quantity:=v.accepted_base_quantity;source_value:=v.inventory_cost_vnd;
  select coalesce(sum(r.base_quantity),0) into prior_quantity from public.return_cases r
   where r.delivery_verification_line_id=v.id and r.case_kind='CUSTOMER_RETURN' and r.state='RETURNED';
  select coalesce(sum(m.inventory_value_delta_vnd),0)::bigint into prior_value from public.inventory_movements m
   join public.return_cases r on r.id=m.source_return_case_id where r.delivery_verification_line_id=v.id
    and r.case_kind='CUSTOMER_RETURN' and r.state='RETURNED' and m.location_kind='WAREHOUSE' and m.movement_type='CUSTOMER_RETURN';
 end if;
 if source_quantity is null or source_quantity<=0 or source_value is null or source_value<=0 or prior_quantity+c.base_quantity>source_quantity
 then raise exception 'return_cost_source_missing_or_quantity_exceeded' using errcode='23514';end if;
 portion:=round((prior_quantity+c.base_quantity)*source_value/source_quantity)::bigint-prior_value;
 if portion<0 or prior_value>source_value then raise exception 'return_cost_source_reconciliation_required' using errcode='23514';end if;
 return portion;
end $function$

CREATE OR REPLACE FUNCTION private.sales_order_credit_snapshot(target_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.sales_orders%rowtype; amount bigint; exposure public.customer_credit_exposure%rowtype;
  overdue bigint; customer_active boolean;
begin
  select * into o from public.sales_orders where id = target_order_id;
  if not found then raise exception 'sales_order_not_found' using errcode = '23503'; end if;
  select coalesce(sum(line_total_vnd), 0)::bigint into amount
    from public.sales_order_lines where sales_order_id = o.id;
  select * into exposure from public.customer_credit_exposure where customer_id = o.customer_id;
  select active into customer_active from public.customers
    where id = o.customer_id and branch_id = o.branch_id;
  select coalesce(sum(greatest(private.current_receivable_outstanding(r.id), 0)), 0)::bigint
    into overdue from public.receivable_obligations r
    where r.customer_id = o.customer_id and r.due_date < current_date;
  return jsonb_build_object('order_id', o.id, 'branch_id', o.branch_id, 'customer_id', o.customer_id,
    'state', o.commercial_state, 'draft_version', o.draft_version,
    'customer_active', coalesce(customer_active, false), 'order_amount_vnd', amount::text,
    'approved_limit_vnd', exposure.credit_limit_vnd::text,
    'exposure_vnd', coalesce(exposure.exposure_vnd, 0)::text, 'overdue_vnd', overdue::text);
end
$function$

CREATE OR REPLACE FUNCTION private.verify_opening_source_snapshot(package_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.operational_opening_packages%rowtype; m jsonb; p jsonb; actual jsonb;
 source_id uuid; qty numeric; value_total bigint; n integer; snapshot jsonb='[]'::jsonb;
begin
 select * into strict a from private.operational_opening_packages where id=package_id;
 for m in select value from jsonb_array_elements(a.source_manifest) loop
  p=m->'payload'; actual=null;source_id=null;
  if m->>'kind'='INVENTORY' then
   execute 'select id,payload from public.inventory_opening_sources where branch_id=$1 and source_ref=$2'
   into source_id,actual using a.branch_id,p->>'source_ref';
   if actual is distinct from p then raise exception 'opening_inventory_readback_mismatch' using errcode='PT409';end if;
   execute 'select count(*)::int,coalesce(sum(base_quantity_delta),0),coalesce(sum(inventory_value_delta_vnd),0)::bigint from public.inventory_movements where source_inventory_opening_id=$1'
   into n,qty,value_total using source_id;
   if n<>(case when (p->>'base_quantity')::numeric>0 then 1 else 0 end)
   or qty<>(p->>'base_quantity')::numeric or value_total<>(p->>'value_vnd')::bigint
   then raise exception 'opening_inventory_reconciliation_failed' using errcode='PT409';end if;
  elsif m->>'kind'='FINANCE' then
   select id,to_jsonb(t)->'import_payload' into source_id,actual from public.opening_balance_sources t
   where branch_id=a.branch_id and source_ref=p->>'source_ref'
   and side=case when p->>'party_kind'='CUSTOMER' then 'RECEIVABLE' else 'PAYABLE' end;
   if actual is distinct from p then raise exception 'opening_finance_readback_mismatch' using errcode='PT409';end if;
   if p->>'party_kind'='CUSTOMER' then
    select count(*)::int,coalesce(sum(original_amount_vnd),0)::bigint into n,value_total
    from public.receivable_obligations where opening_source_id=source_id;
   else
    select count(*)::int,coalesce(sum(original_amount_vnd),0)::bigint into n,value_total
    from public.payable_obligations where opening_source_id=source_id;
   end if;
   if n<>(case when (p->>'outstanding_vnd')::bigint>0 then 1 else 0 end)
   or value_total<>(p->>'outstanding_vnd')::bigint
   then raise exception 'opening_finance_reconciliation_failed' using errcode='PT409';end if;
  elsif m->>'kind'='CASH' then
   execute 'select id,payload from public.cash_opening_balances where branch_id=$1 and source_ref=$2'
   into source_id,actual using a.branch_id,p->>'source_ref';
   if actual is distinct from p then raise exception 'opening_cash_readback_mismatch' using errcode='PT409';end if;
  else raise exception 'unsupported_opening_domain' using errcode='22023';end if;
  snapshot=snapshot||jsonb_build_array(jsonb_build_object('source_id',source_id,'kind',m->>'kind','payload',actual));
 end loop;
 return snapshot;
end $function$

CREATE OR REPLACE FUNCTION private.worker_work_item_payload(target_work_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.work_items%rowtype; d public.deliveries%rowtype; s public.service_jobs%rowtype;
  customer jsonb; site jsonb; lines jsonb; proofs jsonb; source_assignment integer;
begin
  select * into w from public.work_items where id=target_work_item_id;
  if w.id is null then return null; end if;
  if w.delivery_id is not null then
    select * into d from public.deliveries where id=w.delivery_id;
    select assignment_version into source_assignment from public.delivery_assignments where delivery_id=d.id and superseded_at is null;
    select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'material_name',sl.material_name_snapshot,
      'unit',u.symbol,'planned_base_quantity',l.planned_base_quantity::text) order by l.id),'[]'::jsonb) into lines
    from public.delivery_lines l join public.sales_order_lines sl on sl.id=l.sales_order_line_id
      join public.units_of_measure u on u.id=l.base_uom_id where l.delivery_id=d.id;
    select to_jsonb(c) into customer from public.customers c where c.id=d.customer_id;
    select to_jsonb(cs) into site from public.customer_sites cs where cs.id=d.site_id;
  else
    select * into s from public.service_jobs where id=w.service_job_id;
    select to_jsonb(c) into customer from public.customers c where c.id=s.customer_id;
    select to_jsonb(cs) into site from public.customer_sites cs where cs.id=s.site_id;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'mime_type',e.mime_type,'created_at',e.created_at)
    order by e.created_at desc),'[]'::jsonb) into proofs from public.portal_evidence_objects e
    where e.work_item_id=w.id and e.object_state='READY' and e.uploaded_by=(select auth.uid());
  return jsonb_strip_nulls(jsonb_build_object('id',w.id,'number',w.work_number,
    'kind',case when w.delivery_id is not null then 'DELIVERY' else 'SERVICE_JOB' end,
    'state',w.execution_state,'version',w.version,'title',w.title,'description',s.description,
    'scheduled_start',w.scheduled_start,'scheduled_end',w.scheduled_end,
    'quantity',s.planned_quantity::text,'unit',s.unit_label,
    'customer_name',coalesce(d.customer_name_snapshot,customer->>'display_name'),
    'site_name',coalesce(d.site_name_snapshot,site->>'name'),
    'address',coalesce(d.delivery_address_snapshot,site->>'address_text'),
    'receiver_name',coalesce(d.receiver_name_snapshot,site->>'receiver_name'),
    'receiver_phone',coalesce(d.receiver_phone_snapshot,site->>'receiver_phone'),
    'access_note',site->>'access_note','receiving_window',site->>'receiving_window','proofs',proofs,
    'delivery',case when d.id is not null then jsonb_build_object('id',d.id,'version',d.version,
      'state',d.execution_state,'assignment_version',source_assignment,'lines',lines) end));
end $function$

CREATE OR REPLACE FUNCTION public.accept_quote_revision(target_revision_id uuid, acceptance_channel text, confirmed_by_name text, evidence_object_path text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare revision public.quotation_revisions%rowtype; quote public.quotations%rowtype; hash text; receipt public.command_receipts%rowtype; acceptance_id uuid;
begin
  select r.* into revision from public.quotation_revisions r where r.id = target_revision_id for update;
  select q.* into quote from public.quotations q where q.id = revision.quotation_id;
  if not (private.has_permission(quote.branch_id, 'quotation.accept') or private.has_customer_membership(quote.customer_id, array['OWNER','FINANCE_CONTACT'])) then raise exception 'forbidden' using errcode = '42501'; end if;
  if acceptance_channel not in ('PORTAL','PHONE','ZALO','EMAIL','OTHER') then raise exception 'invalid_acceptance_channel' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('revision_id', target_revision_id, 'channel', acceptance_channel, 'confirmed_by', confirmed_by_name, 'evidence', evidence_object_path));
  select * into receipt from public.command_receipts where command_receipts.operation_id = accept_quote_revision.operation_id;
  if found then if receipt.command_name <> 'accept_quote_revision' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if revision.state <> 'SENT' or (revision.expires_at is not null and revision.expires_at <= now()) then raise exception 'quote_revision_not_acceptable' using errcode = '23514'; end if;
  insert into public.quotation_acceptances(revision_id, channel, confirmed_by_name, accepted_by_auth_user_id, evidence_object_path)
  values (target_revision_id, acceptance_channel, confirmed_by_name, (select auth.uid()), evidence_object_path) returning id into acceptance_id;
  update public.quotation_revisions set state = 'ACCEPTED', accepted_at = now() where id = target_revision_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'accept_quote_revision', hash, 'quotation_acceptance', acceptance_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), quote.branch_id, 'quotation.accept', 'quotation_revision', target_revision_id,
    operation_id, array['state', 'accepted_at']);
  return acceptance_id;
end
$function$

CREATE OR REPLACE FUNCTION public.activate_branch_operations(target_branch_id uuid, expected_version integer, recovery_accepted boolean, confirmation text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.branch_operational_states%rowtype; old private.operational_state_events%rowtype; intent jsonb;
begin
 if not private.operational_owner(target_branch_id) then raise exception 'forbidden' using errcode='42501';end if;
 if recovery_accepted is distinct from true or operation_id is null
 or confirmation is distinct from 'ACTIVATE:'||target_branch_id::text||':'||expected_version::text
 then raise exception 'operational_activation_confirmation_required' using errcode='22023';end if;
 select * into s from private.branch_operational_states where branch_id=target_branch_id for update;
 intent=jsonb_build_object('action','activate','branch',target_branch_id,'version',expected_version);
 select * into old from private.operational_state_events e where e.operation_id=activate_branch_operations.operation_id;
 if found then
  if old.actor_id is distinct from auth.uid() or old.intent<>intent then raise exception 'operation_payload_conflict' using errcode='PT409';end if;
  return target_branch_id;
 end if;
 if s.state is distinct from 'READY_FOR_ACTIVATION' or s.version is distinct from expected_version
 or not exists(select 1 from private.operational_opening_readbacks r
 join private.operational_opening_packages a on a.id=r.package_id
 join private.operational_recovery_checkpoints c on c.id=a.recovery_id
 where r.id=s.reconciliation_id and a.branch_id=target_branch_id and a.status='RECONCILED'
 and a.recovery_accepted_at is not null and c.expires_at>clock_timestamp())
 then raise exception 'operational_activation_preconditions_failed' using errcode='PT409';end if;
 update private.branch_operational_states set state='ACTIVE',version=version+1,updated_by=auth.uid(),
 updated_at=clock_timestamp(),activation_operation_id=operation_id where branch_id=target_branch_id;
 insert into private.operational_state_events values(operation_id,target_branch_id,auth.uid(),intent,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,reason)
 values(auth.uid(),target_branch_id,'operational.branch.activated','branch',target_branch_id,operation_id,
 'Explicit Owner activation after accepted opening reconciliation and recovery');
 return target_branch_id;
end $function$

CREATE OR REPLACE FUNCTION public.adjust_return_receivable(target_return_case_id uuid, credit_amount_vnd bigint, adjustment_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare case_row public.return_cases%rowtype; vl public.delivery_verification_lines%rowtype; l public.delivery_lines%rowtype;
 obligation public.receivable_obligations%rowtype; receipt public.command_receipts%rowtype; hash text;
 payment_ids uuid[]; credit_id uuid:=gen_random_uuid(); adjustment_id uuid; source record; release_id uuid;
 outstanding bigint; owed bigint; left_to_fund bigint; available bigint; part bigint; source_max bigint; prior_credits bigint; prior_return_quantity numeric; customer_id uuid;
begin
 perform private.lock_saved_command_intent(operation_id,'adjust_return_receivable');
 select * into case_row from public.return_cases where id=target_return_case_id for update;
 select * into vl from public.delivery_verification_lines where id=case_row.delivery_verification_line_id;
 select * into l from public.delivery_lines where id=vl.delivery_line_id;
 select o.customer_id into customer_id from public.sales_orders o join public.deliveries d on d.sales_order_id=o.id where d.id=l.delivery_id;
 select * into obligation from public.receivable_obligations where delivery_verification_id=vl.delivery_verification_id;
 if case_row.id is null or case_row.case_kind<>'CUSTOMER_RETURN' or case_row.state<>'RETURNED'
  or not private.has_permission(case_row.branch_id,'finance.ar.adjust') then raise exception 'return_not_adjustable' using errcode='42501';end if;
 hash:=private.command_payload_hash(jsonb_build_object('return_case_id',target_return_case_id,'amount',credit_amount_vnd,'reason',trim(adjustment_reason)));
 select * into receipt from public.command_receipts where command_receipts.operation_id=adjust_return_receivable.operation_id;
 if found then if receipt.command_name<>'adjust_return_receivable' or receipt.payload_hash<>hash then raise exception 'operation_payload_conflict' using errcode='23505';end if;return receipt.result_entity_id;end if;
 if credit_amount_vnd is null or credit_amount_vnd<0 or coalesce(length(trim(adjustment_reason)),0) not between 3 and 500
 then raise exception 'invalid_return_credit' using errcode='22023';end if;
 if exists(select 1 from public.customer_credits c where c.return_case_id=case_row.id)
 then raise exception 'return_credit_already_decided' using errcode='55000';end if;
 if exists(select 1 from public.receivable_adjustments a where a.return_case_id=case_row.id)
 then return private.reconcile_legacy_return_credit(target_return_case_id,credit_amount_vnd,adjustment_reason,operation_id);end if;
 -- Lock the receipts first, then the debt. A new payment appearing in that interval requires a clean retry.
 select coalesce(array_agg(distinct a.payment_id),array[]::uuid[]) into payment_ids from public.payment_allocations a
  where a.receivable_obligation_id=obligation.id and a.amount_delta_vnd>0;
 perform 1 from public.payments p where p.id=any(payment_ids) order by p.id for update;
 perform 1 from public.receivable_obligations o where o.id=obligation.id for update;
 if exists(select 1 from public.payment_allocations a where a.receivable_obligation_id=obligation.id
   and a.amount_delta_vnd>0 and not(a.payment_id=any(payment_ids)))
 then raise exception 'return_payment_sources_changed_retry' using errcode='PT409';end if;
 select coalesce(sum(c.approved_credit_vnd),0)::bigint,coalesce(sum(r.base_quantity),0) into prior_credits,prior_return_quantity
  from public.customer_credits c join public.return_cases r on r.id=c.return_case_id where r.delivery_verification_line_id=vl.id;
 source_max:=private.return_credit_source_limit(case_row.id);
 if credit_amount_vnd>source_max or prior_credits+credit_amount_vnd>vl.receivable_amount_vnd
 then raise exception 'return_credit_exceeds_source' using errcode='23514';end if;
 outstanding:=case when obligation.id is null then 0 else private.current_receivable_outstanding(obligation.id) end;
 if outstanding<0 then raise exception 'legacy_negative_receivable_requires_reconciliation' using errcode='55000';end if;
 owed:=greatest(0,credit_amount_vnd-outstanding);left_to_fund:=owed;
 if credit_amount_vnd>0 then
  insert into public.receivable_adjustments(obligation_id,amount_delta_vnd,reason,recorded_by,return_case_id,adjustment_kind)
   values(obligation.id,-credit_amount_vnd,trim(adjustment_reason),(select auth.uid()),case_row.id,'RETURN') returning id into adjustment_id;
 end if;
 insert into public.customer_credits(id,branch_id,customer_id,return_case_id,obligation_id,receivable_adjustment_id,approved_credit_vnd,amount_vnd,reason,approved_by)
 values(credit_id,case_row.branch_id,customer_id,case_row.id,obligation.id,adjustment_id,credit_amount_vnd,owed,trim(adjustment_reason),(select auth.uid()));
 for source in select a.* from public.payment_allocations a join public.payments p on p.id=a.payment_id
  where a.receivable_obligation_id=obligation.id and a.amount_delta_vnd>0 and p.direction='RECEIPT'
  and p.reversal_of_payment_id is null and not exists(select 1 from public.payments r where r.reversal_of_payment_id=p.id)
  order by a.payment_id,a.id loop
  exit when left_to_fund=0;
  select(source.amount_delta_vnd+coalesce(sum(a.amount_delta_vnd),0))::bigint into available from public.payment_allocations a where a.reversal_of_allocation_id=source.id;
  part:=least(left_to_fund,available);if part<=0 then continue;end if;
  insert into public.payment_allocations(payment_id,receivable_obligation_id,amount_delta_vnd,reversal_of_allocation_id,allocated_by,source_customer_credit_id)
   values(source.payment_id,obligation.id,-part,source.id,(select auth.uid()),credit_id) returning id into release_id;
  insert into public.customer_credit_funds(credit_id,source_payment_id,released_allocation_id,amount_vnd) values(credit_id,source.payment_id,release_id,part);
  left_to_fund:=left_to_fund-part;
 end loop;
 if left_to_fund<>0 then raise exception 'return_credit_payment_source_missing' using errcode='23514';end if;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values((select auth.uid()),case_row.branch_id,'customer.credit_approved','customer_credit',credit_id,operation_id,
   array['source_return','receivable_adjustment','released_allocations','credit_funds'],trim(adjustment_reason));
 insert into public.command_receipts values(operation_id,(select auth.uid()),'adjust_return_receivable',hash,
  case when adjustment_id is null then 'customer_credit' else 'receivable_adjustment' end,coalesce(adjustment_id,credit_id),now());
 return coalesce(adjustment_id,credit_id);
end $function$

CREATE OR REPLACE FUNCTION public.advance_report_export_job(target_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  job public.report_export_jobs%rowtype;
  item record;
  batch jsonb := '[]'::jsonb;
  batch_count integer := 0;
  more_rows boolean := false;
begin
  select * into job from public.report_export_jobs where id = target_job_id for update;
  if not found or job.owner_user_id is distinct from auth.uid()
     or not private.has_permission(job.branch_id, case job.side when 'AR' then 'finance.ar.read' else 'finance.ap.read' end)
  then raise exception 'report_export_forbidden' using errcode = '42501'; end if;

  if job.state in ('COMPLETED', 'FAILED') or job.next_run_at > now()
     or (job.lease_until is not null and job.lease_until > now()) then
    return jsonb_build_object('id', job.id, 'state', job.state, 'processedRows', job.processed_rows,
      'attempt', job.attempt, 'safeError', job.safe_error, 'nextRunAt', job.next_run_at);
  end if;

  update public.report_export_jobs set state = 'RUNNING', attempt = attempt + 1,
    lease_until = now() + interval '30 seconds', updated_at = now() where id = job.id;
  begin
    for item in
      select obligation_id, party_name, site_name, source_type, due_date, outstanding_amount_vnd
      from public.finance_obligation_snapshot(
        target_branch_id := job.branch_id,
        target_side := job.side,
        as_of := ((job.as_of_date + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh') - interval '1 millisecond',
        knowledge_cutoff := job.knowledge_cutoff,
        target_customer_id := job.customer_id,
        target_site_id := null,
        target_sales_employee_id := null
      )
      where outstanding_amount_vnd > 0
      order by outstanding_amount_vnd desc, obligation_id
      offset job.processed_rows limit 501
    loop
      if batch_count = 500 then more_rows := true; exit; end if;
      batch := batch || jsonb_build_object(
        'id', item.obligation_id,
        'label', item.party_name,
        'context', concat(coalesce(item.site_name, item.source_type), ' · ', item.source_type),
        'date', item.due_date,
        'amountVnd', item.outstanding_amount_vnd::text
      );
      batch_count := batch_count + 1;
    end loop;

    update public.report_export_jobs set
      rows_json = rows_json || batch,
      processed_rows = processed_rows + batch_count,
      consecutive_failures = 0,
      state = case when more_rows then 'PENDING' else 'COMPLETED' end,
      next_run_at = now(), lease_until = null, safe_error = null, updated_at = now()
    where id = job.id;
  exception when others then
    update public.report_export_jobs set
      consecutive_failures = consecutive_failures + 1,
      state = case when consecutive_failures + 1 >= 3 then 'FAILED' else 'PENDING' end,
      next_run_at = now() + interval '30 seconds', lease_until = null,
      safe_error = 'Không thể xử lý lô xuất file. Có thể thử lại sau.', updated_at = now()
    where id = job.id;
  end;

  select * into job from public.report_export_jobs where id = target_job_id;
  return jsonb_build_object('id', job.id, 'state', job.state, 'processedRows', job.processed_rows,
    'attempt', job.attempt, 'safeError', job.safe_error, 'nextRunAt', job.next_run_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.allocate_payment(target_payment_id uuid, allocation_lines jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment public.payments%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into payment from public.payments where id = target_payment_id;
  if payment.id is null or not private.has_permission(payment.branch_id, 'finance.payment.post') then raise exception 'forbidden_or_payment_not_found' using errcode = '42501'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('payment_id', target_payment_id, 'allocations', allocation_lines));
  perform private.lock_saved_command_intent(allocate_payment.operation_id,'allocate_payment');
  select * into payment from public.payments where id=target_payment_id for update;
  select * into receipt from public.command_receipts where command_receipts.operation_id = allocate_payment.operation_id;
  if found then
    if receipt.command_name <> 'allocate_payment' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  select * into payment from public.payments where id = target_payment_id for update;
  if payment.reversal_of_payment_id is not null or exists (select 1 from public.payments where reversal_of_payment_id = payment.id) then
    raise exception 'payment_not_allocatable' using errcode = '55000';
  end if;
  if jsonb_typeof(allocation_lines) is distinct from 'array' or jsonb_array_length(allocation_lines) not between 1 and 50
   then raise exception 'invalid_allocations' using errcode='22023';end if;
  perform private.allocate_payment_lines(payment.id, allocation_lines, (select auth.uid()));
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'allocate_payment', payload_hash, 'payment', payment.id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), payment.branch_id, 'payment.allocated', 'payment', payment.id, operation_id, array['allocations']);
  return payment.id;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_route_plan(target_route_plan_id uuid, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  plan public.route_plans%rowtype;
  stop record;
  delivery public.deliveries%rowtype;
  current_assignment_version integer;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into plan from public.route_plans p where p.id = target_route_plan_id for update;
  if plan.id is null or not private.has_permission(plan.branch_id, 'delivery.assign') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('route_plan_id', target_route_plan_id, 'version', expected_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = apply_route_plan.operation_id;
  if found then
    if receipt.command_name <> 'apply_route_plan' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  if plan.status <> 'DRAFT' or plan.version  IS DISTINCT FROM expected_version then
    raise exception 'route_plan_version_conflict' using errcode = 'PT409';
  end if;

  for stop in
    select s.* from public.route_plan_stops s where s.route_plan_id = plan.id order by s.stop_order for update
  loop
    select * into delivery from public.deliveries d where d.id = stop.delivery_id for update;
    if delivery.id is null or delivery.branch_id <> plan.branch_id or delivery.execution_state not in ('PLANNED','ASSIGNED')
      or delivery.version  IS DISTINCT FROM stop.expected_delivery_version then
      raise exception 'route_delivery_stale' using errcode = 'PT409';
    end if;
    select coalesce(max(a.assignment_version), 0) into current_assignment_version
      from public.delivery_assignments a where a.delivery_id = delivery.id and a.superseded_at is null;
    if current_assignment_version  IS DISTINCT FROM stop.expected_assignment_version then
      raise exception 'route_assignment_stale' using errcode = 'PT409';
    end if;
    perform public.assign_delivery(
      delivery.id,
      plan.driver_employee_id,
      plan.vehicle_id,
      null::text,
      null::text,
      delivery.version,
      gen_random_uuid()
    );
  end loop;

  update public.route_plans
    set status = 'APPLIED', version = version + 1, applied_by = (select auth.uid()), applied_at = now(), apply_operation_id = apply_route_plan.operation_id
    where id = plan.id;
  insert into public.command_receipts values (apply_route_plan.operation_id, (select auth.uid()), 'apply_route_plan', payload_hash, 'route_plan', plan.id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), plan.branch_id, 'route_plan.applied', 'route_plan', plan.id, apply_route_plan.operation_id,
    array['delivery_assignments','vehicle','driver']);
  return plan.id;
end
$function$

CREATE OR REPLACE FUNCTION public.approve_earning_event(target_earning_event_id uuid, approved_amount_vnd bigint, due_date date, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare earning public.earning_events%rowtype; basis public.compensation_manual_bases%rowtype; payload_hash text; receipt public.command_receipts%rowtype; payable_id uuid; adjustment_id uuid; outstanding bigint;
begin
  select * into earning from public.earning_events where id=target_earning_event_id;
  if earning.id is null or not private.has_permission(earning.branch_id,'compensation.approve') then raise exception 'forbidden_or_earning_not_found' using errcode='42501'; end if;
  if approved_amount_vnd=0 or due_date is null or sign(approved_amount_vnd)<>sign(earning.calculated_amount_vnd) or abs(approved_amount_vnd)>abs(earning.calculated_amount_vnd) then raise exception 'invalid_approved_amount' using errcode='22023'; end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('earning',target_earning_event_id,'amount',approved_amount_vnd,'due',due_date,'version',expected_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id=approve_earning_event.operation_id;
  if found then if receipt.command_name<>'approve_earning_event' or receipt.payload_hash<>payload_hash then raise exception 'operation_payload_conflict' using errcode='23505'; end if; return receipt.result_entity_id; end if;
  select * into earning from public.earning_events where id=target_earning_event_id for update;
  if earning.version IS DISTINCT FROM expected_version then raise exception 'stale_earning_version' using errcode = 'PT409'; end if;
  if earning.approval_state<>'DRAFT' then raise exception 'earning_already_approved' using errcode='55000'; end if;
  if approved_amount_vnd>0 then
    insert into public.payable_obligations(branch_id,supplier_id,employee_id,opening_source_id,purchase_receipt_id,supplier_fulfillment_id,expense_id,earning_event_id,original_amount_vnd,due_date,recorded_by) values(earning.branch_id,null,earning.employee_id,null,null,null,null,earning.id,approved_amount_vnd,due_date,(select auth.uid())) returning id into payable_id;
  else
    select b.* into basis from public.compensation_manual_bases b where b.id=earning.manual_basis_id;
    select p.id into payable_id from public.payable_obligations p where p.earning_event_id=basis.adjusts_earning_event_id for update;
    if payable_id is null then raise exception 'adjusted_payable_not_found' using errcode='23503'; end if;
    outstanding:=private.current_payable_outstanding(payable_id);
    if outstanding+approved_amount_vnd<0 then raise exception 'adjustment_exceeds_payable_outstanding' using errcode='23514'; end if;
    insert into public.payable_adjustments(obligation_id,amount_delta_vnd,reason,evidence_object_id,recorded_by) values(payable_id,approved_amount_vnd,basis.description,basis.evidence_object_id,(select auth.uid())) returning id into adjustment_id;
  end if;
  update public.earning_events set approved_amount_vnd=approve_earning_event.approved_amount_vnd,approval_state='APPROVED',version=version+1,approved_by=(select auth.uid()),approved_at=now(),payable_obligation_id=case when approve_earning_event.approved_amount_vnd>0 then payable_id else null end,payable_adjustment_id=adjustment_id where id=earning.id;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'approve_earning_event',payload_hash,'earning_event',earning.id,now());
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values((select auth.uid()),earning.branch_id,'earning.approved','earning_event',earning.id,operation_id,array['approved_amount_vnd','payable_effect']);
  return earning.id;
end $function$

CREATE OR REPLACE FUNCTION public.approve_expense(target_expense_id uuid, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  expense public.expenses%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  perform private.lock_saved_command_intent(operation_id,'approve_expense');
  perform pg_advisory_xact_lock(hashtextextended('approve_expense:'||operation_id::text,0));
  select * into expense from public.expenses where id = target_expense_id;
  if expense.id is null or not private.has_permission(expense.branch_id, 'finance.expense.manage') then raise exception 'forbidden_or_expense_not_found' using errcode = '42501'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('expense_id', target_expense_id, 'version', expected_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = approve_expense.operation_id;
  if found then
    if receipt.command_name <> 'approve_expense' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  select * into expense from public.expenses where id = target_expense_id for update;
  if expense.approval_state <> 'DRAFT' or expense.version  IS DISTINCT FROM expected_version then raise exception 'expense_version_conflict' using errcode = 'PT409'; end if;
  if expense.evidence_object_id is not null then perform private.assert_verified_evidence(expense.evidence_object_id, expense.branch_id); end if;
  update public.expenses set approval_state = 'APPROVED', version = version + 1, approved_by = (select auth.uid()), approved_at = now() where id = expense.id;
  insert into public.payable_obligations(branch_id, supplier_id, expense_id, original_amount_vnd, due_date, recorded_at, recorded_by)
  values (expense.branch_id, expense.supplier_id, expense.id, expense.amount_vnd, expense.due_date, now(), (select auth.uid()));
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'approve_expense', payload_hash, 'expense', expense.id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), expense.branch_id, 'expense.approved', 'expense', expense.id, operation_id, array['approval_state','version']);
  return expense.id;
end
$function$

CREATE OR REPLACE FUNCTION public.approve_invoice_business(target_invoice_id uuid, expected_version integer, review_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  invoice public.invoice_intents%rowtype;
  line_total bigint;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  perform private.lock_saved_command_intent(operation_id,'approve_invoice_business');
  perform pg_advisory_xact_lock(hashtextextended('document:'||operation_id::text,0));
  select * into invoice from public.invoice_intents i where i.id = target_invoice_id for update;
  if invoice.id is null or not private.has_permission(invoice.branch_id, 'finance.reconcile') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('invoice_id', target_invoice_id, 'version', expected_version, 'reason', trim(review_reason)));
  select * into receipt from public.command_receipts where command_receipts.operation_id = approve_invoice_business.operation_id;
  if found then
    if receipt.command_name <> 'approve_invoice_business' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  if invoice.status <> 'DRAFT' or invoice.version  IS DISTINCT FROM expected_version then
    raise exception 'invoice_version_conflict' using errcode = 'PT409';
  end if;
  if char_length(trim(review_reason)) not between 3 and 500 then
    raise exception 'invoice_review_reason_required' using errcode = '22023';
  end if;
  select coalesce(sum(l.source_amount_vnd), 0)::bigint into line_total from public.invoice_draft_lines l where l.invoice_intent_id = invoice.id;
  if line_total <> invoice.source_amount_vnd or not exists (
    select 1 from public.invoice_coverage c where c.invoice_intent_id = invoice.id and c.released_at is null
  ) then raise exception 'invoice_coverage_invalid' using errcode = '23514'; end if;
  update public.invoice_intents i
    set status = 'BUSINESS_APPROVED', version = i.version + 1,
        reviewed_by = (select auth.uid()), reviewed_at = now(), review_reason = trim(approve_invoice_business.review_reason),
        review_operation_id = approve_invoice_business.operation_id
    where i.id = invoice.id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'approve_invoice_business', payload_hash, 'invoice_intent', invoice.id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason)
  values ((select auth.uid()), invoice.branch_id, 'invoice_business.approved', 'invoice_intent', invoice.id, operation_id,
    array['status','reviewed_by'], trim(review_reason));
  return invoice.id;
end
$function$

CREATE OR REPLACE FUNCTION public.approve_operational_opening_import(target_package_id uuid, expected_package_sha256 text, expected_state_version integer, recovery_accepted boolean, confirmation text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.operational_opening_packages%rowtype; s private.branch_operational_states%rowtype;
 intent jsonb; old private.operational_state_events%rowtype;
begin
 select * into a from private.operational_opening_packages where id=target_package_id;
 if not found or not private.operational_owner(a.branch_id) then raise exception 'forbidden' using errcode='42501';end if;
 select * into s from private.branch_operational_states where branch_id=a.branch_id for update;
 select * into a from private.operational_opening_packages where id=target_package_id for update;
 if expected_package_sha256 is distinct from a.package_sha256 or a.actor_id is distinct from auth.uid()
 or recovery_accepted is distinct from true
 or confirmation is distinct from 'FINAL OWNER IMPORT AUTHORIZATION:'||a.id::text||':'||a.package_sha256
 or operation_id is null then raise exception 'opening_owner_confirmation_invalid' using errcode='22023';end if;
 intent=jsonb_build_object('action','approve_opening','package',a.id,'hash',a.package_sha256,'version',expected_state_version);
 select * into old from private.operational_state_events e where e.operation_id=approve_operational_opening_import.operation_id;
 if found then
  if old.actor_id is distinct from auth.uid() or old.intent<>intent then raise exception 'operation_payload_conflict' using errcode='PT409';end if;
  return a.id;
 end if;
 if s.state is distinct from 'PENDING_OPENING' or s.version is distinct from expected_state_version
 or a.status<>'REGISTERED' or a.expires_at<=clock_timestamp()
 or not exists(select 1 from private.operational_recovery_checkpoints r where r.id=a.recovery_id
 and r.branch_id=a.branch_id and r.expires_at>clock_timestamp())
 then raise exception 'opening_approval_preconditions_failed' using errcode='PT409';end if;
 update private.operational_opening_packages set status='APPROVED',approved_by=auth.uid(),
 approved_at=clock_timestamp(),recovery_accepted_at=clock_timestamp() where id=a.id;
 insert into private.operational_state_events values(operation_id,a.branch_id,auth.uid(),intent,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,reason)
 values(auth.uid(),a.branch_id,'operational.opening.authorized','operational_opening_package',a.id,operation_id,
 'Explicit package-bound FINAL OWNER IMPORT AUTHORIZATION; not business activation');
 return a.id;
end $function$

CREATE OR REPLACE FUNCTION public.approve_stock_count(target_stock_count_id uuid, expected_count_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare count_row public.stock_counts%rowtype; line public.stock_count_lines%rowtype; delta numeric;
  current_qty numeric; current_value bigint; reserved_qty numeric; unit_cost numeric; value_delta bigint; hash text; receipt public.command_receipts%rowtype;
begin
  select * into count_row from public.stock_counts where id = target_stock_count_id for update;
  if count_row.id is null or not private.has_permission(count_row.branch_id, 'inventory.adjust') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('count_id', target_stock_count_id, 'version', expected_count_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = approve_stock_count.operation_id;
  if found then if receipt.command_name <> 'approve_stock_count' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if expected_count_version is null or expected_count_version <= 0 or count_row.state <> 'OPEN' or count_row.version  IS DISTINCT FROM expected_count_version or not exists (select 1 from public.stock_count_lines where stock_count_id = target_stock_count_id) then raise exception 'stock_count_not_approvable' using errcode = 'PT409'; end if;
  perform 1 from public.warehouses where id = count_row.warehouse_id for update;
  for line in select * from public.stock_count_lines where stock_count_id = target_stock_count_id order by id loop
    if line.basis_fingerprint is null
      or line.basis_fingerprint is distinct from private.stock_count_basis(count_row.branch_id,count_row.warehouse_id,line.material_id)
    then raise exception 'stock_count_basis_changed_recount_required' using errcode='PT409'; end if;
    delta := line.counted_base_quantity - line.expected_base_quantity;
    if delta <> 0 then
      select coalesce(sum(base_quantity_delta), 0), coalesce(sum(inventory_value_delta_vnd), 0)::bigint
        into current_qty, current_value from public.inventory_movements
        where warehouse_id = count_row.warehouse_id and material_id = line.material_id;
      select coalesce(sum(r.reserved_base_quantity),0) into reserved_qty
        from public.inventory_reservations r where r.branch_id=count_row.branch_id
          and r.warehouse_id=count_row.warehouse_id and r.material_id=line.material_id and r.state='ACTIVE';
      if current_qty+delta<0 or current_qty+delta<reserved_qty
      then raise exception 'stock_count_adjustment_below_reserved_or_on_hand' using errcode='23514'; end if;
      unit_cost := case when delta<0 then case when current_qty>0 then current_value::numeric/current_qty else null end
        else coalesce(line.adjustment_unit_cost_vnd,case when current_qty>0 then current_value::numeric/current_qty else null end) end;
      if unit_cost is null or unit_cost <= 0 then raise exception 'adjustment_cost_required' using errcode = '23514'; end if;
      value_delta := round(delta * unit_cost)::bigint;
      if current_value+value_delta<0
        or ((current_qty+delta=0) is distinct from (current_value+value_delta=0))
      then raise exception 'stock_count_inventory_value_inconsistent' using errcode='23514'; end if;
      if value_delta = 0 then raise exception 'adjustment_value_too_small' using errcode = '23514'; end if;
      insert into public.inventory_movements(branch_id, material_id, base_uom_id, location_kind, warehouse_id,
        movement_type, base_quantity_delta, inventory_value_delta_vnd, unit_cost_vnd_per_base,
        source_stock_count_line_id, occurred_at, recorded_by)
      select count_row.branch_id, line.material_id, m.base_uom_id, 'WAREHOUSE', count_row.warehouse_id,
        'STOCK_ADJUSTMENT', delta, value_delta, unit_cost, line.id, now(), (select auth.uid())
      from public.materials m where m.id = line.material_id;
    end if;
  end loop;
  update public.stock_counts set state = 'APPROVED', version = version + 1, approved_by = (select auth.uid()), approved_at = now() where id = target_stock_count_id;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
  values((select auth.uid()),count_row.branch_id,'stock_count.approved','stock_count',target_stock_count_id,
    approve_stock_count.operation_id,array['state','version','inventory_adjustment']);
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'approve_stock_count', hash, 'stock_count', target_stock_count_id, now());
  return target_stock_count_id;
end
$function$

CREATE OR REPLACE FUNCTION public.approve_supplier_return_credit(target_acceptance_event_id uuid, credit_amount_vnd bigint, approval_reason text, expected_case_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.supplier_return_events%rowtype;c public.supplier_return_cases%rowtype;o public.payable_obligations%rowtype;r public.command_receipts%rowtype;h text;credit_id uuid:=gen_random_uuid();adj_id uuid;release_id uuid;payment_ids uuid[];outstanding bigint;owed bigint;remaining bigint;available bigint;part bigint;source record;
begin
 select * into e from public.supplier_return_events where id=target_acceptance_event_id;select * into c from public.supplier_return_cases where id=e.case_id;
 if e.id is null or e.event_kind<>'SUPPLIER_ACCEPTANCE' or not private.has_permission(c.branch_id,'finance.ap.adjust') then raise exception 'forbidden_or_supplier_acceptance_not_found' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'approve_supplier_return_credit');perform pg_advisory_xact_lock(hashtextextended('supplier_credit:'||operation_id::text,0));
 h:=private.command_payload_hash(jsonb_build_array(target_acceptance_event_id,credit_amount_vnd,trim(approval_reason),expected_case_version));
 select * into r from public.command_receipts where command_receipts.operation_id=approve_supplier_return_credit.operation_id;
 if found then if r.command_name<>'approve_supplier_return_credit' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 select * into c from public.supplier_return_cases where id=e.case_id for update;
 if c.version is distinct from expected_case_version then raise exception 'supplier_return_version_conflict' using errcode='PT409';end if;
 if operation_id is null or credit_amount_vnd is null or credit_amount_vnd<0 or credit_amount_vnd>e.source_value_vnd or approval_reason is null or char_length(trim(approval_reason)) not between 3 and 500 then raise exception 'supplier_credit_exceeds_acceptance_or_invalid' using errcode='23514';end if;
 if exists(select 1 from public.supplier_return_credits x where x.acceptance_event_id=e.id) then raise exception 'supplier_acceptance_credit_already_decided' using errcode='55000';end if;
 select coalesce(array_agg(distinct a.payment_id),array[]::uuid[]) into payment_ids from public.payment_allocations a where a.payable_obligation_id=c.source_payable_id and a.amount_delta_vnd>0;
 perform 1 from public.payments p where p.id=any(payment_ids) order by p.id for update;
 select * into o from public.payable_obligations where id=c.source_payable_id for update;
 if o.supplier_id is distinct from c.supplier_id or o.branch_id is distinct from c.branch_id then raise exception 'supplier_return_payable_scope_mismatch' using errcode='23514';end if;
 if exists(select 1 from public.payment_allocations a where a.payable_obligation_id=o.id and a.amount_delta_vnd>0 and not(a.payment_id=any(payment_ids))) then raise exception 'supplier_return_payment_sources_changed_retry' using errcode='PT409';end if;
 outstanding:=private.current_payable_outstanding(o.id);if outstanding<0 then raise exception 'legacy_negative_payable_requires_reconciliation' using errcode='55000';end if;
 owed:=greatest(0,credit_amount_vnd-outstanding);remaining:=owed;
 if credit_amount_vnd>0 then insert into public.payable_adjustments(obligation_id,amount_delta_vnd,reason,recorded_by) values(o.id,-credit_amount_vnd,trim(approval_reason),auth.uid()) returning id into adj_id;end if;
 insert into public.supplier_return_credits(id,branch_id,supplier_id,acceptance_event_id,case_id,obligation_id,payable_adjustment_id,approved_credit_vnd,amount_vnd,reason,approved_by)
 values(credit_id,c.branch_id,c.supplier_id,e.id,c.id,o.id,adj_id,credit_amount_vnd,owed,trim(approval_reason),auth.uid());
 for source in select a.* from public.payment_allocations a join public.payments p on p.id=a.payment_id where a.payable_obligation_id=o.id and a.amount_delta_vnd>0 and p.direction='DISBURSEMENT'
  and p.reversal_of_payment_id is null and not exists(select 1 from public.payments rev where rev.reversal_of_payment_id=p.id) order by a.payment_id,a.id loop
  exit when remaining=0;
  select(source.amount_delta_vnd+coalesce(sum(a.amount_delta_vnd),0))::bigint into available from public.payment_allocations a where a.reversal_of_allocation_id=source.id;
  part:=least(remaining,available);if part<=0 then continue;end if;
  insert into public.payment_allocations(payment_id,payable_obligation_id,amount_delta_vnd,reversal_of_allocation_id,allocated_by,source_supplier_credit_id)
   values(source.payment_id,o.id,-part,source.id,auth.uid(),credit_id) returning id into release_id;
  insert into public.supplier_credit_funds(credit_id,source_payment_id,released_allocation_id,amount_vnd) values(credit_id,source.payment_id,release_id,part);remaining:=remaining-part;
 end loop;
 if remaining<>0 then raise exception 'supplier_credit_requires_recorded_payment_sources' using errcode='23514';end if;
 update public.supplier_return_cases set version=version+1 where id=c.id;
 insert into public.command_receipts values(operation_id,auth.uid(),'approve_supplier_return_credit',h,'supplier_return_credit',credit_id,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
 values(auth.uid(),c.branch_id,'supplier_return.credit_approved','supplier_return_credit',credit_id,operation_id,array['acceptance_event','payable_adjustment','payment_funding'],trim(approval_reason));
 return credit_id;
end $function$

CREATE OR REPLACE FUNCTION public.assign_delivery(target_delivery_id uuid, target_employee_id uuid, target_vehicle_id uuid, external_carrier_name text, external_carrier_phone text, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare delivery public.deliveries%rowtype; next_assignment_version integer; assignment_id uuid; work public.work_items%rowtype; work_assignment_version integer; hash text; receipt public.command_receipts%rowtype;
begin
  select * into delivery from public.deliveries where id = target_delivery_id for update;
  if delivery.id is null or not private.has_permission(delivery.branch_id, 'delivery.assign') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('delivery_id', target_delivery_id, 'employee_id', target_employee_id, 'vehicle_id', target_vehicle_id, 'external_name', nullif(trim(external_carrier_name), ''), 'external_phone', nullif(trim(external_carrier_phone), ''), 'version', expected_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = assign_delivery.operation_id;
  if found then if receipt.command_name <> 'assign_delivery' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if delivery.execution_state not in ('PLANNED','ASSIGNED') or delivery.version is distinct from expected_version then raise exception 'delivery_assignment_version_conflict' using errcode = 'PT409'; end if;
  if not ((target_employee_id is not null and target_vehicle_id is not null and nullif(trim(external_carrier_name), '') is null)
    or (target_employee_id is null and target_vehicle_id is null and nullif(trim(external_carrier_name), '') is not null)) then raise exception 'invalid_assignment_shape' using errcode = '22023'; end if;
  if target_employee_id is not null and (not exists (select 1 from public.employees e join public.employee_branch_access a on a.employee_id = e.id where e.id = target_employee_id and e.active and a.branch_id = delivery.branch_id and a.active)
    or not exists (select 1 from public.vehicles where id = target_vehicle_id and branch_id = delivery.branch_id and active)) then raise exception 'assignment_resource_invalid' using errcode = '23503'; end if;
  select * into work from public.work_items where delivery_id=delivery.id for update;
  if work.id is not null and(work.execution_state not in('AVAILABLE','CLAIMED') or work.started_at is not null)
  then raise exception 'delivery_reassignment_after_work_started_forbidden' using errcode='PT409';end if;
  if work.id is not null and target_employee_id is null then
   raise exception 'delivery_external_assignment_with_work_forbidden' using errcode='PT409';
  end if;
  if target_employee_id is not null then
   perform private.assert_delivery_resources(delivery.id,target_employee_id,target_vehicle_id,delivery.scheduled_at,
     coalesce(delivery.scheduled_end_at,work.scheduled_end,delivery.scheduled_at+interval '4 hours'));
  end if;
  update public.gps_tracking_sessions set status='REVOKED',stopped_at=now(),stop_reason='assignment_superseded'
   where delivery_id=delivery.id and status='ACTIVE';
  update public.delivery_assignments set superseded_at = now() where delivery_id = target_delivery_id and superseded_at is null;
  select coalesce(max(assignment_version), 0) + 1 into next_assignment_version from public.delivery_assignments where delivery_id = target_delivery_id;
  insert into public.delivery_assignments(delivery_id, assignment_version, employee_id, vehicle_id,
    external_carrier_name, external_carrier_phone, assigned_by)
  values (target_delivery_id, next_assignment_version, target_employee_id, target_vehicle_id,
    nullif(trim(external_carrier_name), ''), nullif(trim(external_carrier_phone), ''), (select auth.uid())) returning id into assignment_id;
  update public.deliveries set execution_state = 'ASSIGNED', scheduled_end_at=coalesce(scheduled_end_at,work.scheduled_end,scheduled_at+interval '4 hours'), version = version + 1 where id = target_delivery_id;
  if work.id is not null then
   update public.work_item_assignments set superseded_at=now() where work_item_id=work.id and superseded_at is null;
   if target_employee_id is null then
    update public.work_items set execution_state='CANCELLED',version=version+1 where id=work.id;
   else
    select coalesce(max(assignment_version),0)+1 into work_assignment_version from public.work_item_assignments where work_item_id=work.id;
    insert into public.work_item_assignments(work_item_id,assignment_version,employee_id,vehicle_id,machine_id,assignment_kind,assigned_by)
     values(work.id,work_assignment_version,target_employee_id,target_vehicle_id,null,'DIRECT',(select auth.uid()));
    update public.work_items set planned_vehicle_id=target_vehicle_id,scheduled_start=delivery.scheduled_at,scheduled_end=coalesce(delivery.scheduled_end_at,work.scheduled_end,delivery.scheduled_at+interval '4 hours'),execution_state='CLAIMED',version=version+1 where id=work.id;
   end if;
  end if;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values((select auth.uid()),delivery.branch_id,'delivery.assigned','delivery',delivery.id,assign_delivery.operation_id,
   array['delivery_assignment','work_assignment','assignment_version','gps_session'],
   case when work.id is not null then 'Đồng bộ phân giao trước khi bắt đầu việc' else 'Phân giao theo kế hoạch' end);
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'assign_delivery', hash, 'delivery_assignment', assignment_id, now());
  return assignment_id;
end
$function$

