  if work.assignment_mode<>'POOL_CLAIM' or work.execution_state<>'AVAILABLE' then raise exception 'work_not_claimable' using errcode='55000'; end if;
  perform private.assert_work_resources_available(work.id,work.branch_id,employee,work.planned_vehicle_id,work.planned_machine_id,work.scheduled_start,work.scheduled_end);
  insert into public.work_item_assignments(work_item_id,assignment_version,employee_id,vehicle_id,machine_id,assignment_kind,assigned_by) values(work.id,1,employee,work.planned_vehicle_id,work.planned_machine_id,'CLAIM',(select auth.uid())) returning id into assignment_id;
  update public.work_items set execution_state='CLAIMED',version=version+1 where id=work.id;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'claim_work_item',payload_hash,'work_item_assignment',assignment_id,now());
  return assignment_id;
end $function$

CREATE OR REPLACE FUNCTION public.close_sales_order_remaining(target_order_id uuid, close_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  order_row public.sales_orders%ROWTYPE;
  receipt public.command_receipts%ROWTYPE;
  payload_hash text;
BEGIN
  SELECT * INTO order_row FROM public.sales_orders WHERE id = target_order_id;
  IF NOT FOUND OR NOT private.has_permission(order_row.branch_id, 'orders.cancel') THEN
    RAISE EXCEPTION 'forbidden_or_order_not_found' USING ERRCODE = '42501';
  END IF;
  IF close_reason IS NULL OR char_length(trim(close_reason)) NOT BETWEEN 3 AND 500 THEN
    RAISE EXCEPTION 'close_reason_required' USING ERRCODE = '22023';
  END IF;
  -- Same allocation -> sales-line -> sales-order lock order as Delivery creation.
  PERFORM 1 FROM public.supply_allocations a
    JOIN public.sales_order_lines l ON l.id = a.sales_order_line_id
    WHERE l.sales_order_id = target_order_id ORDER BY a.id FOR UPDATE OF a;
  PERFORM 1 FROM public.sales_order_lines WHERE sales_order_id = target_order_id ORDER BY id FOR UPDATE;
  SELECT * INTO order_row FROM public.sales_orders WHERE id = target_order_id FOR UPDATE;
  IF NOT private.has_permission(order_row.branch_id, 'orders.cancel') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  payload_hash := private.command_payload_hash(jsonb_build_object('order_id', target_order_id, 'reason', trim(close_reason)));
  SELECT * INTO receipt FROM public.command_receipts r WHERE r.operation_id = close_sales_order_remaining.operation_id;
  IF FOUND THEN
    IF receipt.command_name <> 'close_sales_order_remaining' OR receipt.payload_hash <> payload_hash
      OR receipt.actor_auth_user_id <> (SELECT auth.uid()) THEN
      RAISE EXCEPTION 'operation_payload_conflict' USING ERRCODE = '23505';
    END IF;
    RETURN receipt.result_entity_id;
  END IF;
  IF order_row.commercial_state <> 'CONFIRMED' THEN
    RAISE EXCEPTION 'sales_order_not_closeable' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.deliveries d WHERE d.sales_order_id = target_order_id AND d.execution_state NOT IN ('VERIFIED', 'CANCELLED'))
    OR EXISTS (SELECT 1 FROM public.return_cases r JOIN public.delivery_lines l ON l.id = r.delivery_line_id
      JOIN public.deliveries d ON d.id = l.delivery_id WHERE d.sales_order_id = target_order_id AND r.state = 'OPEN')
    OR EXISTS (SELECT 1 FROM public.work_items w JOIN public.deliveries d ON d.id = w.delivery_id
      WHERE d.sales_order_id = target_order_id AND w.execution_state NOT IN ('VERIFIED', 'CANCELLED'))
    OR EXISTS (SELECT 1 FROM public.inventory_movements m JOIN public.deliveries d ON d.id = m.delivery_id
      WHERE d.sales_order_id = target_order_id AND m.location_kind = 'IN_TRANSIT'
      GROUP BY m.delivery_id, m.material_id, m.base_uom_id
      HAVING sum(m.base_quantity_delta) <> 0 OR sum(m.inventory_value_delta_vnd) <> 0) THEN
    RAISE EXCEPTION 'sales_order_unresolved_execution' USING ERRCODE = 'PT409';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sales_order_lines l WHERE l.sales_order_id = target_order_id
    AND l.quantity * l.conversion_numerator / l.conversion_denominator > coalesce((
      SELECT sum(v.accepted_base_quantity) FROM public.delivery_verification_lines v
        JOIN public.delivery_lines dl ON dl.id = v.delivery_line_id
        JOIN public.deliveries d ON d.id = dl.delivery_id
      WHERE dl.sales_order_line_id = l.id AND d.execution_state = 'VERIFIED'), 0)) THEN
    RAISE EXCEPTION 'sales_order_has_no_remaining' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.customers WHERE id = order_row.customer_id FOR UPDATE;
  UPDATE public.inventory_reservations r SET state = 'RELEASED', version = r.version + 1, finalized_at = now()
    WHERE r.state = 'ACTIVE' AND r.sales_order_line_id IN (SELECT id FROM public.sales_order_lines WHERE sales_order_id = target_order_id);
  UPDATE public.credit_commitments SET released_vnd = amount_vnd - consumed_vnd WHERE sales_order_id = target_order_id;
  UPDATE public.sales_orders SET commercial_state = 'CLOSED' WHERE id = target_order_id;
  INSERT INTO public.command_receipts VALUES (operation_id, (SELECT auth.uid()), 'close_sales_order_remaining', payload_hash, 'sales_order', target_order_id, now());
  INSERT INTO public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason)
    VALUES ((SELECT auth.uid()), order_row.branch_id, 'sales_order.remaining.close', 'sales_order', target_order_id, operation_id,
      ARRAY['commercial_state', 'credit_commitment', 'inventory_reservation'], trim(close_reason));
  RETURN target_order_id;
END
$function$

CREATE OR REPLACE FUNCTION public.configure_compensation_recognition(target_rule_id uuid, recognition_kind text, effective_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.compensation_rules%rowtype; p public.compensation_recognition_policies%rowtype;
  h text; receipt public.command_receipts%rowtype;
begin
  select * into r from public.compensation_rules where id=target_rule_id;
  if r.id is null or not private.has_permission(r.branch_id,'compensation.manage')
    or not private.has_permission(r.branch_id,'compensation.approve') then
    raise exception 'forbidden_or_rule_not_found' using errcode='42501';
  end if;
  if r.employee_id is null or effective_at is null or not isfinite(effective_at)
    or recognition_kind not in ('AR_PAYMENT_ALLOCATION','WORK_ITEM_VERIFICATION')
    or (effective_at at time zone 'Asia/Ho_Chi_Minh')::date<r.effective_from
    or (r.effective_to is not null and (effective_at at time zone 'Asia/Ho_Chi_Minh')::date>r.effective_to)
    or (recognition_kind='AR_PAYMENT_ALLOCATION' and (r.earning_type<>'SALES_COMMISSION' or r.calculation_kind<>'PERCENT_BPS'))
    or (recognition_kind='WORK_ITEM_VERIFICATION' and (r.earning_type not in ('PER_JOB','PER_TRIP') or r.calculation_kind<>'FIXED_PER_BASIS')) then
    raise exception 'invalid_recognition_policy' using errcode='22023';
  end if;
  h:=private.command_payload_hash(jsonb_build_object('rule',target_rule_id,'kind',recognition_kind,'effective_at',effective_at));
  select * into receipt from public.command_receipts c where c.operation_id=configure_compensation_recognition.operation_id;
  if found then
    if receipt.command_name<>'configure_compensation_recognition' or receipt.payload_hash<>h then raise exception 'operation_payload_conflict' using errcode='PT409'; end if;
    return receipt.result_entity_id;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(r.branch_id::text||':'||r.employee_id::text||':'||recognition_kind,0));
  select * into p from public.compensation_recognition_policies where rule_id=r.id;
  if p.rule_id is not null then
    if p.recognition_kind<>configure_compensation_recognition.recognition_kind or p.effective_at<>configure_compensation_recognition.effective_at then
      raise exception 'recognition_policy_conflict' using errcode='PT409'; end if;
  else
    if exists(select 1 from public.compensation_recognition_policies x where x.branch_id=r.branch_id and x.employee_id=r.employee_id and x.recognition_kind=configure_compensation_recognition.recognition_kind) then
      raise exception 'recognition_policy_already_configured' using errcode='PT409'; end if;
    insert into public.compensation_recognition_policies(rule_id,branch_id,employee_id,recognition_kind,effective_at,approved_by)
      values(r.id,r.branch_id,r.employee_id,recognition_kind,effective_at,(select auth.uid()));
    insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
      values((select auth.uid()),r.branch_id,'compensation.recognition.approved','compensation_rule',r.id,operation_id,array['recognition_kind','effective_at']);
  end if;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'configure_compensation_recognition',h,'compensation_rule',r.id,now());
  return r.id;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_purchase_order(target_purchase_order_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_row public.purchase_orders%rowtype; hash text; receipt public.command_receipts%rowtype;
begin
  select * into order_row from public.purchase_orders where id = target_purchase_order_id for update;
  if not private.has_permission(order_row.branch_id, 'purchasing.confirm') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('purchase_order_id', target_purchase_order_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = confirm_purchase_order.operation_id;
  if found then if receipt.command_name <> 'confirm_purchase_order' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if order_row.state <> 'DRAFT' or not exists (select 1 from public.purchase_order_lines where purchase_order_id = target_purchase_order_id) then raise exception 'purchase_order_not_confirmable' using errcode = '23514'; end if;
  update public.purchase_orders set state = 'CONFIRMED', confirmed_at = now() where id = target_purchase_order_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'confirm_purchase_order', hash, 'purchase_order', target_purchase_order_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), order_row.branch_id, 'purchase_order.confirm', 'purchase_order', target_purchase_order_id, operation_id, array['state']);
  return target_purchase_order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_sales_order(target_order_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_row public.sales_orders%rowtype; hash text; receipt public.command_receipts%rowtype; commitment_id uuid;
begin
  select * into order_row from public.sales_orders where id = target_order_id for update;
  if not private.has_permission(order_row.branch_id, 'orders.confirm') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('order_id', target_order_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = confirm_sales_order.operation_id;
  if found then if receipt.command_name <> 'confirm_sales_order' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if order_row.commercial_state <> 'DRAFT' then raise exception 'sales_order_not_confirmable' using errcode = '23514'; end if;
  commitment_id := private.reserve_sales_order_credit(target_order_id, (select auth.uid()));
  update public.sales_orders set commercial_state = 'CONFIRMED', confirmed_at = now() where id = target_order_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'confirm_sales_order', hash, 'sales_order', target_order_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), order_row.branch_id, 'sales_order.confirm', 'sales_order', target_order_id, operation_id, array['commercial_state','credit_commitment']);
  return target_order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_sales_order_with_credit_override(target_order_id uuid, override_reason text, expected_snapshot_hash text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.sales_orders%rowtype; snapshot jsonb; hash text; actor uuid := (select auth.uid());
  receipt public.command_receipts%rowtype; commitment uuid; amount bigint; exposure bigint;
  approved_limit bigint; overdue bigint; normalized_reason text := btrim(override_reason);
begin
  select * into o from public.sales_orders where id = target_order_id for update;
  if actor is null or not found or not private.has_permission(o.branch_id, 'orders.confirm')
    or not private.has_permission(o.branch_id, 'finance.ar.adjust') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if operation_id is null or normalized_reason is null
    or char_length(normalized_reason) not between 3 and 500
    or expected_snapshot_hash is null or expected_snapshot_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'credit_override_input_invalid' using errcode = '22023';
  end if;
  hash := private.command_payload_hash(jsonb_build_object('order_id', target_order_id,
    'reason', normalized_reason, 'snapshot_hash', expected_snapshot_hash, 'actor', actor));
  select * into receipt from public.command_receipts r
    where r.operation_id = confirm_sales_order_with_credit_override.operation_id;
  if found then
    if receipt.command_name <> 'confirm_sales_order_with_credit_override'
      or receipt.payload_hash <> hash or receipt.actor_auth_user_id <> actor then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  if o.commercial_state <> 'DRAFT' then
    raise exception 'sales_order_not_confirmable' using errcode = '23514';
  end if;
  -- Same customer lock as ordinary confirmation. Recompute AFTER acquiring it.
  perform 1 from public.customers where id = o.customer_id and branch_id = o.branch_id and active for update;
  if not found then raise exception 'customer_not_active' using errcode = '23514'; end if;
  snapshot := private.sales_order_credit_snapshot(target_order_id);
  if private.command_payload_hash(snapshot) <> expected_snapshot_hash then
    raise exception 'credit_snapshot_changed' using errcode = '40001';
  end if;
  amount := (snapshot->>'order_amount_vnd')::bigint;
  exposure := (snapshot->>'exposure_vnd')::bigint;
  approved_limit := (snapshot->>'approved_limit_vnd')::bigint;
  overdue := (snapshot->>'overdue_vnd')::bigint;
  if amount <= 0 then raise exception 'sales_order_amount_invalid' using errcode = '23514'; end if;
  if approved_limit is not null and overdue <= 0 and exposure + amount <= approved_limit then
    raise exception 'credit_override_not_required' using errcode = '23514';
  end if;
  insert into public.credit_commitments(branch_id, customer_id, source_type, source_key,
    sales_order_id, amount_vnd, created_by)
  values (o.branch_id, o.customer_id, 'SALES_ORDER', o.id::text, o.id, amount, actor)
    returning id into commitment;
  update public.sales_orders set commercial_state = 'CONFIRMED', confirmed_at = now() where id = o.id;
  insert into public.command_receipts values (operation_id, actor,
    'confirm_sales_order_with_credit_override', hash, 'sales_order', o.id, now());
  insert into public.sales_order_credit_overrides(sales_order_id, branch_id, customer_id,
    commitment_id, operation_id, actor_auth_user_id, reason, approved_limit_vnd,
    exposure_before_vnd, order_amount_vnd, exposure_after_vnd, overdue_vnd, snapshot_hash)
  values (o.id, o.branch_id, o.customer_id, commitment, operation_id, actor, normalized_reason,
    approved_limit, exposure, amount, exposure + amount, overdue, expected_snapshot_hash);
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id,
    trace_id, changed_fields, reason)
  values (actor, o.branch_id, 'sales_order.confirm_credit_override', 'sales_order', o.id,
    operation_id, array['commercial_state','credit_commitment','credit_override_snapshot'], normalized_reason);
  return o.id;
end
$function$

CREATE OR REPLACE FUNCTION public.conversation_list_for_scope(target_branch_id uuid, target_customer_id uuid, before_updated_at timestamp with time zone, before_id uuid, page_size integer)
 RETURNS TABLE(conversation_id uuid, branch_id uuid, audience text, customer_id uuid, subject text, entity_type text, entity_id uuid, participant_summary text, last_message_preview text, last_message_at timestamp with time zone, updated_at timestamp with time zone, unread_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bounded_size integer;
begin
  if (target_branch_id is null) = (target_customer_id is null) then
    raise exception 'conversation_scope_invalid' using errcode = '22023';
  end if;
  if target_branch_id is not null and not private.has_branch_access(target_branch_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if target_customer_id is not null and not exists (
    select 1 from public.customer_portal_memberships m
    where m.customer_id = target_customer_id and m.auth_user_id = (select auth.uid()) and m.active
  ) then raise exception 'forbidden' using errcode = '42501'; end if;
  bounded_size := least(50, greatest(1, coalesce(page_size, 25)));
  return query
    select c.id, c.branch_id, c.audience, c.customer_id, c.subject, c.entity_type, c.entity_id,
      c.participant_summary, c.last_message_preview, c.last_message_at, c.updated_at, p.unread_count
    from public.conversation_participants p
    join public.conversations c on c.id = p.conversation_id
    where p.auth_user_id = (select auth.uid()) and p.active
      and ((target_branch_id is not null and c.branch_id = target_branch_id)
        or (target_customer_id is not null and c.customer_id = target_customer_id and c.audience = 'CUSTOMER'))
      and (before_updated_at is null or (c.updated_at, c.id) < (before_updated_at, before_id))
    order by c.updated_at desc, c.id desc
    limit bounded_size;
end
$function$

CREATE OR REPLACE FUNCTION public.create_compensation_rule(target_branch_id uuid, rule_code text, rule_name text, target_employee_id uuid, earning_type text, calculation_kind text, rate_vnd_per_unit numeric, rate_bps integer, classification text, effective_from date, effective_to date, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload_hash text; receipt public.command_receipts%rowtype; entity_id uuid; next_version integer;
begin
  if not private.has_permission(target_branch_id,'compensation.manage') then raise exception 'forbidden' using errcode='42501'; end if;
  if upper(trim(rule_code))!~'^[A-Z0-9_-]{2,32}$' or char_length(trim(rule_name)) not between 2 and 160 or earning_type not in ('FIXED_MONTHLY','PER_JOB','PER_TRIP','PER_HOUR','PER_SHIFT','PER_DAY','PER_TON','PER_M3','PER_BAG','PER_UNIT','BONUS','ADJUSTMENT','SALES_COMMISSION') or calculation_kind not in ('FIXED_PER_BASIS','PERCENT_BPS') or classification not in ('DIRECT_LABOR','OPEX','SALES_COMMISSION') then raise exception 'invalid_compensation_rule' using errcode='22023'; end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('branch',target_branch_id,'code',upper(trim(rule_code)),'name',trim(rule_name),'employee',target_employee_id,'type',earning_type,'calculation',calculation_kind,'rate',rate_vnd_per_unit,'bps',rate_bps,'classification',classification,'from',effective_from,'to',effective_to));
  select * into receipt from public.command_receipts where command_receipts.operation_id=create_compensation_rule.operation_id;
  if found then if receipt.command_name<>'create_compensation_rule' or receipt.payload_hash<>payload_hash then raise exception 'operation_payload_conflict' using errcode='23505'; end if; return receipt.result_entity_id; end if;
  if target_employee_id is not null then perform 1 from public.employee_branch_access where employee_id=target_employee_id and branch_id=target_branch_id and active; if not found then raise exception 'invalid_rule_employee' using errcode='23503'; end if; end if;
  perform pg_advisory_xact_lock(hashtextextended(target_branch_id::text||':'||upper(trim(rule_code)),0));
  select coalesce(max(version),0)+1 into next_version from public.compensation_rules where branch_id=target_branch_id and code=upper(trim(rule_code));
  insert into public.compensation_rules(branch_id,code,name,version,employee_id,earning_type,calculation_kind,rate_vnd_per_unit,rate_bps,classification,effective_from,effective_to,created_by) values(target_branch_id,upper(trim(rule_code)),trim(rule_name),next_version,target_employee_id,earning_type,calculation_kind,rate_vnd_per_unit,rate_bps,classification,effective_from,effective_to,(select auth.uid())) returning id into entity_id;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'create_compensation_rule',payload_hash,'compensation_rule',entity_id,now());
  return entity_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_conversation(target_branch_id uuid, target_audience text, target_customer_id uuid, target_subject text, target_entity_type text, target_entity_id uuid, target_participant_auth_user_ids uuid[], operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  conversation_id uuid;
  participant_auth_user_id uuid;
  participant_kind text;
  participant_display text;
  participant_ids uuid[];
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  if (select auth.uid()) is null or not private.has_branch_access(target_branch_id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if target_audience not in ('INTERNAL','CUSTOMER') or char_length(trim(target_subject)) not between 3 and 160
    or char_length(trim(target_entity_type)) not between 2 and 80 or target_entity_id is null then
    raise exception 'invalid_conversation' using errcode = '22023';
  end if;
  if target_audience = 'CUSTOMER' then
    if not private.has_permission(target_branch_id, 'customers.read') then
      raise exception 'forbidden' using errcode = '42501';
    end if;
    if target_customer_id is null or not exists (
      select 1 from public.customers c where c.id = target_customer_id and c.branch_id = target_branch_id and c.active
    ) then raise exception 'conversation_customer_invalid' using errcode = '23503'; end if;
  elsif target_customer_id is not null then
    raise exception 'internal_conversation_customer_forbidden' using errcode = '22023';
  end if;
  select array_agg(distinct participant order by participant) into participant_ids
  from unnest(array_append(coalesce(target_participant_auth_user_ids, '{}'::uuid[]), (select auth.uid()))) participant;
  if coalesce(cardinality(participant_ids), 0) not between 2 and 50 then
    raise exception 'conversation_participants_invalid' using errcode = '22023';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'branch_id', target_branch_id,
    'audience', target_audience,
    'customer_id', target_customer_id,
    'subject', trim(target_subject),
    'entity_type', trim(target_entity_type),
    'entity_id', target_entity_id,
    'participants', participant_ids
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_conversation.operation_id;
  if found then
    if receipt.command_name <> 'create_conversation' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;

  insert into public.conversations(
    branch_id, audience, customer_id, subject, entity_type, entity_id,
    participant_summary, created_by, operation_id
  ) values (
    target_branch_id, target_audience, target_customer_id, trim(target_subject), trim(target_entity_type), target_entity_id,
    'Đang cập nhật người tham gia', (select auth.uid()), operation_id
  ) returning id into conversation_id;

  foreach participant_auth_user_id in array participant_ids loop
    participant_kind := null;
    participant_display := null;
    select 'EMPLOYEE', e.display_name into participant_kind, participant_display
      from public.employees e
      join public.employee_branch_access a on a.employee_id = e.id and a.active
      where e.auth_user_id = participant_auth_user_id and e.active and a.branch_id = target_branch_id
      limit 1;
    if participant_display is null and target_audience = 'CUSTOMER' then
      select 'CUSTOMER', c.display_name || ' (khách hàng)' into participant_kind, participant_display
      from public.customer_portal_memberships m
      join public.customers c on c.id = m.customer_id and c.active
      where m.auth_user_id = participant_auth_user_id and m.customer_id = target_customer_id and m.active
      limit 1;
    end if;
    if participant_display is null or (target_audience = 'INTERNAL' and participant_kind <> 'EMPLOYEE') then
      raise exception 'conversation_participant_forbidden' using errcode = '42501';
    end if;
    insert into public.conversation_participants(
      conversation_id, auth_user_id, participant_kind, display_name_snapshot, last_read_at
    ) values (
      conversation_id, participant_auth_user_id, participant_kind, participant_display,
      case when participant_auth_user_id = (select auth.uid()) then now() else null end
    );
  end loop;

  update public.conversations c set participant_summary = (
    select string_agg(p.display_name_snapshot, ', ' order by p.display_name_snapshot)
    from public.conversation_participants p where p.conversation_id = c.id
  ) where c.id = conversation_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_conversation', payload_hash, 'conversation', conversation_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), target_branch_id, 'conversation.created', 'conversation', conversation_id, operation_id,
    array['audience','participants','entity']);
  return conversation_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_delivery_expense(target_branch_id uuid, target_assignment_id uuid, target_category_id uuid, target_supplier_id uuid, amount_vnd bigint, effective_at timestamp with time zone, due_date date, description text, cost_scope text, supplier_reference text, target_evidence_id uuid, expected_delivery_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.deliveries%rowtype; a public.delivery_assignments%rowtype; r public.command_receipts%rowtype; h text; expense_id uuid;
begin
 if not private.has_permission(target_branch_id,'finance.expense.manage') then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'create_delivery_expense');
 perform pg_advisory_xact_lock(hashtextextended('create_delivery_expense:'||operation_id::text,0));
 if operation_id is null or cost_scope is null or cost_scope not in('DIRECT_DELIVERY','OVERHEAD') or supplier_reference is null
 or char_length(trim(supplier_reference)) not between 3 and 100 or amount_vnd is null or amount_vnd<=0 or effective_at is null or due_date is null or description is null
 then raise exception 'invalid_delivery_expense' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_branch_id,target_assignment_id,target_category_id,target_supplier_id,amount_vnd,effective_at,due_date,trim(description),cost_scope,trim(supplier_reference),target_evidence_id,expected_delivery_version));
 select * into r from public.command_receipts where command_receipts.operation_id=create_delivery_expense.operation_id;
 if found then
  if r.command_name<>'create_delivery_expense' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid()
  then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;
 end if;
 select * into a from public.delivery_assignments where id=target_assignment_id;
 select * into d from public.deliveries where id=a.delivery_id and branch_id=target_branch_id for update;
 if d.id is null or d.version is distinct from expected_delivery_version then raise exception 'delivery_expense_source_version_conflict' using errcode='40001';end if;
 -- Assignment is explicit and immutable: a later reassignment cannot move an old trip's expense.
 if not exists(select 1 from public.delivery_handoffs where assignment_id=a.id) then raise exception 'delivery_expense_requires_actual_handoff' using errcode='23514';end if;
 expense_id:=public.create_expense(target_branch_id,target_category_id,target_supplier_id,amount_vnd,effective_at,due_date,description,'DELIVERY',
  case when cost_scope='DIRECT_DELIVERY' then d.sales_order_id else null end,target_evidence_id,gen_random_uuid());
 insert into public.delivery_expense_sources values(expense_id,target_branch_id,d.id,a.id,cost_scope,target_supplier_id,trim(supplier_reference),auth.uid(),now());
 insert into public.command_receipts values(operation_id,auth.uid(),'create_delivery_expense',h,'expense',expense_id,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
 values(auth.uid(),target_branch_id,'delivery_expense.created','expense',expense_id,operation_id,array['delivery_id','assignment_id','cost_scope','supplier_reference']);
 return expense_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_delivery_from_allocation(target_supply_allocation_id uuid, planned_base_quantity numeric, scheduled_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allocation public.supply_allocations%rowtype; sale_line public.sales_order_lines%rowtype;
  sale_order public.sales_orders%rowtype; already_planned numeric; delivery_id uuid; delivery_line_id uuid;
  hash text; receipt public.command_receipts%rowtype;
begin
  select * into allocation from public.supply_allocations where id = target_supply_allocation_id for update;
  select * into sale_line from public.sales_order_lines where id = allocation.sales_order_line_id for update;
  select * into sale_order from public.sales_orders where id = sale_line.sales_order_id for update;
  if sale_order.id is null or sale_order.commercial_state <> 'CONFIRMED' or not private.has_permission(sale_order.branch_id, 'delivery.create') then raise exception 'order_not_ready_for_delivery' using errcode = '42501'; end if;
  if planned_base_quantity <= 0 then raise exception 'invalid_delivery_quantity' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('allocation_id', target_supply_allocation_id, 'quantity', planned_base_quantity, 'scheduled_at', scheduled_at));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_delivery_from_allocation.operation_id;
  if found then if receipt.command_name <> 'create_delivery_from_allocation' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_exact_quantity(planned_base_quantity,false);

  already_planned := private.delivery_allocation_consumed(target_supply_allocation_id);
  if already_planned + planned_base_quantity > allocation.allocated_base_quantity then raise exception 'delivery_exceeds_allocation' using errcode = '23514'; end if;
  insert into public.deliveries(branch_id, sales_order_id, delivery_number, customer_id, site_id,
    customer_name_snapshot, site_name_snapshot, delivery_address_snapshot, receiver_name_snapshot,
    receiver_phone_snapshot, scheduled_at, created_by)
  values (sale_order.branch_id, sale_order.id, 'DL-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.delivery_number_seq')::text, 6, '0'),
    sale_order.customer_id, sale_order.site_id, sale_order.customer_name_snapshot, sale_order.site_name_snapshot,
    sale_order.delivery_address_snapshot, sale_order.receiver_name_snapshot, sale_order.receiver_phone_snapshot,
    scheduled_at, (select auth.uid())) returning id into delivery_id;
  insert into public.delivery_lines(delivery_id, sales_order_line_id, supply_allocation_id, material_id,
    base_uom_id, source_mode, warehouse_id, planned_base_quantity, conversion_numerator,
    conversion_denominator, unit_price_vnd)
  values (delivery_id, sale_line.id, allocation.id, sale_line.material_id, sale_line.base_uom_id,
    allocation.supply_mode, allocation.warehouse_id, planned_base_quantity, sale_line.conversion_numerator,
    sale_line.conversion_denominator, sale_line.unit_price_vnd) returning id into delivery_line_id;
  if allocation.supply_mode in ('WAREHOUSE','SUPPLIER_TO_WAREHOUSE') then
    perform private.reserve_inventory_for_line(sale_line.id, delivery_line_id, allocation.warehouse_id, planned_base_quantity, (select auth.uid()));
  end if;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_delivery_from_allocation', hash, 'delivery', delivery_id, now());
  return delivery_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_delivery_from_allocations(target_sales_order_id uuid, planned_lines jsonb, scheduled_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sale_order public.sales_orders%rowtype;
  allocation public.supply_allocations%rowtype;
  sale_line public.sales_order_lines%rowtype;
  item jsonb;
  allocation_id uuid;
  allocation_ids uuid[] := '{}';
  used_sales_lines uuid[] := '{}';
  quantity_base numeric;
  already_planned numeric;
  direct_source boolean;
  delivery_id uuid;
  delivery_line_id uuid;
  hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into sale_order from public.sales_orders where id = target_sales_order_id;
  if sale_order.id is null or not private.has_permission(sale_order.branch_id, 'delivery.create') then
    raise exception 'forbidden_or_order_not_found' using errcode = '42501';
  end if;
  hash := private.command_payload_hash(jsonb_build_object('sales_order_id', target_sales_order_id, 'lines', planned_lines, 'scheduled_at', scheduled_at));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_delivery_from_allocations.operation_id;
  if found then
    if receipt.command_name <> 'create_delivery_from_allocations' or receipt.payload_hash <> hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  perform private.require_quantity_lines(planned_lines,array['planned_base_quantity'],false);

  if jsonb_typeof(planned_lines) is distinct from 'array' then
    raise exception 'invalid_delivery_lines' using errcode = '22023';
  end if;
  if jsonb_array_length(planned_lines) < 1 or jsonb_array_length(planned_lines) > 50 then
    raise exception 'invalid_delivery_lines' using errcode = '22023';
  end if;
  for item in select value from jsonb_array_elements(planned_lines) loop
    allocation_id := (item->>'supply_allocation_id')::uuid;
    quantity_base := (item->>'planned_base_quantity')::numeric;
    if allocation_id is null or quantity_base is null or quantity_base <= 0 or quantity_base::text in ('NaN','Infinity','-Infinity')
      or allocation_id = any(allocation_ids) then
      raise exception 'invalid_delivery_line' using errcode = '22023';
    end if;
    allocation_ids := array_append(allocation_ids, allocation_id);
  end loop;
  perform 1 from public.supply_allocations where id = any(allocation_ids) order by id for update;
  if (select count(*) from public.supply_allocations where id = any(allocation_ids)) <> cardinality(allocation_ids) then
    raise exception 'allocation_not_found' using errcode = '23503';
  end if;
  if (select count(distinct warehouse_id) from public.supply_allocations where id=any(allocation_ids) and supply_mode<>'SUPPLIER_DIRECT')>1
  then raise exception 'delivery_multiple_pickups_require_split' using errcode='23514';end if;
  perform 1 from public.sales_order_lines
    where id in (select sales_order_line_id from public.supply_allocations where id = any(allocation_ids))
    order by id for update;
  select * into sale_order from public.sales_orders where id = target_sales_order_id for update;
  if sale_order.commercial_state <> 'CONFIRMED' or not private.has_permission(sale_order.branch_id, 'delivery.create') then
    raise exception 'order_not_ready_for_delivery' using errcode = '42501';
  end if;
  insert into public.deliveries(branch_id, sales_order_id, delivery_number, customer_id, site_id,
    customer_name_snapshot, site_name_snapshot, delivery_address_snapshot, receiver_name_snapshot,
    receiver_phone_snapshot, scheduled_at, created_by)
  values (sale_order.branch_id, sale_order.id, 'DL-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.delivery_number_seq')::text, 6, '0'),
    sale_order.customer_id, sale_order.site_id, sale_order.customer_name_snapshot, sale_order.site_name_snapshot,
    sale_order.delivery_address_snapshot, sale_order.receiver_name_snapshot, sale_order.receiver_phone_snapshot,
    scheduled_at, (select auth.uid())) returning id into delivery_id;
  for item in select value from jsonb_array_elements(planned_lines) loop
    allocation_id := (item->>'supply_allocation_id')::uuid;
    quantity_base := (item->>'planned_base_quantity')::numeric;
    select * into allocation from public.supply_allocations where id = allocation_id;
    select * into sale_line from public.sales_order_lines where id = allocation.sales_order_line_id;
    if sale_line.id is null or sale_line.sales_order_id <> target_sales_order_id or sale_line.id = any(used_sales_lines) then
      raise exception 'delivery_line_source_invalid_or_duplicate' using errcode = '23514';
    end if;
    if direct_source is null then
      direct_source := allocation.supply_mode = 'SUPPLIER_DIRECT';
    elsif direct_source is distinct from (allocation.supply_mode = 'SUPPLIER_DIRECT') then
      raise exception 'delivery_mixed_source_not_supported' using errcode = '23514';
    end if;
    used_sales_lines := array_append(used_sales_lines, sale_line.id);
    already_planned := private.delivery_allocation_consumed(allocation.id);
    if allocation.supply_mode='SUPPLIER_DIRECT' and private.direct_source_retired_quantity(allocation.purchase_order_line_id,sale_line.id,now())>0 and already_planned-private.direct_source_retired_quantity(allocation.purchase_order_line_id,sale_line.id,now(),'CUSTOMER_RETURN')+quantity_base
     >least(allocation.allocated_base_quantity,(select pl.quantity*pl.conversion_numerator/pl.conversion_denominator from public.purchase_order_lines pl where pl.id=allocation.purchase_order_line_id)
       -private.direct_source_retired_quantity(allocation.purchase_order_line_id,sale_line.id,now()))
    then raise exception 'direct_source_retired_requires_replacement' using errcode='23514';end if;
    if already_planned + quantity_base > allocation.allocated_base_quantity then
      raise exception 'delivery_exceeds_allocation' using errcode = '23514';
    end if;
    insert into public.delivery_lines(delivery_id, sales_order_line_id, supply_allocation_id, material_id,
      base_uom_id, source_mode, warehouse_id, planned_base_quantity, conversion_numerator,
      conversion_denominator, unit_price_vnd)
    values (delivery_id, sale_line.id, allocation.id, sale_line.material_id, sale_line.base_uom_id,
      allocation.supply_mode, allocation.warehouse_id, quantity_base, sale_line.conversion_numerator,
      sale_line.conversion_denominator, sale_line.unit_price_vnd) returning id into delivery_line_id;
    if allocation.supply_mode in ('WAREHOUSE','SUPPLIER_TO_WAREHOUSE') then
      perform private.reserve_inventory_for_line(sale_line.id, delivery_line_id, allocation.warehouse_id, quantity_base, (select auth.uid()));
    end if;
  end loop;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_delivery_from_allocations', hash, 'delivery', delivery_id, now());
  return delivery_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_direct_purchase_from_sales_line(source_sales_order_line_id uuid, target_supplier_id uuid, requested_quantity numeric, purchase_line jsonb, expected_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sale_line public.sales_order_lines%rowtype; sale_order public.sales_orders%rowtype;
  supplier public.suppliers%rowtype; checked record; payload jsonb; hash text;
  receipt public.command_receipts%rowtype; order_id uuid; purchase_line_id uuid; base_quantity numeric;
begin
  select * into sale_line from public.sales_order_lines where id = source_sales_order_line_id for update;
  select * into sale_order from public.sales_orders where id = sale_line.sales_order_id;
  if not private.has_permission(sale_order.branch_id, 'purchasing.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  payload := jsonb_build_object('sales_line_id', source_sales_order_line_id, 'supplier_id', target_supplier_id, 'quantity', requested_quantity, 'line', purchase_line, 'expected_at', expected_at);
  hash := private.command_payload_hash(payload);
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_direct_purchase_from_sales_line.operation_id;
  if found then if receipt.command_name <> 'create_direct_purchase_from_sales_line' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_exact_quantity(requested_quantity,false);

  if sale_order.commercial_state not in ('DRAFT','CONFIRMED') then raise exception 'sales_order_not_sourceable' using errcode = '23514'; end if;
  if (purchase_line->>'material_id')::uuid <> sale_line.material_id
    or (purchase_line->>'ordered_uom_id')::uuid <> sale_line.ordered_uom_id
    or (purchase_line->>'conversion_numerator')::numeric <> sale_line.conversion_numerator
    or (purchase_line->>'conversion_denominator')::numeric <> sale_line.conversion_denominator
    or requested_quantity <> (purchase_line->>'quantity')::numeric then
    raise exception 'direct_purchase_line_mismatch' using errcode = '22023';
  end if;
  select * into supplier from public.suppliers where id = target_supplier_id and branch_id = sale_order.branch_id and active;
  if supplier.id is null then raise exception 'supplier_invalid' using errcode = '23503'; end if;
  select * into checked from private.assert_purchase_line(sale_order.branch_id, target_supplier_id, purchase_line, (select auth.uid()));
  base_quantity := checked.quantity * checked.conversion_numerator / checked.conversion_denominator;
  perform private.assert_allocation_capacity(source_sales_order_line_id, base_quantity);
  insert into public.purchase_orders(branch_id, purchase_order_number, supplier_id, destination_type, customer_id,
    site_id, source_sales_order_id, supplier_name_snapshot, supplier_address_snapshot,
    destination_name_snapshot, destination_address_snapshot, expected_at, created_by)
  values (sale_order.branch_id, 'PO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.purchase_order_number_seq')::text, 6, '0'),
    target_supplier_id, 'CUSTOMER_SITE', sale_order.customer_id, sale_order.site_id, sale_order.id,
    supplier.name, supplier.address_text, sale_order.site_name_snapshot, sale_order.delivery_address_snapshot,
    expected_at, (select auth.uid())) returning id into order_id;
  insert into public.purchase_order_lines(purchase_order_id, linked_sales_order_line_id, line_number, material_id,
    material_name_snapshot, ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator,
    rounding_mode, unit_cost_vnd, line_total_cost_vnd, purchase_price_rule_id, purchase_price_rule_version,
    price_source_type, override_by, override_reason)
  values (order_id, source_sales_order_line_id, 1, checked.material_id, checked.material_name, checked.ordered_uom_id,
    checked.base_uom_id, checked.quantity, checked.conversion_numerator, checked.conversion_denominator,
    checked.rounding_mode, checked.unit_cost_vnd, checked.line_total_cost_vnd, checked.purchase_price_rule_id,
    checked.purchase_price_rule_version, checked.price_source_type, checked.override_by, checked.override_reason)
  returning id into purchase_line_id;
  insert into public.supply_allocations(branch_id, sales_order_line_id, supply_mode, purchase_order_line_id,
    allocated_base_quantity, created_by)
  values (sale_order.branch_id, source_sales_order_line_id, 'SUPPLIER_DIRECT', purchase_line_id,
    base_quantity, (select auth.uid()));
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_direct_purchase_from_sales_line', hash, 'purchase_order', order_id, now());
  return order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_direct_purchase_from_sales_order(target_sales_order_id uuid, target_supplier_id uuid, purchase_lines jsonb, expected_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  sale_order public.sales_orders%rowtype;
  sale_line public.sales_order_lines%rowtype;
  supplier public.suppliers%rowtype;
  receipt public.command_receipts%rowtype;
  checked record;
  payload_hash text;
  order_id uuid;
  purchase_line_id uuid;
  item jsonb;
  source_line_id uuid;
  seen_source_ids uuid[] := array[]::uuid[];
  line_no integer := 0;
  base_quantity numeric;
begin
  select * into sale_order from public.sales_orders where id = target_sales_order_id;
  if not found or not private.has_permission(sale_order.branch_id, 'purchasing.create')
  then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(purchase_lines) is distinct from 'array' then raise exception 'purchase_lines_required' using errcode = '22023'; end if;
  if jsonb_array_length(purchase_lines) not between 1 and 50 then raise exception 'purchase_lines_invalid' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('sales_order_id', target_sales_order_id,
    'supplier_id', target_supplier_id, 'lines', purchase_lines, 'expected_at', expected_at));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_direct_purchase_from_sales_order.operation_id;
  if found then
    if receipt.command_name <> 'create_direct_purchase_from_sales_order' or receipt.payload_hash <> payload_hash
      or receipt.actor_auth_user_id <> (select auth.uid())
    then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  perform private.require_quantity_lines(purchase_lines,array['quantity'],false);

  if sale_order.commercial_state not in ('DRAFT','CONFIRMED')
  then raise exception 'sales_order_not_sourceable' using errcode = '23514'; end if;
  select * into supplier from public.suppliers where id = target_supplier_id and branch_id = sale_order.branch_id and active;
  if supplier.id is null then raise exception 'supplier_invalid' using errcode = '23503'; end if;
  insert into public.purchase_orders(branch_id, purchase_order_number, supplier_id, destination_type, customer_id,
    site_id, source_sales_order_id, supplier_name_snapshot, supplier_address_snapshot,
    destination_name_snapshot, destination_address_snapshot, expected_at, created_by)
  values (sale_order.branch_id, 'PO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.purchase_order_number_seq')::text, 6, '0'),
    target_supplier_id, 'CUSTOMER_SITE', sale_order.customer_id, sale_order.site_id, sale_order.id,
    supplier.name, supplier.address_text, sale_order.site_name_snapshot, sale_order.delivery_address_snapshot,
    expected_at, (select auth.uid())) returning id into order_id;
  for item in select value from jsonb_array_elements(purchase_lines) loop
    source_line_id := nullif(item->>'linked_sales_order_line_id', '')::uuid;
    if source_line_id is null or source_line_id = any(seen_source_ids)
    then raise exception 'direct_purchase_source_line_invalid' using errcode = '22023'; end if;
    seen_source_ids := array_append(seen_source_ids, source_line_id);
    select * into sale_line from public.sales_order_lines where id = source_line_id and sales_order_id = target_sales_order_id for update;
    if not found then raise exception 'direct_purchase_source_line_invalid' using errcode = '23503'; end if;
    select * into checked from private.assert_purchase_line(sale_order.branch_id, target_supplier_id, item, (select auth.uid()));
    if checked.material_id <> sale_line.material_id or checked.base_uom_id <> sale_line.base_uom_id
    then raise exception 'direct_purchase_line_mismatch' using errcode = '22023'; end if;
    base_quantity := checked.quantity * checked.conversion_numerator / checked.conversion_denominator;
    perform private.assert_allocation_capacity(source_line_id, base_quantity);
    line_no := line_no + 1;
    insert into public.purchase_order_lines(purchase_order_id, linked_sales_order_line_id, line_number, material_id,
      material_name_snapshot, ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator,
      rounding_mode, unit_cost_vnd, line_total_cost_vnd, purchase_price_rule_id, purchase_price_rule_version,
      price_source_type, override_by, override_reason)
    values (order_id, source_line_id, line_no, checked.material_id, checked.material_name,
      checked.ordered_uom_id, checked.base_uom_id, checked.quantity, checked.conversion_numerator,
      checked.conversion_denominator, checked.rounding_mode, checked.unit_cost_vnd, checked.line_total_cost_vnd,
      checked.purchase_price_rule_id, checked.purchase_price_rule_version, checked.price_source_type,
      checked.override_by, checked.override_reason)
    returning id into purchase_line_id;
    insert into public.supply_allocations(branch_id, sales_order_line_id, supply_mode, purchase_order_line_id,
      allocated_base_quantity, created_by)
    values (sale_order.branch_id, source_line_id, 'SUPPLIER_DIRECT', purchase_line_id, base_quantity, (select auth.uid()));
  end loop;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_direct_purchase_from_sales_order', payload_hash, 'purchase_order', order_id, now());
  return order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_evidence_upload(target_branch_id uuid, bucket_name text, object_path text, audience text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
