CREATE OR REPLACE FUNCTION public.create_invoice_adjustment_draft(target_invoice_id uuid, target_receivable_adjustment_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  invoice public.invoice_intents%rowtype;
  adjustment public.receivable_adjustments%rowtype;
  draft_id uuid;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  perform private.lock_saved_command_intent(operation_id,'create_invoice_adjustment_draft');
  perform pg_advisory_xact_lock(hashtextextended('document:'||operation_id::text,0));
  select * into invoice from public.invoice_intents i where i.id = target_invoice_id for update;
  if invoice.id is null or not private.has_permission(invoice.branch_id, 'finance.ar.adjust') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'invoice_id', target_invoice_id, 'adjustment_id', target_receivable_adjustment_id
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_invoice_adjustment_draft.operation_id;
  if found then
    if receipt.command_name <> 'create_invoice_adjustment_draft' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  select * into adjustment from public.receivable_adjustments a where a.id = target_receivable_adjustment_id;
  if invoice.status <> 'BUSINESS_APPROVED' or adjustment.id is null
    or adjustment.obligation_id <> invoice.source_obligation_id or adjustment.amount_delta_vnd = 0 then
    raise exception 'invoice_adjustment_source_invalid' using errcode = '23514';
  end if;
  insert into public.invoice_adjustment_drafts(
    branch_id, invoice_intent_id, receivable_adjustment_id, amount_delta_vnd,
    reason_snapshot, created_by, operation_id
  ) values (
    invoice.branch_id, invoice.id, adjustment.id, adjustment.amount_delta_vnd,
    adjustment.reason, (select auth.uid()), operation_id
  ) returning id into draft_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_invoice_adjustment_draft', payload_hash, 'invoice_adjustment_draft', draft_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), invoice.branch_id, 'invoice_adjustment_draft.created', 'invoice_adjustment_draft', draft_id, operation_id,
    array['source_adjustment','amount_delta','reason']);
  return draft_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_invoice_draft(target_obligation_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  obligation public.receivable_obligations%rowtype;
  source_type text;
  source_id uuid;
  verified_at timestamptz;
  customer_name text;
  invoice_id uuid;
  line_total bigint;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  perform private.lock_saved_command_intent(operation_id,'create_invoice_draft');
  perform pg_advisory_xact_lock(hashtextextended('document:'||operation_id::text,0));
  select * into obligation from public.receivable_obligations o where o.id = target_obligation_id for update;
  if obligation.id is null or not private.has_permission(obligation.branch_id, 'finance.ar.adjust') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if obligation.opening_source_id is not null or obligation.original_amount_vnd <= 0 then
    raise exception 'invoice_source_ineligible' using errcode = '23514';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('source_obligation_id', target_obligation_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_invoice_draft.operation_id;
  if found then
    if receipt.command_name <> 'create_invoice_draft' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  if exists (select 1 from public.invoice_coverage c where c.source_obligation_id = obligation.id and c.released_at is null) then
    raise exception 'invoice_source_already_covered' using errcode = '23505';
  end if;
  select c.display_name into customer_name from public.customers c where c.id = obligation.customer_id;
  if obligation.delivery_verification_id is not null then
    source_type := 'DELIVERY_VERIFICATION';
    source_id := obligation.delivery_verification_id;
    select v.verified_at into verified_at from public.delivery_verifications v where v.id = source_id;
  else
    source_type := 'SERVICE_VERIFICATION';
    source_id := obligation.service_verification_id;
    select v.verified_at into verified_at from public.service_verifications v where v.id = source_id;
  end if;
  if verified_at is null or customer_name is null then
    raise exception 'invoice_source_unverified' using errcode = '23514';
  end if;

  insert into public.invoice_intents(
    branch_id, customer_id, customer_name_snapshot, source_obligation_id,
    source_type, source_id, source_amount_vnd, billing_verified_at, created_by, create_operation_id
  ) values (
    obligation.branch_id, obligation.customer_id, customer_name, obligation.id,
    source_type, source_id, obligation.original_amount_vnd, verified_at, (select auth.uid()), operation_id
  ) returning id into invoice_id;

  if source_type = 'DELIVERY_VERIFICATION' then
    insert into public.invoice_draft_lines(
      invoice_intent_id, line_number, source_line_id, description_snapshot, quantity_snapshot, source_amount_vnd
    )
    select invoice_id, row_number() over(order by vl.id)::integer, vl.id,
      sol.material_name_snapshot, vl.billable_base_quantity, vl.receivable_amount_vnd
    from public.delivery_verification_lines vl
    join public.delivery_lines dl on dl.id = vl.delivery_line_id
    join public.sales_order_lines sol on sol.id = dl.sales_order_line_id
    where vl.delivery_verification_id = source_id
      and vl.billable_base_quantity > 0 and vl.receivable_amount_vnd > 0;
  else
    insert into public.invoice_draft_lines(
      invoice_intent_id, line_number, source_line_id, description_snapshot, quantity_snapshot, source_amount_vnd
    )
    select invoice_id, 1, sv.id, sj.service_type, sv.billable_quantity, sv.billable_amount_vnd
    from public.service_verifications sv
    join public.service_jobs sj on sj.id = sv.service_job_id
    where sv.id = source_id and sv.billable_quantity > 0 and sv.billable_amount_vnd > 0;
  end if;
  select coalesce(sum(l.source_amount_vnd), 0)::bigint into line_total
    from public.invoice_draft_lines l where l.invoice_intent_id = invoice_id;
  if line_total <> obligation.original_amount_vnd then
    raise exception 'invoice_source_amount_mismatch' using errcode = '23514';
  end if;
  insert into public.invoice_coverage(source_obligation_id, invoice_intent_id, covered_amount_vnd)
  values (obligation.id, invoice_id, obligation.original_amount_vnd);
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_invoice_draft', payload_hash, 'invoice_intent', invoice_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), obligation.branch_id, 'invoice_draft.created', 'invoice_intent', invoice_id, operation_id,
    array['source','source_amount','coverage','billing_verified_at']);
  return invoice_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_linked_direct_drafts(target_branch_id uuid, target_supplier_id uuid, target_customer_id uuid, target_site_id uuid, purchase_line jsonb, sales_line jsonb, expected_at timestamp with time zone, commercial_terms text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  purchases jsonb := purchase_line;
  sales jsonb := sales_line;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  supplier public.suppliers%rowtype;
  customer public.customers%rowtype;
  site public.customer_sites%rowtype;
  checked_purchase record;
  checked_sale record;
  sales_order_id uuid;
  sales_line_id uuid;
  purchase_order_id uuid;
  purchase_line_id uuid;
  line_no integer;
  base_quantity numeric;
begin
  if not private.has_permission(target_branch_id, 'purchasing.create') or not private.has_permission(target_branch_id, 'orders.create')
  then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(purchases) = 'object' then purchases := jsonb_build_array(purchases); end if;
  if jsonb_typeof(sales) = 'object' then sales := jsonb_build_array(sales); end if;
  if jsonb_typeof(purchases) is distinct from 'array' or jsonb_typeof(sales) is distinct from 'array'
  then raise exception 'linked_draft_lines_required' using errcode = '22023'; end if;
  if jsonb_array_length(purchases) not between 1 and 50 or jsonb_array_length(purchases) <> jsonb_array_length(sales)
    or char_length(coalesce(commercial_terms, '')) > 1000
  then raise exception 'linked_draft_lines_invalid' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'branch_id', target_branch_id, 'supplier_id', target_supplier_id, 'customer_id', target_customer_id,
    'site_id', target_site_id, 'purchases', purchases, 'sales', sales, 'expected_at', expected_at, 'terms', commercial_terms));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_linked_direct_drafts.operation_id;
  if found then
    if receipt.command_name <> 'create_linked_direct_drafts' or receipt.payload_hash <> payload_hash
      or receipt.actor_auth_user_id <> (select auth.uid())
    then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  select * into supplier from public.suppliers where id = target_supplier_id and branch_id = target_branch_id and active;
  select * into customer from public.customers where id = target_customer_id and branch_id = target_branch_id and active;
  select * into site from public.customer_sites where id = target_site_id and customer_id = target_customer_id and active;
  if supplier.id is null or customer.id is null or site.id is null
  then raise exception 'linked_party_invalid' using errcode = '23503'; end if;
  insert into public.sales_orders(branch_id, order_number, customer_id, site_id, sales_owner_employee_id,
    customer_name_snapshot, site_name_snapshot, delivery_address_snapshot, receiver_name_snapshot,
    receiver_phone_snapshot, requested_delivery_at, commercial_terms, created_by)
  values (target_branch_id, 'SO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.sales_order_number_seq')::text, 6, '0'),
    target_customer_id, target_site_id, private.current_employee_id(), customer.display_name, site.name,
    site.address_text, site.receiver_name, site.receiver_phone, expected_at, commercial_terms, (select auth.uid()))
  returning id into sales_order_id;
  insert into public.purchase_orders(branch_id, purchase_order_number, supplier_id, destination_type, customer_id,
    site_id, source_sales_order_id, supplier_name_snapshot, supplier_address_snapshot,
    destination_name_snapshot, destination_address_snapshot, expected_at, commercial_terms, created_by)
  values (target_branch_id, 'PO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.purchase_order_number_seq')::text, 6, '0'),
    target_supplier_id, 'CUSTOMER_SITE', target_customer_id, target_site_id, sales_order_id,
    supplier.name, supplier.address_text, site.name, site.address_text, expected_at, commercial_terms, (select auth.uid()))
  returning id into purchase_order_id;
  for line_no in 1..jsonb_array_length(purchases) loop
    if (purchases->(line_no - 1)->>'material_id')::uuid is distinct from (sales->(line_no - 1)->>'material_id')::uuid
      or (purchases->(line_no - 1)->>'ordered_uom_id')::uuid is distinct from (sales->(line_no - 1)->>'ordered_uom_id')::uuid
      or (purchases->(line_no - 1)->>'quantity')::numeric is distinct from (sales->(line_no - 1)->>'quantity')::numeric
    then raise exception 'linked_draft_lines_mismatch' using errcode = '22023'; end if;
    select * into checked_purchase from private.assert_purchase_line(target_branch_id, target_supplier_id, purchases->(line_no - 1), (select auth.uid()));
    select * into checked_sale from private.assert_commercial_line(target_branch_id, target_customer_id, sales->(line_no - 1), (select auth.uid()));
    if checked_purchase.base_uom_id <> checked_sale.base_uom_id
      or checked_purchase.conversion_numerator <> checked_sale.conversion_numerator
      or checked_purchase.conversion_denominator <> checked_sale.conversion_denominator
    then raise exception 'linked_conversion_mismatch' using errcode = '22023'; end if;
    insert into public.sales_order_lines(sales_order_id, line_number, material_id, material_name_snapshot,
      ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator, rounding_mode,
      unit_price_vnd, line_total_vnd, pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason)
    values (sales_order_id, line_no, checked_sale.material_id, checked_sale.material_name, checked_sale.ordered_uom_id,
      checked_sale.base_uom_id, checked_sale.quantity, checked_sale.conversion_numerator, checked_sale.conversion_denominator,
      checked_sale.rounding_mode, checked_sale.unit_price_vnd, checked_sale.line_total_vnd, checked_sale.pricing_rule_id,
      checked_sale.pricing_rule_version, checked_sale.price_source_type, checked_sale.override_by, checked_sale.override_reason)
    returning id into sales_line_id;
    insert into public.purchase_order_lines(purchase_order_id, linked_sales_order_line_id, line_number, material_id,
      material_name_snapshot, ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator,
      rounding_mode, unit_cost_vnd, line_total_cost_vnd, purchase_price_rule_id, purchase_price_rule_version,
      price_source_type, override_by, override_reason)
    values (purchase_order_id, sales_line_id, line_no, checked_purchase.material_id, checked_purchase.material_name,
      checked_purchase.ordered_uom_id, checked_purchase.base_uom_id, checked_purchase.quantity,
      checked_purchase.conversion_numerator, checked_purchase.conversion_denominator, checked_purchase.rounding_mode,
      checked_purchase.unit_cost_vnd, checked_purchase.line_total_cost_vnd, checked_purchase.purchase_price_rule_id,
      checked_purchase.purchase_price_rule_version, checked_purchase.price_source_type,
      checked_purchase.override_by, checked_purchase.override_reason)
    returning id into purchase_line_id;
    base_quantity := checked_purchase.quantity * checked_purchase.conversion_numerator / checked_purchase.conversion_denominator;
    insert into public.supply_allocations(branch_id, sales_order_line_id, supply_mode, purchase_order_line_id,
      allocated_base_quantity, created_by)
    values (target_branch_id, sales_line_id, 'SUPPLIER_DIRECT', purchase_line_id, base_quantity, (select auth.uid()));
  end loop;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_linked_direct_drafts', payload_hash, 'purchase_order', purchase_order_id, now());
  return purchase_order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_portal_evidence(target_context_type text, target_work_item_id uuid, target_customer_id uuid, target_mime_type text, target_byte_size bigint, operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload_hash text;
  receipt public.command_receipts%rowtype;
  evidence public.portal_evidence_objects%rowtype;
  extension text;
  actor_quota bigint;
begin
  if (select auth.uid()) is null then raise exception 'authentication_required' using errcode = '42501'; end if;
  if target_mime_type not in ('image/jpeg','image/png','application/pdf') or target_byte_size not between 1 and 10485760 then
    raise exception 'unsupported_evidence_file' using errcode = '22023';
  end if;
  if target_context_type = 'WORK_RESULT' then
    if target_work_item_id is null or target_customer_id is not null or not private.is_current_work_assignee(target_work_item_id) then
      raise exception 'work_evidence_forbidden' using errcode = '42501';
    end if;
  elsif target_context_type = 'PAYMENT_NOTICE' then
    if target_customer_id is null or target_work_item_id is not null or coalesce(private.portal_customer_role(target_customer_id), '') not in ('OWNER','FINANCE_CONTACT') then
      raise exception 'payment_evidence_forbidden' using errcode = '42501';
    end if;
  else
    raise exception 'unsupported_evidence_context' using errcode = '22023';
  end if;

  payload_hash := private.command_payload_hash(jsonb_build_object(
    'context', target_context_type,
    'work_item', target_work_item_id,
    'customer', target_customer_id,
    'mime', target_mime_type,
    'bytes', target_byte_size
  ));
  select * into receipt from public.command_receipts r where r.operation_id = create_portal_evidence.operation_id;
  if found then
    if receipt.command_name <> 'create_portal_evidence' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    select * into evidence from public.portal_evidence_objects e where e.id = receipt.result_entity_id;
    return jsonb_build_object('id', evidence.id, 'bucket_id', evidence.bucket_id, 'object_path', evidence.object_path, 'state', evidence.object_state);
  end if;

  select coalesce(sum(coalesce(e.final_byte_size, e.declared_byte_size)), 0)
  into actor_quota
  from public.portal_evidence_objects e
  where e.uploaded_by = (select auth.uid()) and e.object_state <> 'REVOKED';
  if actor_quota + target_byte_size > 104857600 then raise exception 'portal_evidence_quota_exceeded' using errcode = '54000'; end if;

  extension := case target_mime_type when 'image/jpeg' then '.jpg' when 'image/png' then '.png' else '.pdf' end;
  evidence.id := gen_random_uuid();
  evidence.object_path := lower(target_context_type) || '/' || evidence.id::text || '-' || gen_random_uuid()::text || extension;
  insert into public.portal_evidence_objects(
    id, object_path, context_type, work_item_id, customer_id, uploaded_by, mime_type, declared_byte_size
  ) values(
    evidence.id, evidence.object_path, target_context_type, target_work_item_id, target_customer_id,
    (select auth.uid()), target_mime_type, target_byte_size
  ) returning * into evidence;
  insert into public.command_receipts
  values(operation_id, (select auth.uid()), 'create_portal_evidence', payload_hash, 'portal_evidence', evidence.id, now());
  return jsonb_build_object('id', evidence.id, 'bucket_id', evidence.bucket_id, 'object_path', evidence.object_path, 'state', evidence.object_state);
end $function$

CREATE OR REPLACE FUNCTION public.create_purchase_order_draft(target_branch_id uuid, target_supplier_id uuid, target_warehouse_id uuid, expected_at timestamp with time zone, commercial_terms text, purchase_lines jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; hash text; receipt public.command_receipts%rowtype;
  supplier public.suppliers%rowtype; warehouse public.warehouses%rowtype;
  order_id uuid; item jsonb; checked record; line_no integer := 0;
begin
  if auth.uid() is null or not private.has_permission(target_branch_id, 'purchasing.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(purchase_lines) <> 'array' or jsonb_array_length(purchase_lines) = 0 then raise exception 'purchase_lines_required' using errcode = '22023'; end if;
  payload := jsonb_build_object('branch_id', target_branch_id, 'supplier_id', target_supplier_id, 'warehouse_id', target_warehouse_id, 'expected_at', expected_at, 'terms', commercial_terms, 'lines', purchase_lines);
  hash := private.command_payload_hash(payload);
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_purchase_order_draft.operation_id;
  if found then if receipt.command_name <> 'create_purchase_order_draft' or receipt.payload_hash <> hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_quantity_lines(purchase_lines,array['quantity'],false);

  select * into supplier from public.suppliers where id = target_supplier_id and branch_id = target_branch_id and active;
  select * into warehouse from public.warehouses where id = target_warehouse_id and branch_id = target_branch_id and active for share;
  if supplier.id is null or warehouse.id is null then raise exception 'supplier_or_warehouse_invalid' using errcode = '23503'; end if;
  if private.normalize_po_warehouse_address(warehouse.address_text) is null then raise exception 'warehouse_address_required' using errcode = '22023'; end if;
  insert into public.purchase_orders(branch_id, purchase_order_number, supplier_id, destination_type, warehouse_id,
    supplier_name_snapshot, supplier_address_snapshot, destination_name_snapshot, destination_address_snapshot,
    expected_at, commercial_terms, created_by)
  values (target_branch_id, 'PO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.purchase_order_number_seq')::text, 6, '0'),
    target_supplier_id, 'WAREHOUSE', target_warehouse_id, supplier.name, supplier.address_text,
    warehouse.name, private.normalize_po_warehouse_address(warehouse.address_text), expected_at, commercial_terms, (select auth.uid())) returning id into order_id;
  for item in select value from jsonb_array_elements(purchase_lines) loop
    line_no := line_no + 1;
    select * into checked from private.assert_purchase_line(target_branch_id, target_supplier_id, item, (select auth.uid()));
    insert into public.purchase_order_lines(purchase_order_id, line_number, material_id, material_name_snapshot,
      ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator, rounding_mode,
      unit_cost_vnd, line_total_cost_vnd, purchase_price_rule_id, purchase_price_rule_version,
      price_source_type, override_by, override_reason)
    values (order_id, line_no, checked.material_id, checked.material_name, checked.ordered_uom_id, checked.base_uom_id,
      checked.quantity, checked.conversion_numerator, checked.conversion_denominator, checked.rounding_mode,
      checked.unit_cost_vnd, checked.line_total_cost_vnd, checked.purchase_price_rule_id,
      checked.purchase_price_rule_version, checked.price_source_type, checked.override_by, checked.override_reason);
  end loop;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_purchase_order_draft', hash, 'purchase_order', order_id, now());
  return order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_quote_draft(target_branch_id uuid, target_customer_id uuid, target_site_id uuid, expires_at timestamp with time zone, commercial_terms text, quote_lines jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload jsonb; payload_hash text; receipt public.command_receipts%rowtype;
  customer public.customers%rowtype; site public.customer_sites%rowtype;
  quote_id uuid; revision_id uuid; employee_id uuid; item jsonb; checked record; line_no integer := 0; total bigint := 0;
begin
  if not private.has_permission(target_branch_id, 'quotation.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(quote_lines) <> 'array' or jsonb_array_length(quote_lines) = 0 then raise exception 'quote_lines_required' using errcode = '22023'; end if;
  payload := jsonb_build_object('branch_id', target_branch_id, 'customer_id', target_customer_id, 'site_id', target_site_id, 'expires_at', expires_at, 'terms', commercial_terms, 'lines', quote_lines);
  payload_hash := private.command_payload_hash(payload);
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_quote_draft.operation_id;
  if found then
    if receipt.command_name <> 'create_quote_draft' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  perform private.require_quantity_lines(quote_lines,array['quantity'],false);

  select * into customer from public.customers where id = target_customer_id and branch_id = target_branch_id and active;
  select * into site from public.customer_sites where id = target_site_id and customer_id = target_customer_id and active;
  if customer.id is null or site.id is null then raise exception 'customer_or_site_invalid' using errcode = '23503'; end if;
  employee_id := private.current_employee_id();
  insert into public.quotations(branch_id, quotation_number, customer_id, site_id, sales_owner_employee_id, created_by)
  values (target_branch_id, 'QT-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.quotation_number_seq')::text, 6, '0'), target_customer_id, target_site_id, employee_id, (select auth.uid()))
  returning id into quote_id;
  insert into public.quotation_revisions(quotation_id, revision_number, customer_name_snapshot, site_name_snapshot,
    delivery_address_snapshot, receiver_name_snapshot, receiver_phone_snapshot, commercial_terms, expires_at, created_by)
  values (quote_id, 1, customer.display_name, site.name, site.address_text, site.receiver_name, site.receiver_phone,
    commercial_terms, expires_at, (select auth.uid())) returning id into revision_id;
  for item in select value from jsonb_array_elements(quote_lines) loop
    line_no := line_no + 1;
    select * into checked from private.assert_commercial_line(target_branch_id, target_customer_id, item, (select auth.uid()));
    insert into public.quotation_lines(revision_id, line_number, material_id, material_name_snapshot, ordered_uom_id, base_uom_id,
      quantity, conversion_numerator, conversion_denominator, rounding_mode, unit_price_vnd, line_total_vnd,
      pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason)
    values (revision_id, line_no, checked.material_id, checked.material_name, checked.ordered_uom_id, checked.base_uom_id,
      checked.quantity, checked.conversion_numerator, checked.conversion_denominator, checked.rounding_mode,
      checked.unit_price_vnd, checked.line_total_vnd, checked.pricing_rule_id, checked.pricing_rule_version,
      checked.price_source_type, checked.override_by, checked.override_reason);
    total := total + checked.line_total_vnd;
  end loop;
  update public.quotation_revisions set total_vnd = total where id = revision_id;
  update public.quotations set current_revision_id = revision_id where id = quote_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_quote_draft', payload_hash, 'quotation', quote_id, now());
  return quote_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_quote_revision(source_revision_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_revision public.quotation_revisions%rowtype; quote public.quotations%rowtype; hash text; receipt public.command_receipts%rowtype; new_revision_id uuid;
begin
  select * into source_revision from public.quotation_revisions where id = source_revision_id for update;
  select * into quote from public.quotations where id = source_revision.quotation_id for update;
  if not private.has_permission(quote.branch_id, 'quotation.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('source_revision_id', source_revision_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_quote_revision.operation_id;
  if found then if receipt.command_name <> 'create_quote_revision' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if quote.current_revision_id <> source_revision_id or source_revision.state not in ('SENT','ACCEPTED','EXPIRED') then raise exception 'revision_not_revisable' using errcode = '23514'; end if;
  update public.quotation_revisions set state = 'SUPERSEDED' where id = source_revision_id;
  insert into public.quotation_revisions(quotation_id, revision_number, customer_name_snapshot, site_name_snapshot,
    delivery_address_snapshot, receiver_name_snapshot, receiver_phone_snapshot, commercial_terms, total_vnd,
    expires_at, supersedes_revision_id, created_by)
  values (source_revision.quotation_id, source_revision.revision_number + 1, source_revision.customer_name_snapshot,
    source_revision.site_name_snapshot, source_revision.delivery_address_snapshot, source_revision.receiver_name_snapshot,
    source_revision.receiver_phone_snapshot, source_revision.commercial_terms, source_revision.total_vnd,
    source_revision.expires_at, source_revision_id, (select auth.uid())) returning id into new_revision_id;
  insert into public.quotation_lines(revision_id, line_number, material_id, material_name_snapshot, ordered_uom_id,
    base_uom_id, quantity, conversion_numerator, conversion_denominator, rounding_mode, unit_price_vnd,
    line_total_vnd, pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason)
  select new_revision_id, line_number, material_id, material_name_snapshot, ordered_uom_id, base_uom_id, quantity,
    conversion_numerator, conversion_denominator, rounding_mode, unit_price_vnd, line_total_vnd,
    pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason
  from public.quotation_lines where revision_id = source_revision_id;
  update public.quotations set current_revision_id = new_revision_id where id = source_revision.quotation_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_quote_revision', hash, 'quotation_revision', new_revision_id, now());
  return new_revision_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_report_export_job(target_branch_id uuid, target_side text, target_as_of date, target_cutoff timestamp with time zone, target_customer_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
  key text;
  result_id uuid;
begin
  if actor is null or target_side not in ('AR', 'AP')
     or target_as_of is null or target_cutoff is null or target_cutoff > now()
     or (target_side = 'AP' and target_customer_id is not null)
     or not private.has_permission(target_branch_id, case target_side when 'AR' then 'finance.ar.read' else 'finance.ap.read' end)
  then raise exception 'report_export_forbidden' using errcode = '42501'; end if;

  key := md5(concat_ws(':', actor, target_branch_id, target_side, target_as_of, target_cutoff, coalesce(target_customer_id::text, '')));
  insert into public.report_export_jobs (owner_user_id, branch_id, side, as_of_date, knowledge_cutoff, customer_id, dedupe_key)
  values (actor, target_branch_id, target_side, target_as_of, target_cutoff, target_customer_id, key)
  on conflict (owner_user_id, dedupe_key) do update set updated_at = public.report_export_jobs.updated_at
  returning id into result_id;
  return result_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_route_plan(target_branch_id uuid, target_departure_at timestamp with time zone, target_vehicle_id uuid, target_driver_employee_id uuid, target_provider_state text, target_provider_distance_meters integer, target_provider_duration_seconds integer, target_provider_error_safe text, target_stops jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  plan_id uuid;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  stop record;
  delivery public.deliveries%rowtype;
  current_assignment_version integer;
  stop_count integer;
begin
  if (select auth.uid()) is null or not private.has_permission(target_branch_id, 'delivery.assign') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if target_departure_at is null or target_vehicle_id is null or target_driver_employee_id is null then
    raise exception 'route_resources_required' using errcode = '22023';
  end if;
  if target_provider_state not in ('RECOMMENDED','MANUAL_FALLBACK') then
    raise exception 'invalid_route_provider_state' using errcode = '22023';
  end if;
  if jsonb_typeof(target_stops) <> 'array' or jsonb_array_length(target_stops) not between 1 and 50 then
    raise exception 'invalid_route_stops' using errcode = '22023';
  end if;
  if not exists (select 1 from public.vehicles v where v.id = target_vehicle_id and v.branch_id = target_branch_id and v.active) then
    raise exception 'route_vehicle_invalid' using errcode = '23503';
  end if;
  if not exists (
    select 1 from public.employees e
    join public.employee_branch_access a on a.employee_id = e.id and a.active
    where e.id = target_driver_employee_id and e.active and a.branch_id = target_branch_id
  ) then
    raise exception 'route_driver_invalid' using errcode = '23503';
  end if;

  payload_hash := private.command_payload_hash(jsonb_build_object(
    'branch_id', target_branch_id,
    'departure_at', target_departure_at,
    'vehicle_id', target_vehicle_id,
    'driver_employee_id', target_driver_employee_id,
    'provider_state', target_provider_state,
    'provider_distance_meters', target_provider_distance_meters,
    'provider_duration_seconds', target_provider_duration_seconds,
    'stops', target_stops
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_route_plan.operation_id;
  if found then
    if receipt.command_name <> 'create_route_plan' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;

  select count(*), count(distinct (item->>'stop_order')::integer)
    into stop_count, current_assignment_version
  from jsonb_array_elements(target_stops) item;
  if stop_count <> current_assignment_version
    or (select min((item->>'stop_order')::integer) from jsonb_array_elements(target_stops) item) <> 1
    or (select max((item->>'stop_order')::integer) from jsonb_array_elements(target_stops) item) <> stop_count then
    raise exception 'route_stop_order_invalid' using errcode = '22023';
  end if;

  insert into public.route_plans(
    branch_id, departure_at, vehicle_id, driver_employee_id, provider_state,
    provider_distance_meters, provider_duration_seconds, provider_error_safe,
    created_by, operation_id
  ) values (
    target_branch_id, target_departure_at, target_vehicle_id, target_driver_employee_id, target_provider_state,
    target_provider_distance_meters, target_provider_duration_seconds, nullif(left(trim(target_provider_error_safe), 300), ''),
    (select auth.uid()), operation_id
  ) returning id into plan_id;

  for stop in
    select * from jsonb_to_recordset(target_stops) as x(
      delivery_id uuid,
      stop_order integer,
      expected_delivery_version integer,
      expected_assignment_version integer,
      latitude numeric,
      longitude numeric,
      address_snapshot text,
      time_window_snapshot text,
      capacity_warning text,
      time_window_warning text
    ) order by stop_order
  loop
    select * into delivery from public.deliveries d where d.id = stop.delivery_id for update;
    if delivery.id is null or delivery.branch_id <> target_branch_id or delivery.execution_state not in ('PLANNED','ASSIGNED')
      or delivery.version  IS DISTINCT FROM stop.expected_delivery_version then
      raise exception 'route_delivery_stale' using errcode = 'PT409';
    end if;
    select coalesce(max(a.assignment_version), 0) into current_assignment_version
      from public.delivery_assignments a where a.delivery_id = delivery.id and a.superseded_at is null;
    if current_assignment_version  IS DISTINCT FROM stop.expected_assignment_version then
      raise exception 'route_assignment_stale' using errcode = 'PT409';
    end if;
    if nullif(trim(stop.address_snapshot), '') is null then
      raise exception 'route_address_required' using errcode = '22023';
    end if;
    insert into public.route_plan_stops(
      route_plan_id, stop_order, delivery_id, expected_delivery_version, expected_assignment_version,
      latitude, longitude, address_snapshot, time_window_snapshot, capacity_warning, time_window_warning
    ) values (
      plan_id, stop.stop_order, stop.delivery_id, stop.expected_delivery_version, stop.expected_assignment_version,
      stop.latitude, stop.longitude, trim(stop.address_snapshot), nullif(trim(stop.time_window_snapshot), ''),
      nullif(trim(stop.capacity_warning), ''), nullif(trim(stop.time_window_warning), '')
    );
  end loop;

  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_route_plan', payload_hash, 'route_plan', plan_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), target_branch_id, 'route_plan.created', 'route_plan', plan_id, operation_id,
    array['stops','vehicle','driver','departure','provider_state']);
  return plan_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_sales_order_draft(target_branch_id uuid, target_customer_id uuid, target_site_id uuid, requested_delivery_at timestamp with time zone, commercial_terms text, order_lines jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payload jsonb;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  customer public.customers%rowtype;
  site public.customer_sites%rowtype;
  order_id uuid;
  employee_id uuid;
  item jsonb;
  checked record;
  line_no integer := 0;
begin
  if not private.has_permission(target_branch_id, 'orders.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(order_lines) <> 'array' or jsonb_array_length(order_lines) = 0 then raise exception 'order_lines_required' using errcode = '22023'; end if;
  payload := jsonb_build_object('branch_id', target_branch_id, 'customer_id', target_customer_id, 'site_id', target_site_id, 'delivery_at', requested_delivery_at, 'terms', commercial_terms, 'lines', order_lines);
  payload_hash := private.command_payload_hash(payload);
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_sales_order_draft.operation_id;
  if found then
    if receipt.command_name <> 'create_sales_order_draft' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  perform private.require_quantity_lines(order_lines,array['quantity'],false);

  select * into customer from public.customers where id = target_customer_id and branch_id = target_branch_id and active;
  select * into site from public.customer_sites where id = target_site_id and customer_id = target_customer_id and active;
  if customer.id is null or site.id is null then raise exception 'customer_or_site_invalid' using errcode = '23503'; end if;
  employee_id := private.current_employee_id();
  insert into public.sales_orders(branch_id, order_number, customer_id, site_id, sales_owner_employee_id,
    customer_name_snapshot, site_name_snapshot, delivery_address_snapshot, receiver_name_snapshot, receiver_phone_snapshot,
    requested_delivery_at, commercial_terms, created_by)
  values (target_branch_id, 'SO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.sales_order_number_seq')::text, 6, '0'),
    target_customer_id, target_site_id, employee_id, customer.display_name, site.name, site.address_text, site.receiver_name, site.receiver_phone,
    requested_delivery_at, commercial_terms, (select auth.uid())) returning id into order_id;
  for item in select value from jsonb_array_elements(order_lines) loop
    line_no := line_no + 1;
    select * into checked from private.assert_commercial_line(target_branch_id, target_customer_id, item, (select auth.uid()));
    insert into public.sales_order_lines(sales_order_id, line_number, material_id, material_name_snapshot, ordered_uom_id, base_uom_id,
      quantity, conversion_numerator, conversion_denominator, rounding_mode, unit_price_vnd, line_total_vnd,
      pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason)
    values (order_id, line_no, checked.material_id, checked.material_name, checked.ordered_uom_id, checked.base_uom_id,
      checked.quantity, checked.conversion_numerator, checked.conversion_denominator, checked.rounding_mode,
      checked.unit_price_vnd, checked.line_total_vnd, checked.pricing_rule_id, checked.pricing_rule_version,
      checked.price_source_type, checked.override_by, checked.override_reason);
  end loop;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_sales_order_draft', payload_hash, 'sales_order', order_id, now());
  return order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_sales_order_from_quote(source_revision_id uuid, requested_delivery_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare revision public.quotation_revisions%rowtype; quote public.quotations%rowtype; hash text; receipt public.command_receipts%rowtype; order_id uuid; existing_id uuid;
begin
  select r.* into revision from public.quotation_revisions r where r.id = source_revision_id for update;
  select q.* into quote from public.quotations q where q.id = revision.quotation_id;
  if not private.has_permission(quote.branch_id, 'orders.create') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('source_revision_id', source_revision_id, 'delivery_at', requested_delivery_at));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_sales_order_from_quote.operation_id;
  if found then if receipt.command_name <> 'create_sales_order_from_quote' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  select id into existing_id from public.sales_orders where quotation_revision_id = source_revision_id;
  if existing_id is not null then
    insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_sales_order_from_quote', hash, 'sales_order', existing_id, now());
    return existing_id;
  end if;
  if revision.state <> 'ACCEPTED' then raise exception 'quote_revision_not_accepted' using errcode = '23514'; end if;
  insert into public.sales_orders(branch_id, order_number, customer_id, site_id, quotation_revision_id,
    sales_owner_employee_id, customer_name_snapshot, site_name_snapshot, delivery_address_snapshot,
    receiver_name_snapshot, receiver_phone_snapshot, requested_delivery_at, commercial_terms, created_by)
  values (quote.branch_id, 'SO-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.sales_order_number_seq')::text, 6, '0'),
    quote.customer_id, quote.site_id, source_revision_id, quote.sales_owner_employee_id, revision.customer_name_snapshot,
    revision.site_name_snapshot, revision.delivery_address_snapshot, revision.receiver_name_snapshot,
    revision.receiver_phone_snapshot, requested_delivery_at, revision.commercial_terms, (select auth.uid()))
  returning id into order_id;
  insert into public.sales_order_lines(sales_order_id, quotation_line_id, line_number, material_id, material_name_snapshot,
    ordered_uom_id, base_uom_id, quantity, conversion_numerator, conversion_denominator, rounding_mode,
    unit_price_vnd, line_total_vnd, pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason)
  select order_id, id, line_number, material_id, material_name_snapshot, ordered_uom_id, base_uom_id, quantity,
    conversion_numerator, conversion_denominator, rounding_mode, unit_price_vnd, line_total_vnd,
    pricing_rule_id, pricing_rule_version, price_source_type, override_by, override_reason
  from public.quotation_lines where revision_id = source_revision_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_sales_order_from_quote', hash, 'sales_order', order_id, now());
  return order_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_service_job(target_branch_id uuid, target_customer_id uuid, target_site_id uuid, service_type text, description text, scheduled_start timestamp with time zone, scheduled_end timestamp with time zone, planned_quantity numeric, unit_label text, target_sales_employee_id uuid, target_vehicle_id uuid, target_machine_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload_hash text; receipt public.command_receipts%rowtype; entity_id uuid;
begin
  if not private.has_permission(target_branch_id, 'service.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(trim(service_type)) not between 2 and 120 or char_length(trim(description)) not between 3 and 500
    or scheduled_end <= scheduled_start or planned_quantity <= 0 or char_length(trim(unit_label)) not between 1 and 30
    or num_nonnulls(target_vehicle_id, target_machine_id) > 1 then raise exception 'invalid_service_job' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('branch',target_branch_id,'customer',target_customer_id,'site',target_site_id,'type',trim(service_type),'description',trim(description),'start',scheduled_start,'end',scheduled_end,'quantity',planned_quantity,'unit',trim(unit_label),'sales',target_sales_employee_id,'vehicle',target_vehicle_id,'machine',target_machine_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_service_job.operation_id;
  if found then
    if receipt.command_name <> 'create_service_job' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  perform private.require_exact_quantity(planned_quantity,false);

  perform 1 from public.customers c join public.customer_sites s on s.customer_id = c.id
  where c.id = target_customer_id and c.branch_id = target_branch_id and c.active and s.id = target_site_id and s.active;
  if not found then raise exception 'invalid_customer_site' using errcode = '23503'; end if;
  if target_sales_employee_id is not null then
    perform 1 from public.employee_branch_access where employee_id = target_sales_employee_id and branch_id = target_branch_id and active;
    if not found then raise exception 'invalid_sales_employee' using errcode = '23503'; end if;
  end if;
  if target_vehicle_id is not null then perform 1 from public.vehicles where id = target_vehicle_id and branch_id = target_branch_id and active; if not found then raise exception 'invalid_vehicle' using errcode = '23503'; end if; end if;
  if target_machine_id is not null then perform 1 from public.machines where id = target_machine_id and branch_id = target_branch_id and active; if not found then raise exception 'invalid_machine' using errcode = '23503'; end if; end if;
  insert into public.service_jobs(branch_id,job_number,customer_id,site_id,sales_employee_id,service_type,description,scheduled_start,scheduled_end,planned_quantity,unit_label,vehicle_id,machine_id,created_by)
  values (target_branch_id,'SRV-'||to_char((scheduled_start at time zone 'Asia/Ho_Chi_Minh')::date,'YYYYMM')||'-'||lpad(nextval('public.service_job_number_seq')::text,6,'0'),target_customer_id,target_site_id,target_sales_employee_id,trim(service_type),trim(description),scheduled_start,scheduled_end,planned_quantity,trim(unit_label),target_vehicle_id,target_machine_id,(select auth.uid())) returning id into entity_id;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'create_service_job',payload_hash,'service_job',entity_id,now());
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values((select auth.uid()),target_branch_id,'service_job.created','service_job',entity_id,operation_id,array['schedule','planned_quantity','resources']);
  return entity_id;
end
$function$

CREATE OR REPLACE FUNCTION public.create_supplier_quick(target_branch_id uuid, supplier_code text, supplier_name text, supplier_phone text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare normalized_code text; hash text; receipt public.command_receipts%rowtype; supplier_id uuid;
begin
  if not (private.has_permission(target_branch_id, 'suppliers.manage') or private.has_permission(target_branch_id, 'purchasing.create')) then raise exception 'forbidden' using errcode = '42501'; end if;
  normalized_code := upper(trim(supplier_code));
  if normalized_code !~ '^[A-Z0-9_-]{2,32}$' or char_length(trim(supplier_name)) < 2 then raise exception 'supplier_invalid' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('branch_id', target_branch_id, 'code', normalized_code, 'name', trim(supplier_name), 'phone', nullif(trim(supplier_phone), '')));
  select * into receipt from public.command_receipts where command_receipts.operation_id = create_supplier_quick.operation_id;
  if found then if receipt.command_name <> 'create_supplier_quick' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  insert into public.suppliers(branch_id, code, name, phone)
  values (target_branch_id, normalized_code, trim(supplier_name), nullif(trim(supplier_phone), ''))
  on conflict (branch_id, code) do nothing
  returning id into supplier_id;
  if supplier_id is null then raise exception 'supplier_code_exists' using errcode = '23505'; end if;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'create_supplier_quick', hash, 'supplier', supplier_id, now());
  return supplier_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_supplier_return(target_branch_id uuid, target_receipt_line_id uuid, target_fulfillment_line_id uuid, target_custody_case_id uuid, requested_base_quantity numeric, return_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare src record;rc public.return_cases%rowtype;r public.command_receipts%rowtype;h text;case_id uuid;used numeric;
begin
 if not private.has_permission(target_branch_id,'purchasing.create') then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'create_supplier_return');perform pg_advisory_xact_lock(hashtextextended('supplier_return:'||operation_id::text,0));
 perform private.require_exact_quantity(requested_base_quantity);
 if operation_id is null or num_nonnulls(target_receipt_line_id,target_fulfillment_line_id)<>1 or return_reason is null or char_length(trim(return_reason)) not between 3 and 500 then raise exception 'invalid_supplier_return' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_branch_id,target_receipt_line_id,target_fulfillment_line_id,target_custody_case_id,requested_base_quantity,trim(return_reason)));
 select * into r from public.command_receipts where command_receipts.operation_id=create_supplier_return.operation_id;
 if found then if r.command_name<>'create_supplier_return' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 if target_receipt_line_id is not null then
  perform 1 from public.purchase_receipt_lines l where l.id=target_receipt_line_id for update;
  select p.supplier_id,l.material_id,pl.base_uom_id,l.warehouse_id,l.received_base_quantity qty,l.inventory_value_vnd val,o.id payable_id into src
   from public.purchase_receipt_lines l join public.purchase_receipts pr on pr.id=l.purchase_receipt_id
   join public.purchase_orders p on p.id=pr.purchase_order_id join public.purchase_order_lines pl on pl.id=l.purchase_order_line_id
   join public.payable_obligations o on o.purchase_receipt_id=pr.id
   where l.id=target_receipt_line_id and p.branch_id=target_branch_id and pr.branch_id=target_branch_id and o.branch_id=target_branch_id;
  if target_custody_case_id is not null then raise exception 'warehouse_supplier_return_custody_source_invalid' using errcode='23514';end if;
 else
  perform 1 from public.supplier_fulfillment_lines l where l.id=target_fulfillment_line_id for update;
  select p.supplier_id,pl.material_id,pl.base_uom_id,null::uuid warehouse_id,l.supplier_base_quantity qty,l.payable_amount_vnd val,o.id payable_id into src
   from public.supplier_fulfillment_lines l join public.supplier_fulfillments sf on sf.id=l.supplier_fulfillment_id
   join public.purchase_orders p on p.id=sf.purchase_order_id join public.purchase_order_lines pl on pl.id=l.purchase_order_line_id
   join public.materials m on m.id=pl.material_id join public.payable_obligations o on o.supplier_fulfillment_id=sf.id
   where l.id=target_fulfillment_line_id and p.branch_id=target_branch_id and sf.branch_id=target_branch_id and o.branch_id=target_branch_id;
  select * into rc from public.return_cases where id=target_custody_case_id for update;
  if rc.id is null or rc.branch_id<>target_branch_id or not(rc.state='OPEN' or(rc.state='RETURNED' and rc.resolution_warehouse_id is not null)) or rc.case_kind not in('CUSTOMER_RETURN','TRANSIT_REMAINDER')
   or (rc.state='OPEN' and rc.base_quantity<>requested_base_quantity) or not exists(select 1 from public.delivery_lines dl join public.supply_allocations sa on sa.id=dl.supply_allocation_id
    join public.supplier_fulfillment_lines fl on fl.purchase_order_line_id=sa.purchase_order_line_id and fl.sales_order_line_id=dl.sales_order_line_id
    where dl.id=rc.delivery_line_id and dl.source_mode='SUPPLIER_DIRECT' and fl.id=target_fulfillment_line_id)
   or requested_base_quantity+coalesce((select sum(case when other.dispatch_closed then coalesce((select sum(e.base_quantity) from public.supplier_return_events e where e.case_id=other.id and e.event_kind='PHYSICAL_RETURN'),0) else other.requested_base_quantity end) from public.supplier_return_cases other where other.source_return_case_id=rc.id),0)>rc.base_quantity
  then raise exception 'direct_supplier_return_requires_recorded_custody_source' using errcode='23514';end if;
  if rc.state='RETURNED' then src.warehouse_id:=rc.resolution_warehouse_id;end if;
 end if;
 if src is null or src.payable_id is null then raise exception 'supplier_return_source_missing_or_scope_mismatch' using errcode='23514';end if;
 select coalesce(sum(case when c.dispatch_closed then coalesce((select sum(e.base_quantity) from public.supplier_return_events e where e.case_id=c.id and e.event_kind='PHYSICAL_RETURN'),0) else c.requested_base_quantity end),0) into used
 from public.supplier_return_cases c where (target_receipt_line_id is not null and c.source_receipt_line_id=target_receipt_line_id) or(target_fulfillment_line_id is not null and c.source_fulfillment_line_id=target_fulfillment_line_id);
 if requested_base_quantity+used>src.qty then raise exception 'supplier_return_exceeds_source_quantity' using errcode='23514';end if;
 insert into public.supplier_return_cases(branch_id,supplier_id,return_number,source_receipt_line_id,source_fulfillment_line_id,source_return_case_id,source_payable_id,material_id,base_uom_id,warehouse_id,requested_base_quantity,source_base_quantity,source_value_vnd,reason,created_by)
 values(target_branch_id,src.supplier_id,'SR-'||lpad(nextval('public.supplier_return_number_seq')::text,8,'0'),target_receipt_line_id,target_fulfillment_line_id,target_custody_case_id,src.payable_id,src.material_id,src.base_uom_id,src.warehouse_id,requested_base_quantity,src.qty,src.val,trim(return_reason),auth.uid()) returning id into case_id;
 insert into public.command_receipts values(operation_id,auth.uid(),'create_supplier_return',h,'supplier_return_case',case_id,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields)
 values(auth.uid(),target_branch_id,'supplier_return.created','supplier_return_case',case_id,operation_id,array['source_receipt_line_id','source_fulfillment_line_id','source_return_case_id','requested_base_quantity']);
 return case_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_warehouse_transfer(target_branch_id uuid, from_warehouse_id uuid, to_warehouse_id uuid, target_material_id uuid, planned_base_quantity numeric, transfer_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.command_receipts%rowtype;h text;tid uuid;u uuid;
begin
 if not private.has_permission(target_branch_id,'inventory.reserve') then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'create_warehouse_transfer');perform pg_advisory_xact_lock(hashtextextended('warehouse_transfer:'||operation_id::text,0));
 perform private.require_exact_quantity(planned_base_quantity);
 if operation_id is null or transfer_reason is null or char_length(trim(transfer_reason)) not between 3 and 500 then raise exception 'invalid_transfer' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_branch_id,from_warehouse_id,to_warehouse_id,target_material_id,planned_base_quantity,trim(transfer_reason)));
 select * into r from public.command_receipts where command_receipts.operation_id=create_warehouse_transfer.operation_id;
 if found then if r.command_name<>'create_warehouse_transfer' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 if from_warehouse_id is null or to_warehouse_id is null or from_warehouse_id=to_warehouse_id or (select count(*) from public.warehouses w where w.id in(from_warehouse_id,to_warehouse_id) and w.branch_id=target_branch_id and w.active)<>2 then raise exception 'transfer_warehouse_scope_mismatch' using errcode='23514';end if;
 select base_uom_id into u from public.materials where id=target_material_id and active;if u is null then raise exception 'material_not_found' using errcode='23503';end if;
 insert into public.warehouse_transfers(branch_id,transfer_number,from_warehouse_id,to_warehouse_id,material_id,base_uom_id,planned_base_quantity,reason,created_by)
 values(target_branch_id,'WT-'||lpad(nextval('public.warehouse_transfer_number_seq')::text,8,'0'),from_warehouse_id,to_warehouse_id,target_material_id,u,planned_base_quantity,trim(transfer_reason),auth.uid()) returning id into tid;
 insert into public.command_receipts values(operation_id,auth.uid(),'create_warehouse_transfer',h,'warehouse_transfer',tid,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values(auth.uid(),target_branch_id,'warehouse_transfer.created','warehouse_transfer',tid,operation_id,array['from_warehouse_id','to_warehouse_id','material_id','planned_base_quantity']);
 return tid;
end $function$

CREATE OR REPLACE FUNCTION public.customer_credit_balances(target_credit_id uuid)
 RETURNS TABLE(remaining_vnd bigint, refunded_vnd bigint, offset_vnd bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.customer_credits%rowtype;
begin
 select * into c from public.customer_credits where id=target_credit_id;
 if c.id is null or not private.has_permission(c.branch_id,'finance.ar.read') then return;end if;
 return query select private.customer_credit_remaining(c.id),
  coalesce((select sum(s.amount_delta_vnd) from public.customer_credit_settlements s join public.customer_credit_funds f on f.id=s.credit_fund_id
    where f.credit_id=c.id and s.settlement_kind='REFUND'),0)::bigint,
  coalesce((select sum(s.amount_delta_vnd) from public.customer_credit_settlements s join public.customer_credit_funds f on f.id=s.credit_fund_id
    where f.credit_id=c.id and s.settlement_kind='OFFSET'),0)::bigint;
end $function$

CREATE OR REPLACE FUNCTION public.customer_portal_snapshot(target_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  selected_customer_id uuid;
  member_role text;
  customer_json jsonb;
  quote_json jsonb;
  orders_json jsonb;
  debt_json jsonb;
  notices_json jsonb;
begin
  select m.customer_id, m.membership_role::text
  into selected_customer_id, member_role
  from public.customer_portal_memberships m
  where m.auth_user_id = (select auth.uid())
    and m.active
    and (target_customer_id is null or m.customer_id = target_customer_id)
  order by m.customer_id
  limit 1;
  if selected_customer_id is null then raise exception 'active_customer_membership_required' using errcode = '42501'; end if;

  select jsonb_build_object('id', c.id, 'code', c.code, 'display_name', c.display_name)
  into customer_json from public.customers c where c.id = selected_customer_id;

  if member_role in ('OWNER','FINANCE_CONTACT') then
    select jsonb_strip_nulls(jsonb_build_object(
      'id', item->>'id',
      'number', coalesce(item->>'quotation_number', item->>'number'),
      'state', coalesce(item->>'quotation_state', item->>'status'),
      'current_revision_id', item->>'current_revision_id',
      'valid_until', item->>'valid_until'
    )) into quote_json
    from (
      select to_jsonb(q) item
      from public.quotations q
      where to_jsonb(q)->>'customer_id' = selected_customer_id::text
      order by to_jsonb(q)->>'created_at' desc nulls last, q.id desc
      limit 1
    ) quote_row;
  end if;

  select coalesce(jsonb_agg(private.customer_order_payload(o.id) order by o.id desc), '[]'::jsonb)
  into orders_json
  from public.sales_orders o
  where to_jsonb(o)->>'customer_id' = selected_customer_id::text;

  if member_role in ('OWNER','FINANCE_CONTACT') then
    select jsonb_build_object(
      'outstanding_amount_vnd', coalesce(sum((item->>'outstanding_amount_vnd')::bigint), 0),
      'overdue_amount_vnd', coalesce(sum((item->>'outstanding_amount_vnd')::bigint) filter (
        where nullif(item->>'due_date', '') is not null and (item->>'due_date')::date < current_date
      ), 0),
      'items', coalesce(
        jsonb_agg(
          jsonb_strip_nulls(jsonb_build_object(
            'id', item->>'id',
            'source_type', item->>'source_type',
            'source_number', coalesce(item->>'source_number', item->>'reference_number'),
            'original_amount_vnd', item->>'original_amount_vnd',
            'outstanding_amount_vnd', item->>'outstanding_amount_vnd',
            'due_date', item->>'due_date'
          ))
          order by item->>'due_date' nulls first
        ),
        '[]'::jsonb
      )
    ) into debt_json
    from (
      select to_jsonb(r) item
      from public.receivable_read r
      where to_jsonb(r)->>'customer_id' = selected_customer_id::text
        and coalesce((to_jsonb(r)->>'outstanding_amount_vnd')::bigint, 0) > 0
    ) debt_rows;

    select coalesce(jsonb_agg(jsonb_build_object(
      'id', n.id,
      'amount_vnd', n.declared_amount_vnd,
      'paid_on', n.paid_on,
      'reference', n.payment_reference,
      'state', n.review_state,
      'version', n.version,
      'submitted_at', n.submitted_at,
      'evidence_id', n.evidence_id,
      'review_note', n.review_note
    ) order by n.submitted_at desc), '[]'::jsonb)
    into notices_json
    from public.payment_notices n
    where n.customer_id = selected_customer_id;
  else
    debt_json := null;
    notices_json := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'customer', customer_json,
    'membership_role', member_role,
    'can_view_debt', member_role in ('OWNER','FINANCE_CONTACT'),
    'quotation', quote_json,
    'orders', orders_json,
    'debt', debt_json,
    'payment_notices', notices_json
  );
end $function$

CREATE OR REPLACE FUNCTION public.customer_safe_quotation_lines(target_revision_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_branch_id uuid;
  target_customer_id uuid;
  safe_lines jsonb;
begin
  select q.branch_id, q.customer_id into target_branch_id, target_customer_id
  from public.quotation_revisions r
  join public.quotations q on q.id = r.quotation_id
  where r.id = target_revision_id;

  if target_branch_id is null or not (
    coalesce(private.has_permission(target_branch_id, 'quotation.read'), false)
    or coalesce(private.has_customer_membership(target_customer_id, null::text[]), false)
  ) then
    raise exception 'quotation_access_denied' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', l.id,
    'material_name_snapshot', l.material_name_snapshot,
    'quantity', l.quantity::text,
    'unit_price_vnd', l.unit_price_vnd::text,
    'line_total_vnd', l.line_total_vnd::text,
    'uom_symbol', u.symbol
  ) order by l.line_number, l.id), '[]'::jsonb)
  into safe_lines
  from public.quotation_lines l
  left join public.units_of_measure u on u.id = l.ordered_uom_id
  where l.revision_id = target_revision_id;

  return safe_lines;
end
$function$

CREATE OR REPLACE FUNCTION public.deactivate_pricing_rule(target_id uuid, target_branch_id uuid, expected_version integer, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_rule public.pricing_rules%rowtype; receipt public.command_receipts%rowtype; payload_hash text;
begin
  if auth.uid() is null or not private.has_permission(target_branch_id, 'pricing.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if target_id is null or operation_id is null or char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('target',target_id,'branch',target_branch_id,'version',expected_version,'reason',change_reason));
  perform pg_advisory_xact_lock(hashtextextended(operation_id::text,0));
  select * into receipt from public.command_receipts r where r.operation_id=deactivate_pricing_rule.operation_id;
  if found then
   if receipt.command_name<>'deactivate_pricing_rule' or receipt.payload_hash<>payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;
   return receipt.result_entity_id;
  end if;
  select * into old_rule from public.pricing_rules where id = target_id and branch_id = target_branch_id for update;
  if old_rule.id is null or old_rule.version  IS DISTINCT FROM expected_version or not old_rule.active then raise exception 'stale_price_rule' using errcode = 'PT409'; end if;
  update public.pricing_rules set active = false where id = target_id;
  insert into public.command_receipts values(operation_id,auth.uid(),'deactivate_pricing_rule',payload_hash,'pricing_rule',target_id,now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason)
  values(auth.uid(), target_branch_id, 'pricing.deactivate', 'pricing_rules', target_id, operation_id, array['active'], change_reason);
  return target_id;
end $function$

