CREATE OR REPLACE FUNCTION public.finance_obligation_snapshot(target_branch_id uuid, target_side text, as_of timestamp with time zone, knowledge_cutoff timestamp with time zone, target_customer_id uuid DEFAULT NULL::uuid, target_site_id uuid DEFAULT NULL::uuid, target_sales_employee_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(obligation_id uuid, party_id uuid, party_name text, site_id uuid, site_name text, source_type text, source_id uuid, due_date date, outstanding_amount_vnd bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare effective_as_of timestamptz:=least(as_of,now()); effective_cutoff timestamptz:=least(knowledge_cutoff,now());
begin
  if target_side='AR' then
    if not private.has_permission(target_branch_id,'finance.ar.read') then raise exception 'forbidden' using errcode='42501'; end if;
    return query select r.id,r.customer_id,c.display_name,r.site_id,cs.name,case when r.opening_source_id is not null then 'OPENING_BALANCE' when r.delivery_verification_id is not null then 'DELIVERY_VERIFICATION' else 'SERVICE_VERIFICATION' end::text,coalesce(r.opening_source_id,r.delivery_verification_id,r.service_verification_id),r.due_date,(r.original_amount_vnd+coalesce((select sum(a.amount_delta_vnd) from public.receivable_adjustments a where a.obligation_id=r.id and a.recorded_at<=effective_as_of and a.recorded_at<=effective_cutoff),0)-coalesce((select sum(a.amount_delta_vnd) from public.payment_allocations a where a.receivable_obligation_id=r.id and a.allocated_at<=effective_as_of and a.allocated_at<=effective_cutoff),0))::bigint
    from public.receivable_obligations r join public.customers c on c.id=r.customer_id left join public.customer_sites cs on cs.id=r.site_id left join public.delivery_verifications dv on dv.id=r.delivery_verification_id left join public.deliveries d on d.id=dv.delivery_id left join public.sales_orders so on so.id=d.sales_order_id left join public.service_verifications sv on sv.id=r.service_verification_id left join public.service_jobs sj on sj.id=sv.service_job_id
    where r.branch_id=target_branch_id and r.recorded_at<=effective_as_of and r.recorded_at<=effective_cutoff and (target_customer_id is null or r.customer_id=target_customer_id) and (target_site_id is null or r.site_id=target_site_id) and (target_sales_employee_id is null or coalesce(so.sales_owner_employee_id,sj.sales_employee_id)=target_sales_employee_id);
  elsif target_side='AP' then
    if not private.has_permission(target_branch_id,'finance.ap.read') then raise exception 'forbidden' using errcode='42501'; end if;
    if target_customer_id is not null or target_site_id is not null or target_sales_employee_id is not null then return; end if;
    return query select p.id,coalesce(p.supplier_id,p.employee_id),coalesce(s.name,e.display_name),null::uuid,null::text,case when p.opening_source_id is not null then 'OPENING_BALANCE' when p.purchase_receipt_id is not null then 'PURCHASE_RECEIPT' when p.supplier_fulfillment_id is not null then 'SUPPLIER_FULFILLMENT' when p.expense_id is not null then 'EXPENSE' else 'EARNING_EVENT' end::text,coalesce(p.opening_source_id,p.purchase_receipt_id,p.supplier_fulfillment_id,p.expense_id,p.earning_event_id),p.due_date,(p.original_amount_vnd+coalesce((select sum(a.amount_delta_vnd) from public.payable_adjustments a where a.obligation_id=p.id and a.recorded_at<=effective_as_of and a.recorded_at<=effective_cutoff),0)-coalesce((select sum(a.amount_delta_vnd) from public.payment_allocations a where a.payable_obligation_id=p.id and a.allocated_at<=effective_as_of and a.allocated_at<=effective_cutoff),0))::bigint
    from public.payable_obligations p left join public.suppliers s on s.id=p.supplier_id left join public.employees e on e.id=p.employee_id where p.branch_id=target_branch_id and p.recorded_at<=effective_as_of and p.recorded_at<=effective_cutoff;
  else raise exception 'invalid_obligation_side' using errcode='22023'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.get_command_draft(target_operation_id uuid, target_command text, target_branch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d private.command_drafts%rowtype; permission text;
begin
 if target_operation_id is null or target_command is null or target_command not in('post_payment','receive_purchase_order','verify_supplier_fulfillment','allocate_payment','adjust_return_receivable','refund_customer_credit','offset_customer_credit','reverse_customer_credit_offset','resolve_commission_reconciliation','create_delivery_expense','approve_expense','create_warehouse_transfer','record_warehouse_transfer_event','create_supplier_return','record_supplier_return_event','approve_supplier_return_credit','refund_supplier_credit','offset_supplier_credit','register_supplier_document','review_supplier_document','create_invoice_draft','approve_invoice_business','cancel_invoice_draft','create_invoice_adjustment_draft','register_purchase_invoice_source','match_payment_notice','review_payment_notice','record_payment_reconciliation','reverse_payment_notice_match')
 then raise exception 'invalid_command_lookup' using errcode='22023';end if;
 permission:=case target_command when 'post_payment' then 'finance.payment.post' when 'allocate_payment' then 'finance.payment.post' when 'adjust_return_receivable' then 'finance.ar.adjust' when 'refund_customer_credit' then 'finance.payment.post' when 'offset_customer_credit' then 'finance.payment.post' when 'reverse_customer_credit_offset' then 'finance.payment.reverse' when 'resolve_commission_reconciliation' then 'compensation.manage' when 'create_delivery_expense' then 'finance.expense.manage' when 'approve_expense' then 'finance.expense.manage' when 'create_warehouse_transfer' then 'inventory.read' when 'record_warehouse_transfer_event' then 'inventory.read' when 'create_supplier_return' then 'purchasing.create' when 'record_supplier_return_event' then case when private.has_permission(target_branch_id,'inventory.reserve') then 'inventory.reserve' when private.has_permission(target_branch_id,'purchasing.confirm') then 'purchasing.confirm' else 'purchasing.cancel' end when 'approve_supplier_return_credit' then 'finance.ap.adjust' when 'refund_supplier_credit' then 'finance.payment.post' when 'offset_supplier_credit' then 'finance.payment.post' when 'register_supplier_document' then 'finance.ap.adjust' when 'review_supplier_document' then 'finance.ap.read' when 'create_invoice_draft' then 'finance.ar.adjust' when 'approve_invoice_business' then 'finance.reconcile' when 'cancel_invoice_draft' then 'finance.ar.adjust' when 'create_invoice_adjustment_draft' then 'finance.ar.adjust' when 'register_purchase_invoice_source' then 'finance.ap.adjust' when 'review_payment_notice' then 'finance.payment_notice.review' when 'match_payment_notice' then 'finance.payment_notice.review' when 'record_payment_reconciliation' then 'finance.reconcile' when 'reverse_payment_notice_match' then 'finance.payment_notice.review' else 'inventory.receive' end;
 if not private.has_permission(target_branch_id,permission) then raise exception 'forbidden' using errcode='42501';end if;
 select * into d from private.command_drafts where operation_id=target_operation_id and actor_auth_user_id=(select auth.uid())
 and branch_id=target_branch_id and command_name=target_command;
 if d.operation_id is null then return null;end if;
 return jsonb_build_object('operation_id',d.operation_id,'entries',d.form_entries);
end $function$

CREATE OR REPLACE FUNCTION public.get_portal_evidence_for_signing(target_evidence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
