CREATE OR REPLACE FUNCTION public.publish_work_item(target_branch_id uuid, source_kind text, source_id uuid, requested_assignment_mode text, target_employee_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload_hash text; receipt public.command_receipts%rowtype; entity_id uuid; title text; start_at timestamptz; end_at timestamptz; vehicle uuid; machine uuid; employee uuid := target_employee_id; source_delivery uuid; source_service uuid;
begin
  if not private.has_permission(target_branch_id, 'work.manage') then raise exception 'forbidden' using errcode = '42501'; end if;
  if source_kind not in ('DELIVERY','SERVICE_JOB') or requested_assignment_mode not in ('DIRECT','POOL_CLAIM') then raise exception 'invalid_work_source' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('branch',target_branch_id,'kind',source_kind,'source',source_id,'mode',requested_assignment_mode,'employee',target_employee_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = publish_work_item.operation_id;
  if found then
    if receipt.command_name <> 'publish_work_item' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  if source_kind = 'SERVICE_JOB' then
    select j.id,j.service_type||' - '||j.job_number,j.scheduled_start,j.scheduled_end,j.vehicle_id,j.machine_id into source_service,title,start_at,end_at,vehicle,machine
    from public.service_jobs j where j.id=source_id and j.branch_id=target_branch_id and j.execution_state='SCHEDULED' for update;
    if source_service is null then raise exception 'service_not_ready' using errcode = '55000'; end if;
  else
    if requested_assignment_mode <> 'DIRECT' then raise exception 'delivery_requires_direct_assignment' using errcode = '22023'; end if;
    select d.id,'Giao hàng - '||d.delivery_number,d.scheduled_at,coalesce(d.scheduled_end_at,d.scheduled_at+interval '4 hours'),a.vehicle_id,a.employee_id into source_delivery,title,start_at,end_at,vehicle,employee
    from public.deliveries d join public.delivery_assignments a on a.delivery_id=d.id and a.superseded_at is null
    where d.id=source_id and d.branch_id=target_branch_id and d.execution_state='ASSIGNED' and d.scheduled_at is not null for update of d;
    if source_delivery is null or employee is null then raise exception 'delivery_not_ready_for_work' using errcode = '55000'; end if;
    if exists (select 1 from public.deliveries d where d.id = source_delivery
        and (nullif(trim(d.delivery_address_snapshot),'') is null
          or nullif(trim(d.receiver_name_snapshot),'') is null
          or nullif(trim(d.receiver_phone_snapshot),'') is null))
      or not exists (select 1 from public.delivery_lines l where l.delivery_id = source_delivery and l.planned_base_quantity > 0) then
      raise exception 'delivery_contact_or_lines_missing' using errcode = '55000';
    end if;
  end if;
  if requested_assignment_mode='DIRECT' and employee is null then raise exception 'direct_employee_required' using errcode = '22023'; end if;
  if requested_assignment_mode='POOL_CLAIM' and employee is not null then raise exception 'pool_cannot_preassign_employee' using errcode = '22023'; end if;
  insert into public.work_items(branch_id,work_number,delivery_id,service_job_id,title,assignment_mode,execution_state,scheduled_start,scheduled_end,planned_vehicle_id,planned_machine_id,created_by)
  values(target_branch_id,'WRK-'||to_char((start_at at time zone 'Asia/Ho_Chi_Minh')::date,'YYYYMM')||'-'||lpad(nextval('public.work_item_number_seq')::text,6,'0'),source_delivery,source_service,title,requested_assignment_mode,case when employee is null then 'AVAILABLE' else 'CLAIMED' end,start_at,end_at,vehicle,machine,(select auth.uid())) returning id into entity_id;
  if employee is not null then
    perform private.assert_work_resources_available(entity_id,target_branch_id,employee,vehicle,machine,start_at,end_at);
    insert into public.work_item_assignments(work_item_id,assignment_version,employee_id,vehicle_id,machine_id,assignment_kind,assigned_by) values(entity_id,1,employee,vehicle,machine,'DIRECT',(select auth.uid()));
  end if;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'publish_work_item',payload_hash,'work_item',entity_id,now());
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values((select auth.uid()),target_branch_id,'work_item.published','work_item',entity_id,operation_id,array['source','assignment_mode','schedule']);
  return entity_id;
end
$function$

CREATE OR REPLACE FUNCTION public.reactivate_employee_access(target_access_id uuid, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.employee_branch_access%rowtype;
begin
  select * into a from public.employee_branch_access where id = target_access_id for update;
  if auth.uid() is null or a.id is null
    or not private.has_permission(a.branch_id, 'roles.manage')
    or a.employee_id = private.current_employee_id()
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'reason_required' using errcode = '22023';
  end if;
  if a.active then return a.id; end if;
  if not exists (select 1 from public.employees e where e.id = a.employee_id and e.active) then
    raise exception 'employee_inactive' using errcode = '23514';
  end if;
  if not exists (select 1 from public.roles r where r.id = a.role_id and r.active) then
    raise exception 'role_inactive' using errcode = '23514';
  end if;
  if exists (
    select 1 from public.employee_branch_access current_access
    where current_access.employee_id = a.employee_id
      and current_access.branch_id = a.branch_id
      and current_access.active
  ) then
    raise exception 'access_already_active' using errcode = '23505';
  end if;
  if exists (
    select 1 from public.role_permissions rp
    where rp.role_id = a.role_id
      and not private.has_permission(a.branch_id, rp.permission_code)
  ) then
    raise exception 'role_exceeds_actor_permissions' using errcode = '42501';
  end if;

  update public.employee_branch_access
  set active = true, revoked_at = null, granted_at = now()
  where id = a.id;

  insert into public.audit_events(
    actor_auth_user_id, branch_id, action, entity_type, entity_id,
    trace_id, changed_fields, reason
  ) values (
    auth.uid(), a.branch_id, 'employee.access.reactivate', 'employee_branch_access', a.id,
    operation_id, array['active'], trim(change_reason)
  );
  return a.id;
end
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_order(target_purchase_order_id uuid, receipt_lines jsonb, target_evidence_id uuid, received_at timestamp with time zone, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_row public.purchase_orders%rowtype; line public.purchase_order_lines%rowtype;
  item jsonb; prior_quantity numeric; received_quantity numeric; base_quantity numeric;
  inventory_value bigint; unit_cost_base numeric; total_value bigint := 0; receipt_id uuid; receipt_line_id uuid;
  hash text; command_receipt public.command_receipts%rowtype;
begin
  select * into order_row from public.purchase_orders where id = target_purchase_order_id for update;
  if order_row.id is null or not private.has_permission(order_row.branch_id, 'inventory.receive') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('purchase_order_id', target_purchase_order_id, 'lines', receipt_lines, 'evidence_id', target_evidence_id, 'received_at', received_at));
  perform private.lock_saved_command_intent(receive_purchase_order.operation_id,'receive_purchase_order');
  select * into command_receipt from public.command_receipts where command_receipts.operation_id = receive_purchase_order.operation_id;
  if found then if command_receipt.command_name <> 'receive_purchase_order' or command_receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return command_receipt.result_entity_id; end if;
  perform private.require_quantity_lines(receipt_lines,array['received_quantity'],false);

  if order_row.state <> 'CONFIRMED' or order_row.destination_type <> 'WAREHOUSE' or jsonb_array_length(receipt_lines) = 0 or received_at > now() + interval '5 minutes' then raise exception 'purchase_order_not_receivable' using errcode = '23514'; end if;
  perform private.assert_verified_evidence(target_evidence_id, order_row.branch_id);
  perform 1 from public.warehouses where id = order_row.warehouse_id for update;
  insert into public.purchase_receipts(branch_id, purchase_order_id, receipt_number, received_at, evidence_object_id, recorded_by)
  values (order_row.branch_id, target_purchase_order_id, 'PR-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.purchase_receipt_number_seq')::text, 6, '0'), received_at, target_evidence_id, (select auth.uid())) returning id into receipt_id;
  for item in select value from jsonb_array_elements(receipt_lines) loop
    received_quantity := (item->>'received_quantity')::numeric;
    select * into line from public.purchase_order_lines where id = (item->>'purchase_order_line_id')::uuid and purchase_order_id = target_purchase_order_id for update;
    if line.id is null or received_quantity <= 0 then raise exception 'invalid_receipt_line' using errcode = '22023'; end if;
    select coalesce(sum(l.received_quantity), 0) into prior_quantity from public.purchase_receipt_lines l where l.purchase_order_line_id = line.id;
    if prior_quantity + received_quantity > line.quantity then raise exception 'receipt_exceeds_purchase_line' using errcode = '23514'; end if;
    base_quantity := received_quantity * line.conversion_numerator / line.conversion_denominator;
    perform private.require_exact_quantity(base_quantity,false);
    inventory_value := round(received_quantity * line.unit_cost_vnd)::bigint;
    unit_cost_base := inventory_value::numeric / base_quantity;
    insert into public.purchase_receipt_lines(purchase_receipt_id, purchase_order_line_id, material_id, warehouse_id,
      received_quantity, received_base_quantity, unit_cost_vnd, inventory_value_vnd, unit_cost_vnd_per_base)
    values (receipt_id, line.id, line.material_id, order_row.warehouse_id, received_quantity, base_quantity,
      line.unit_cost_vnd, inventory_value, unit_cost_base) returning id into receipt_line_id;
    insert into public.inventory_movements(branch_id, material_id, base_uom_id, location_kind, warehouse_id,
      movement_type, base_quantity_delta, inventory_value_delta_vnd, unit_cost_vnd_per_base,
      source_purchase_receipt_line_id, occurred_at, recorded_by)
    values (order_row.branch_id, line.material_id, line.base_uom_id, 'WAREHOUSE', order_row.warehouse_id,
      'PURCHASE_RECEIPT', base_quantity, inventory_value, unit_cost_base, receipt_line_id, received_at, (select auth.uid()));
    total_value := total_value + inventory_value;
  end loop;
  insert into public.payable_obligations(branch_id, supplier_id, opening_source_id, purchase_receipt_id,
    original_amount_vnd, due_date, recorded_by)
  values (order_row.branch_id, order_row.supplier_id, null, receipt_id, total_value, received_at::date, (select auth.uid()));
  if not exists (
    select 1 from public.purchase_order_lines l
    where l.purchase_order_id = target_purchase_order_id
      and coalesce((select sum(rl.received_quantity) from public.purchase_receipt_lines rl where rl.purchase_order_line_id = l.id), 0) < l.quantity
  ) then update public.purchase_orders set state = 'CLOSED' where id = target_purchase_order_id; end if;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'receive_purchase_order', hash, 'purchase_receipt', receipt_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), order_row.branch_id, 'purchase_order.receive', 'purchase_receipt', receipt_id, operation_id, array['inventory','payable']);
  return receipt_id;
end
$function$

CREATE OR REPLACE FUNCTION public.record_compensation_basis(target_branch_id uuid, target_employee_id uuid, basis_type text, basis_quantity numeric, period_start date, period_end date, description text, adjusts_earning_event_id uuid, target_evidence_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload_hash text; receipt public.command_receipts%rowtype; entity_id uuid;
begin
  if not private.has_permission(target_branch_id,'compensation.manage') then raise exception 'forbidden' using errcode='42501'; end if;
  if basis_type not in ('FIXED_MONTHLY','PER_SHIFT','PER_DAY','BONUS','ADJUSTMENT') or basis_quantity=0 or period_end<period_start or char_length(trim(description)) not between 3 and 500 or ((basis_type='ADJUSTMENT')<>(adjusts_earning_event_id is not null)) then raise exception 'invalid_compensation_basis' using errcode='22023'; end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('branch',target_branch_id,'employee',target_employee_id,'type',basis_type,'quantity',basis_quantity,'from',period_start,'to',period_end,'description',trim(description),'adjusts',adjusts_earning_event_id,'evidence',target_evidence_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id=record_compensation_basis.operation_id;
  if found then if receipt.command_name<>'record_compensation_basis' or receipt.payload_hash<>payload_hash then raise exception 'operation_payload_conflict' using errcode='23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_exact_quantity(abs(basis_quantity),false);
  perform 1 from public.employee_branch_access where employee_id=target_employee_id and branch_id=target_branch_id and active; if not found then raise exception 'invalid_basis_employee' using errcode='23503'; end if;
  if adjusts_earning_event_id is not null then perform 1 from public.earning_events where id=adjusts_earning_event_id and employee_id=target_employee_id and approval_state='APPROVED'; if not found then raise exception 'invalid_adjusted_earning' using errcode='23503'; end if; end if;
  if target_evidence_id is not null then perform 1 from public.evidence_objects where id=target_evidence_id and branch_id=target_branch_id and upload_state='VERIFIED'; if not found then raise exception 'evidence_not_verified' using errcode='23503'; end if; end if;
  insert into public.compensation_manual_bases(branch_id,employee_id,basis_type,basis_quantity,period_start,period_end,description,adjusts_earning_event_id,evidence_object_id,recorded_by) values(target_branch_id,target_employee_id,basis_type,basis_quantity,period_start,period_end,trim(description),adjusts_earning_event_id,target_evidence_id,(select auth.uid())) returning id into entity_id;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'record_compensation_basis',payload_hash,'compensation_basis',entity_id,now());
  return entity_id;
end $function$

CREATE OR REPLACE FUNCTION public.record_gps_ping(target_session_id uuid, target_sequence bigint, target_captured_at timestamp with time zone, target_latitude numeric, target_longitude numeric, target_accuracy_meters numeric, target_speed_mps numeric, target_heading_degrees numeric, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  session public.gps_tracking_sessions%rowtype;
  delivery public.deliveries%rowtype;
  assignment public.delivery_assignments%rowtype;
  position_id uuid;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  retention_days integer;
begin
  select * into session from public.gps_tracking_sessions s where s.id = target_session_id for update;
  if session.id is null or session.status <> 'ACTIVE'
    or session.employee_id is distinct from private.current_employee_id() then
    raise exception 'gps_session_not_active' using errcode = '42501';
  end if;
  select * into assignment from public.delivery_assignments a where a.id = session.assignment_id and a.superseded_at is null;
  select * into delivery from public.deliveries d where d.id = session.delivery_id;
  if assignment.id is null or assignment.assignment_version <> session.assignment_version
    or delivery.execution_state not in ('ASSIGNED','DISPATCHED','ARRIVED','RESULT_SUBMITTED') then
    raise exception 'gps_assignment_revoked' using errcode = '42501';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'session_id', target_session_id,
    'sequence', target_sequence,
    'captured_at', target_captured_at,
    'latitude', target_latitude,
    'longitude', target_longitude,
    'accuracy_meters', target_accuracy_meters,
    'speed_mps', target_speed_mps,
    'heading_degrees', target_heading_degrees
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = record_gps_ping.operation_id;
  if found then
    if receipt.command_name <> 'record_gps_ping' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  if target_sequence <= session.last_sequence
    or (session.last_captured_at is not null and target_captured_at < session.last_captured_at)
    or target_captured_at < session.started_at - interval '5 minutes'
    or target_captured_at > now() + interval '5 minutes' then
    raise exception 'gps_ping_out_of_order' using errcode = 'PT409';
  end if;
  if target_latitude not between -90 and 90 or target_longitude not between -180 and 180 then
    raise exception 'gps_coordinate_invalid' using errcode = '22023';
  end if;
  insert into public.gps_positions(
    session_id, branch_id, delivery_id, assignment_version, sequence, captured_at,
    latitude, longitude, accuracy_meters, speed_mps, heading_degrees, operation_id
  ) values (
    session.id, session.branch_id, session.delivery_id, session.assignment_version, target_sequence, target_captured_at,
    target_latitude, target_longitude, target_accuracy_meters, target_speed_mps, target_heading_degrees, operation_id
  ) returning id into position_id;
  update public.gps_tracking_sessions
    set last_sequence = target_sequence, last_captured_at = target_captured_at, last_position_received_at = now()
    where id = session.id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'record_gps_ping', payload_hash, 'gps_position', position_id, now());
  select coalesce(s.gps_retention_days, 30) into retention_days from public.routing_settings s where s.branch_id = session.branch_id;
  retention_days := coalesce(retention_days, 30);
  delete from public.gps_positions p where p.id in (
    select old.id from public.gps_positions old
    where old.branch_id = session.branch_id and old.received_at < now() - make_interval(days => retention_days)
    order by old.received_at asc limit 500
  );
  return position_id;
end
$function$

CREATE OR REPLACE FUNCTION public.record_payable_adjustment(target_obligation_id uuid, amount_delta_vnd bigint, reason text, target_evidence_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  obligation public.payable_obligations%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  adjustment_id uuid;
begin
  select * into obligation from public.payable_obligations where id = target_obligation_id;
  if obligation.id is null or not private.has_permission(obligation.branch_id, 'finance.ap.adjust') then raise exception 'forbidden_or_obligation_not_found' using errcode = '42501'; end if;
  if amount_delta_vnd = 0 or char_length(trim(reason)) not between 3 and 500 then raise exception 'invalid_adjustment' using errcode = '22023'; end if;
  if target_evidence_id is not null then perform private.assert_verified_evidence(target_evidence_id, obligation.branch_id); end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('obligation_id', target_obligation_id, 'delta', amount_delta_vnd, 'reason', trim(reason), 'evidence_id', target_evidence_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = record_payable_adjustment.operation_id;
  if found then
    if receipt.command_name <> 'record_payable_adjustment' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  perform 1 from public.payable_obligations where id = target_obligation_id for update;
  if private.current_payable_outstanding(target_obligation_id) + amount_delta_vnd < 0 then raise exception 'adjustment_exceeds_outstanding' using errcode = '23514'; end if;
  insert into public.payable_adjustments(obligation_id, amount_delta_vnd, reason, evidence_object_id, recorded_by)
  values (target_obligation_id, amount_delta_vnd, trim(reason), target_evidence_id, (select auth.uid()))
  returning id into adjustment_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'record_payable_adjustment', payload_hash, 'payable_adjustment', adjustment_id, now());
  return adjustment_id;
end
