CREATE OR REPLACE FUNCTION public.record_stock_count_line(target_stock_count_id uuid, target_material_id uuid, counted_base_quantity numeric, adjustment_unit_cost_vnd numeric, reason text, target_evidence_id uuid, expected_count_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare count_row public.stock_counts%rowtype; expected numeric; hash text; receipt public.command_receipts%rowtype; line_id uuid;
begin
  select * into count_row from public.stock_counts where id = target_stock_count_id for update;
  if count_row.id is null or not private.has_permission(count_row.branch_id, 'inventory.count') then raise exception 'forbidden' using errcode = '42501'; end if;
  if counted_base_quantity is null or counted_base_quantity < 0 or counted_base_quantity >= 'Infinity'::numeric
  then raise exception 'invalid_stock_count_quantity' using errcode = '22023'; end if;
  if adjustment_unit_cost_vnd is not null and (adjustment_unit_cost_vnd < 0 or adjustment_unit_cost_vnd >= 'Infinity'::numeric)
  then raise exception 'invalid_stock_count_cost' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('count_id', target_stock_count_id, 'material_id', target_material_id, 'counted', counted_base_quantity, 'cost', adjustment_unit_cost_vnd, 'reason', nullif(trim(reason), ''), 'evidence_id', target_evidence_id, 'version', expected_count_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = record_stock_count_line.operation_id;
  if found then if receipt.command_name <> 'record_stock_count_line' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_exact_quantity(counted_base_quantity,true);

  if expected_count_version is null or expected_count_version <= 0 or count_row.state <> 'OPEN' or count_row.version  IS DISTINCT FROM expected_count_version or counted_base_quantity < 0 then raise exception 'stock_count_version_conflict' using errcode = 'PT409'; end if;
  if not exists (select 1 from public.materials where id = target_material_id and active) then raise exception 'material_not_found' using errcode = '23503'; end if;
  perform private.assert_verified_evidence(target_evidence_id, count_row.branch_id);
  perform 1 from public.warehouses where id=count_row.warehouse_id for update;
  if exists(select 1 from public.inventory_movements m
    where m.branch_id=count_row.branch_id and m.warehouse_id=count_row.warehouse_id
      and m.material_id=target_material_id
      and (m.occurred_at>count_row.cutoff_at or m.created_at>count_row.cutoff_at))
  then raise exception 'stock_count_cutoff_stale' using errcode='PT409'; end if;
  select coalesce(sum(base_quantity_delta), 0) into expected from public.inventory_movements
    where warehouse_id = count_row.warehouse_id and material_id = target_material_id and occurred_at <= count_row.cutoff_at;
  if counted_base_quantity <> expected and char_length(trim(reason)) < 3 then raise exception 'variance_reason_required' using errcode = '22023'; end if;
  insert into public.stock_count_lines(stock_count_id, material_id, expected_base_quantity, counted_base_quantity,
    adjustment_unit_cost_vnd, reason, evidence_object_id, recorded_by)
  values (target_stock_count_id, target_material_id, expected, counted_base_quantity,
    adjustment_unit_cost_vnd, nullif(trim(reason), ''), target_evidence_id, (select auth.uid()))
  on conflict (stock_count_id, material_id) do update set expected_base_quantity = excluded.expected_base_quantity,
    counted_base_quantity = excluded.counted_base_quantity, adjustment_unit_cost_vnd = excluded.adjustment_unit_cost_vnd,
    reason = excluded.reason, evidence_object_id = excluded.evidence_object_id, recorded_by = excluded.recorded_by,
    recorded_at = now() returning id into line_id;
  update public.stock_count_lines set
    basis_fingerprint=private.stock_count_basis(count_row.branch_id,count_row.warehouse_id,target_material_id),
    basis_count_version=count_row.version
    where id=line_id;
  insert into public.stock_count_observations(stock_count_line_id,count_version,expected_base_quantity,
    counted_base_quantity,basis_fingerprint,reason,evidence_object_id,recorded_by,operation_id)
  select l.id,count_row.version,l.expected_base_quantity,l.counted_base_quantity,l.basis_fingerprint,
    l.reason,l.evidence_object_id,(select auth.uid()),record_stock_count_line.operation_id
    from public.stock_count_lines l where l.id=line_id;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values((select auth.uid()),count_row.branch_id,'stock_count.line.recorded','stock_count_line',line_id,
    record_stock_count_line.operation_id,array['expected_base_quantity','counted_base_quantity','basis_count_version'],
    nullif(trim(record_stock_count_line.reason),''));
  update public.stock_counts set version = version + 1 where id = target_stock_count_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'record_stock_count_line', hash, 'stock_count_line', line_id, now());
  return line_id;
end
$function$

CREATE OR REPLACE FUNCTION public.record_supplier_return_event(target_case_id uuid, target_event_kind text, actual_base_quantity numeric, target_supplier_reference text, event_reason text, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.supplier_return_cases%rowtype;rc public.return_cases%rowtype;r public.command_receipts%rowtype;h text;eid uuid;permission text;returned numeric;accepted numeric;prior_qty numeric;portion bigint;on_hand numeric;reserved numeric;stock_value bigint;inventory_portion bigint;accepted_inventory bigint:=0;lot record;lot_before numeric;lot_after numeric;prior_lot_qty numeric:=0;source_line public.delivery_lines%rowtype;vl public.delivery_verification_lines%rowtype;hl public.delivery_handoff_lines%rowtype;
begin
 select * into c from public.supplier_return_cases where id=target_case_id;
 permission:=case target_event_kind when 'PHYSICAL_RETURN' then 'inventory.reserve' when 'SUPPLIER_ACCEPTANCE' then 'purchasing.confirm' when 'CLOSE_DISPATCH' then 'purchasing.cancel' end;
 if c.id is null or permission is null or not private.has_permission(c.branch_id,permission) then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'record_supplier_return_event');perform pg_advisory_xact_lock(hashtextextended('supplier_return:'||operation_id::text,0));
 perform private.require_exact_quantity(actual_base_quantity,target_event_kind='CLOSE_DISPATCH');
 if operation_id is null or event_reason is null or char_length(trim(event_reason)) not between 3 and 500 then raise exception 'invalid_supplier_return_event' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_case_id,target_event_kind,actual_base_quantity,nullif(trim(target_supplier_reference),''),trim(event_reason),expected_version));
 select * into r from public.command_receipts where command_receipts.operation_id=record_supplier_return_event.operation_id;
 if found then if r.command_name<>'record_supplier_return_event' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 -- Serialize all cases of the same original source before their case/version checks.
 if c.source_receipt_line_id is not null then perform 1 from public.purchase_receipt_lines where id=c.source_receipt_line_id for update;
 else perform 1 from public.supplier_fulfillment_lines where id=c.source_fulfillment_line_id for update;end if;
 select * into c from public.supplier_return_cases where id=target_case_id for update;
 if c.version is distinct from expected_version then raise exception 'supplier_return_version_conflict' using errcode='PT409';end if;
 select coalesce(sum(e.base_quantity)filter(where e.event_kind='PHYSICAL_RETURN'),0),coalesce(sum(e.base_quantity)filter(where e.event_kind='SUPPLIER_ACCEPTANCE'),0) into returned,accepted from public.supplier_return_events e where e.case_id=c.id;
 if target_event_kind='CLOSE_DISPATCH' then
  if c.dispatch_closed or actual_base_quantity<>0 or nullif(trim(target_supplier_reference),'') is not null then raise exception 'invalid_supplier_return_close' using errcode='23514';end if;portion:=0;
 else
  if target_event_kind='PHYSICAL_RETURN' and(c.dispatch_closed or returned+actual_base_quantity>c.requested_base_quantity) then raise exception 'supplier_return_exceeds_requested' using errcode='23514';end if;
  if target_event_kind='SUPPLIER_ACCEPTANCE' and(accepted+actual_base_quantity>returned or target_supplier_reference is null or char_length(trim(target_supplier_reference)) not between 3 and 100) then raise exception 'supplier_acceptance_exceeds_physical_return_or_reference_missing' using errcode='23514';end if;
  if target_event_kind='PHYSICAL_RETURN' and nullif(trim(target_supplier_reference),'') is not null then raise exception 'physical_return_has_no_supplier_acceptance_reference' using errcode='23514';end if;
  select coalesce(sum(e.base_quantity),0) into prior_qty from public.supplier_return_events e join public.supplier_return_cases other on other.id=e.case_id
   where e.event_kind=target_event_kind and((c.source_receipt_line_id is not null and other.source_receipt_line_id=c.source_receipt_line_id) or(c.source_fulfillment_line_id is not null and other.source_fulfillment_line_id=c.source_fulfillment_line_id));
  if prior_qty+actual_base_quantity>c.source_base_quantity then raise exception 'supplier_return_exceeds_source_quantity' using errcode='23514';end if;
  portion:=round((prior_qty+actual_base_quantity)*c.source_value_vnd/c.source_base_quantity)::bigint-round(prior_qty*c.source_value_vnd/c.source_base_quantity)::bigint;
  if portion<=0 then raise exception 'supplier_return_portion_has_no_value' using errcode='23514';end if;
 end if;
 if target_event_kind='PHYSICAL_RETURN' then
  if c.warehouse_id is not null then
   if c.source_fulfillment_line_id is not null then
    select * into rc from public.return_cases where id=c.source_return_case_id for update;
    if rc.state<>'RETURNED' or rc.resolution_warehouse_id is distinct from c.warehouse_id then raise exception 'recorded_return_warehouse_custody_changed' using errcode='PT409';end if;
   end if;
   perform 1 from public.warehouses where id=c.warehouse_id and branch_id=c.branch_id and active for update;
   if not found then raise exception 'supplier_return_warehouse_invalid' using errcode='23514';end if;
   select coalesce(sum(m.base_quantity_delta),0),coalesce(sum(m.inventory_value_delta_vnd),0) into on_hand,stock_value from public.inventory_movements m where m.material_id=c.material_id and m.warehouse_id=c.warehouse_id and m.location_kind='WAREHOUSE';
   select coalesce(sum(i.reserved_base_quantity),0) into reserved from public.inventory_reservations i where i.material_id=c.material_id and i.warehouse_id=c.warehouse_id and i.state='ACTIVE';
   if on_hand-reserved<actual_base_quantity or on_hand<=0 or stock_value<=0 then raise exception 'insufficient_available_inventory_for_supplier_return' using errcode='23514';end if;
   inventory_portion:=case when actual_base_quantity=on_hand then stock_value else round(actual_base_quantity*stock_value/on_hand)::bigint end;
   if inventory_portion<=0 then raise exception 'supplier_return_inventory_portion_has_no_value' using errcode='23514';end if;
  else
   select * into rc from public.return_cases where id=c.source_return_case_id for update;
   select * into source_line from public.delivery_lines where id=rc.delivery_line_id;
   perform 1 from public.deliveries where id=source_line.delivery_id for update;
   select * into vl from public.delivery_verification_lines where id=rc.delivery_verification_line_id;
   select h.* into hl from public.delivery_handoff_lines h where h.delivery_line_id=source_line.id;
   if rc.state<>'OPEN' or actual_base_quantity<>rc.base_quantity or returned<>0 or source_line.source_mode<>'SUPPLIER_DIRECT'
   then raise exception 'direct_supplier_return_custody_changed' using errcode='PT409';end if;
   if rc.case_kind='TRANSIT_REMAINDER' and rc.base_quantity>hl.moved_base_quantity-vl.accepted_base_quantity-coalesce((select sum(x.base_quantity) from public.return_cases x where x.delivery_line_id=source_line.id and x.case_kind in('TRANSIT_REMAINDER','TRANSIT_LOSS') and x.state in('RETURNED','LOSS_APPROVED')),0) then raise exception 'return_exceeds_transit_position' using errcode='23514';end if;
  end if;
 end if;
 if target_event_kind='PHYSICAL_RETURN' and c.warehouse_id is null then inventory_portion:=private.return_cost_portion(rc.id);end if;
 if target_event_kind='SUPPLIER_ACCEPTANCE' and c.warehouse_id is not null then
  for lot in select e.* from public.supplier_return_events e where e.case_id=c.id and e.event_kind='PHYSICAL_RETURN' order by e.source_case_version nulls first,e.recorded_at,e.id loop
   lot_before:=least(lot.base_quantity,greatest(0,accepted-prior_lot_qty));
   lot_after:=least(lot.base_quantity,greatest(0,accepted+actual_base_quantity-prior_lot_qty));
   accepted_inventory:=accepted_inventory+round(lot_after*coalesce(lot.inventory_value_vnd,lot.source_value_vnd)/lot.base_quantity)::bigint-round(lot_before*coalesce(lot.inventory_value_vnd,lot.source_value_vnd)/lot.base_quantity)::bigint;
   prior_lot_qty:=prior_lot_qty+lot.base_quantity;
  end loop;
  inventory_portion:=accepted_inventory;
 end if;
 insert into public.supplier_return_events(case_id,branch_id,supplier_id,event_kind,base_quantity,source_value_vnd,supplier_reference,reason,recorded_by,inventory_value_vnd,source_case_version)
 values(c.id,c.branch_id,c.supplier_id,target_event_kind,actual_base_quantity,portion,case when target_event_kind='SUPPLIER_ACCEPTANCE' then trim(target_supplier_reference) else null end,trim(event_reason),auth.uid(),inventory_portion,c.version) returning id into eid;
 if target_event_kind='PHYSICAL_RETURN' then
  if c.warehouse_id is not null then
   insert into public.inventory_movements(branch_id,material_id,base_uom_id,location_kind,warehouse_id,movement_type,base_quantity_delta,inventory_value_delta_vnd,unit_cost_vnd_per_base,source_supplier_return_event_id,occurred_at,recorded_by)
   values(c.branch_id,c.material_id,c.base_uom_id,'WAREHOUSE',c.warehouse_id,'SUPPLIER_RETURN',-actual_base_quantity,-inventory_portion,round(inventory_portion/actual_base_quantity,6),eid,now(),auth.uid());
  else
   update public.return_cases set state='RETURNED',resolution_warehouse_id=null,resolution_destination='SUPPLIER',resolution_reason=trim(event_reason),resolved_by=auth.uid(),resolved_at=now(),version=version+1 where id=rc.id;
   insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason) values(auth.uid(),c.branch_id,'delivery.returned_to_supplier','return_case',rc.id,operation_id,array['state','resolution_destination','physical_custody'],trim(event_reason));
   insert into public.direct_cost_entries(branch_id,sales_order_id,return_case_id,amount_delta_vnd,cost_kind,recorded_by)
   select c.branch_id,d.sales_order_id,rc.id,-inventory_portion,'RETURN_REVERSAL',auth.uid() from public.deliveries d where d.id=source_line.delivery_id;
  end if;
 end if;
 update public.supplier_return_cases set version=version+1,dispatch_closed=dispatch_closed or target_event_kind='CLOSE_DISPATCH' where id=c.id;
 insert into public.command_receipts values(operation_id,auth.uid(),'record_supplier_return_event',h,'supplier_return_event',eid,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
 values(auth.uid(),c.branch_id,'supplier_return.'||lower(target_event_kind),'supplier_return_case',c.id,operation_id,array['source_event','event_kind','base_quantity','supplier_reference','physical_destination'],trim(event_reason));
 return eid;
end $function$

CREATE OR REPLACE FUNCTION public.record_warehouse_transfer_event(target_transfer_id uuid, event_kind text, source_dispatch_id uuid, source_issue_id uuid, actual_base_quantity numeric, event_reason text, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.warehouse_transfers%rowtype;lot public.warehouse_transfer_events%rowtype;issue public.warehouse_transfer_events%rowtype;r public.command_receipts%rowtype;
 h text; eid uuid;permission text; shipped numeric; settled numeric;settled_value bigint;claimed numeric;issue_settled numeric;qty numeric;reserved numeric;val bigint;portion bigint;unit_cost numeric;
begin
 permission:=case event_kind when 'DISPATCH' then 'inventory.reserve' when 'RECEIVE' then 'inventory.receive' when 'REPORT_SHORTAGE' then 'inventory.receive' when 'CLOSE_DISPATCH' then 'inventory.reserve' when 'APPROVE_LOSS' then 'inventory.adjust' end;
 select * into t from public.warehouse_transfers where id=target_transfer_id;
 if permission is null or t.id is null or not private.has_permission(t.branch_id,permission) then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'record_warehouse_transfer_event');perform pg_advisory_xact_lock(hashtextextended('warehouse_transfer:'||operation_id::text,0));
 perform private.require_exact_quantity(actual_base_quantity,event_kind='CLOSE_DISPATCH');
 if operation_id is null or event_reason is null or char_length(trim(event_reason)) not between 3 and 500 then raise exception 'invalid_transfer_event' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_transfer_id,event_kind,source_dispatch_id,source_issue_id,actual_base_quantity,trim(event_reason),expected_version));
 select * into r from public.command_receipts where command_receipts.operation_id=record_warehouse_transfer_event.operation_id;
 if found then if r.command_name<>'record_warehouse_transfer_event' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 select * into t from public.warehouse_transfers where id=target_transfer_id for update;
 if t.version is distinct from expected_version then raise exception 'transfer_version_conflict' using errcode='40001';end if;
 perform 1 from public.warehouses w where w.id in(t.from_warehouse_id,t.to_warehouse_id) and w.active order by w.id for update;
 if (select count(*) from public.warehouses w where w.id in(t.from_warehouse_id,t.to_warehouse_id) and w.active)<>2 then raise exception 'transfer_warehouse_inactive' using errcode='23514';end if;
 select coalesce(sum(e.base_quantity),0) into shipped from public.warehouse_transfer_events e where e.transfer_id=t.id and e.event_kind='DISPATCH';
 if event_kind='CLOSE_DISPATCH' then
  if t.dispatch_closed or source_dispatch_id is not null or source_issue_id is not null or actual_base_quantity<>0 then raise exception 'invalid_transfer_close' using errcode='23514';end if;portion:=0;
 elsif event_kind='DISPATCH' then
  if t.dispatch_closed or source_dispatch_id is not null or source_issue_id is not null or shipped+actual_base_quantity>t.planned_base_quantity then raise exception 'transfer_dispatch_exceeds_plan' using errcode='23514';end if;
  select coalesce(sum(m.base_quantity_delta),0),coalesce(sum(m.inventory_value_delta_vnd),0) into qty,val from public.inventory_movements m where m.warehouse_id=t.from_warehouse_id and m.material_id=t.material_id and m.location_kind='WAREHOUSE';
  select coalesce(sum(i.reserved_base_quantity),0) into reserved from public.inventory_reservations i where i.warehouse_id=t.from_warehouse_id and i.material_id=t.material_id and i.state='ACTIVE';
  if qty-reserved<actual_base_quantity or qty<=0 or val<=0 then raise exception 'insufficient_available_inventory' using errcode='23514';end if;
  portion:=round(actual_base_quantity*val/qty)::bigint;
 else
  select * into lot from public.warehouse_transfer_events e where e.id=record_warehouse_transfer_event.source_dispatch_id and e.transfer_id=t.id and e.event_kind='DISPATCH';
  if lot.id is null then raise exception 'transfer_dispatch_source_invalid' using errcode='23514';end if;
  select coalesce(sum(e.base_quantity),0),coalesce(sum(e.value_vnd),0) into settled,settled_value from public.warehouse_transfer_events e where e.source_dispatch_id=lot.id and e.event_kind in('RECEIVE','APPROVE_LOSS');
  select coalesce(sum(i.base_quantity-coalesce((select sum(e.base_quantity) from public.warehouse_transfer_events e where e.source_issue_id=i.id and e.event_kind in('RECEIVE','APPROVE_LOSS')),0)),0) into claimed from public.warehouse_transfer_events i where i.source_dispatch_id=lot.id and i.event_kind='REPORT_SHORTAGE';
  if actual_base_quantity>lot.base_quantity-settled then raise exception 'transfer_event_exceeds_transit' using errcode='23514';end if;
  if event_kind='REPORT_SHORTAGE' then
   if source_issue_id is not null or actual_base_quantity>lot.base_quantity-settled-claimed then raise exception 'transfer_issue_exceeds_unclaimed_transit' using errcode='23514';end if;portion:=0;
  else
   if source_issue_id is not null then
    select * into issue from public.warehouse_transfer_events e where e.id=record_warehouse_transfer_event.source_issue_id and e.source_dispatch_id=lot.id and e.event_kind='REPORT_SHORTAGE';
    select coalesce(sum(e.base_quantity),0) into issue_settled from public.warehouse_transfer_events e where e.source_issue_id=issue.id and e.event_kind in('RECEIVE','APPROVE_LOSS');
    if issue.id is null or actual_base_quantity>issue.base_quantity-issue_settled then raise exception 'transfer_issue_resolution_exceeds_source' using errcode='23514';end if;
   elsif event_kind='APPROVE_LOSS' or actual_base_quantity>lot.base_quantity-settled-claimed then raise exception 'transfer_open_issue_requires_source' using errcode='23514';end if;
   portion:=round((settled+actual_base_quantity)*lot.value_vnd/lot.base_quantity)::bigint-settled_value;
  end if;
 end if;
 if event_kind in('DISPATCH','RECEIVE','APPROVE_LOSS') and portion<=0 then raise exception 'transfer_portion_has_no_value' using errcode='23514';end if;
 insert into public.warehouse_transfer_events(transfer_id,event_kind,source_dispatch_id,source_issue_id,base_quantity,value_vnd,reason,recorded_by)
 values(t.id,event_kind,source_dispatch_id,source_issue_id,actual_base_quantity,portion,trim(event_reason),auth.uid()) returning id into eid;
 if event_kind in('DISPATCH','RECEIVE','APPROVE_LOSS') then
  unit_cost:=round(portion/actual_base_quantity,6);
  if event_kind='DISPATCH' then
   insert into public.inventory_movements(branch_id,material_id,base_uom_id,location_kind,warehouse_id,movement_type,base_quantity_delta,inventory_value_delta_vnd,unit_cost_vnd_per_base,warehouse_transfer_id,source_warehouse_transfer_event_id,occurred_at,recorded_by)
   values(t.branch_id,t.material_id,t.base_uom_id,'WAREHOUSE',t.from_warehouse_id,'WAREHOUSE_TRANSFER_DISPATCH',-actual_base_quantity,-portion,unit_cost,t.id,eid,now(),auth.uid());
  end if;
  insert into public.inventory_movements(branch_id,material_id,base_uom_id,location_kind,movement_type,base_quantity_delta,inventory_value_delta_vnd,unit_cost_vnd_per_base,warehouse_transfer_id,source_warehouse_transfer_event_id,occurred_at,recorded_by)
  values(t.branch_id,t.material_id,t.base_uom_id,'IN_TRANSIT',case event_kind when 'DISPATCH' then 'WAREHOUSE_TRANSFER_DISPATCH' when 'RECEIVE' then 'WAREHOUSE_TRANSFER_RECEIPT' else 'WAREHOUSE_TRANSFER_LOSS' end,case when event_kind='DISPATCH' then actual_base_quantity else -actual_base_quantity end,case when event_kind='DISPATCH' then portion else -portion end,unit_cost,t.id,eid,now(),auth.uid());
  if event_kind='RECEIVE' then
   insert into public.inventory_movements(branch_id,material_id,base_uom_id,location_kind,warehouse_id,movement_type,base_quantity_delta,inventory_value_delta_vnd,unit_cost_vnd_per_base,warehouse_transfer_id,source_warehouse_transfer_event_id,occurred_at,recorded_by)
   values(t.branch_id,t.material_id,t.base_uom_id,'WAREHOUSE',t.to_warehouse_id,'WAREHOUSE_TRANSFER_RECEIPT',actual_base_quantity,portion,unit_cost,t.id,eid,now(),auth.uid());
  end if;
 end if;
 update public.warehouse_transfers set version=version+1,dispatch_closed=dispatch_closed or event_kind='CLOSE_DISPATCH' where id=t.id;
 insert into public.command_receipts values(operation_id,auth.uid(),'record_warehouse_transfer_event',h,'warehouse_transfer_event',eid,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
 values(auth.uid(),t.branch_id,'warehouse_transfer.'||lower(event_kind),'warehouse_transfer',t.id,operation_id,array['event_id','event_kind','base_quantity','source_dispatch_id','source_issue_id'],trim(event_reason));
 return eid;
end $function$

CREATE OR REPLACE FUNCTION public.refund_customer_credit(target_credit_id uuid, target_account_id uuid, refund_amount_vnd bigint, refunded_at timestamp with time zone, refund_method text, refund_reference text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.customer_credits%rowtype; f public.customer_credit_funds%rowtype; receipt public.command_receipts%rowtype;
 hash text; payment_id uuid; left_to_refund bigint; part bigint;
begin
 select * into c from public.customer_credits where id=target_credit_id;
 if c.id is null or not private.has_permission(c.branch_id,'finance.payment.post') then raise exception 'forbidden_or_customer_credit_not_found' using errcode='42501';end if;
 hash:=private.command_payload_hash(jsonb_build_object('credit_id',target_credit_id,'account_id',target_account_id,'amount',refund_amount_vnd,
  'at',refunded_at,'method',refund_method,'reference',nullif(trim(refund_reference),'')));
 perform private.lock_saved_command_intent(operation_id,'refund_customer_credit');
 select * into c from public.customer_credits where id=target_credit_id for update;
 select * into receipt from public.command_receipts where command_receipts.operation_id=refund_customer_credit.operation_id;
 if found then if receipt.command_name<>'refund_customer_credit' or receipt.payload_hash<>hash then raise exception 'operation_payload_conflict' using errcode='23505';end if;return receipt.result_entity_id;end if;
 if refund_amount_vnd is null or refund_amount_vnd<=0 or refunded_at is null or not isfinite(refunded_at)
  or refund_method is null or refund_method not in('CASH','BANK_TRANSFER','CARD','OTHER') or length(coalesce(refund_reference,''))>160
  or not exists(select 1 from public.finance_accounts a where a.id=target_account_id and a.branch_id=c.branch_id and a.active)
 then raise exception 'invalid_customer_credit_refund' using errcode='22023';end if;
 if refund_amount_vnd>private.customer_credit_remaining(c.id) then raise exception 'customer_credit_settlement_exceeds_remaining' using errcode='23514';end if;
 perform 1 from public.payments p where p.id in(select source_payment_id from public.customer_credit_funds where credit_id=c.id) order by p.id for update;
 insert into public.payments(branch_id,payment_number,direction,customer_id,account_id,amount_vnd,method,external_reference,effective_at,posted_by,customer_credit_refund_id)
  values(c.branch_id,'REF-'||to_char((now() at time zone 'Asia/Ho_Chi_Minh')::date,'YYYYMM')||'-'||lpad(nextval('public.finance_payment_number_seq')::text,6,'0'),
   'DISBURSEMENT',c.customer_id,target_account_id,refund_amount_vnd,refund_method,nullif(trim(refund_reference),''),refunded_at,(select auth.uid()),c.id) returning id into payment_id;
 left_to_refund:=refund_amount_vnd;
 for f in select * from public.customer_credit_funds where credit_id=c.id order by source_payment_id,id loop
  exit when left_to_refund=0;part:=least(left_to_refund,private.customer_credit_fund_remaining(f.id));if part<=0 then continue;end if;
  insert into public.customer_credit_settlements(credit_fund_id,settlement_kind,amount_delta_vnd,payment_id,source_operation_id,recorded_by)
   values(f.id,'REFUND',part,payment_id,operation_id,(select auth.uid()));left_to_refund:=left_to_refund-part;
 end loop;
 if left_to_refund<>0 then raise exception 'customer_credit_funding_incomplete' using errcode='23514';end if;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values((select auth.uid()),c.branch_id,'customer.credit_refunded','payment',payment_id,operation_id,array['source_credit','settlement','cash'],coalesce(nullif(trim(refund_reference),''),'Hoàn tiền khoản có theo nguồn đã duyệt'));
 insert into public.command_receipts values(operation_id,(select auth.uid()),'refund_customer_credit',hash,'payment',payment_id,now());
 return payment_id;
end $function$

CREATE OR REPLACE FUNCTION public.refund_supplier_credit(target_credit_id uuid, target_account_id uuid, refund_amount_vnd bigint, refunded_at timestamp with time zone, refund_method text, refund_reference text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.supplier_return_credits%rowtype;f public.supplier_credit_funds%rowtype;r public.command_receipts%rowtype;h text;pid uuid;remaining bigint;part bigint;
begin
 select * into c from public.supplier_return_credits where id=target_credit_id;
 if c.id is null or not private.has_permission(c.branch_id,'finance.payment.post') then raise exception 'forbidden_or_supplier_credit_not_found' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'refund_supplier_credit');perform pg_advisory_xact_lock(hashtextextended('supplier_credit:'||operation_id::text,0));
 h:=private.command_payload_hash(jsonb_build_array(target_credit_id,target_account_id,refund_amount_vnd,refunded_at,refund_method,nullif(trim(refund_reference),'')));
 select * into c from public.supplier_return_credits where id=target_credit_id for update;
 select * into r from public.command_receipts where command_receipts.operation_id=refund_supplier_credit.operation_id;
 if found then if r.command_name<>'refund_supplier_credit' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 if operation_id is null or refund_amount_vnd is null or refund_amount_vnd<=0 or refunded_at is null or not isfinite(refunded_at) or refund_method is null or refund_method not in('CASH','BANK_TRANSFER','CARD','OTHER') or length(coalesce(refund_reference,''))>160 then raise exception 'invalid_supplier_credit_refund' using errcode='22023';end if;
 if refund_amount_vnd>private.supplier_credit_remaining(c.id) then raise exception 'supplier_credit_settlement_exceeds_remaining' using errcode='23514';end if;
 perform 1 from public.payments p where p.id in(select source_payment_id from public.supplier_credit_funds where credit_id=c.id) order by p.id for update;
 perform 1 from public.finance_accounts a where a.id=target_account_id and a.branch_id=c.branch_id and a.active for update;if not found then raise exception 'invalid_finance_account' using errcode='23503';end if;
 insert into public.payments(branch_id,payment_number,direction,supplier_id,account_id,amount_vnd,method,external_reference,effective_at,posted_by,supplier_credit_refund_id)
 values(c.branch_id,'VREF-'||lpad(nextval('public.finance_payment_number_seq')::text,8,'0'),'RECEIPT',c.supplier_id,target_account_id,refund_amount_vnd,refund_method,nullif(trim(refund_reference),''),refunded_at,auth.uid(),c.id) returning id into pid;
 remaining:=refund_amount_vnd;
 for f in select * from public.supplier_credit_funds where credit_id=c.id order by source_payment_id,id loop
  exit when remaining=0;part:=least(remaining,private.supplier_credit_fund_remaining(f.id));if part<=0 then continue;end if;
  insert into public.supplier_credit_settlements(credit_fund_id,settlement_kind,amount_vnd,payment_id,source_operation_id,recorded_by) values(f.id,'REFUND',part,pid,operation_id,auth.uid());remaining:=remaining-part;
 end loop;
 if remaining<>0 then raise exception 'supplier_credit_funding_incomplete' using errcode='23514';end if;
 insert into public.command_receipts values(operation_id,auth.uid(),'refund_supplier_credit',h,'payment',pid,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values(auth.uid(),c.branch_id,'supplier_return.refund_received','payment',pid,operation_id,array['source_credit','settlement','cash_receipt']);return pid;
end $function$

CREATE OR REPLACE FUNCTION public.register_invited_employee(invited_auth_user_id uuid, employee_code text, employee_name text, target_branch_id uuid, target_role_id uuid, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  employee_id uuid;
  access_id uuid;
begin
  if (select auth.uid()) is null or not private.has_permission(target_branch_id, 'roles.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if change_reason is null or char_length(change_reason) < 3 then
    raise exception 'change_reason_required' using errcode = '22023';
  end if;

  if not exists (select 1 from auth.users where id = invited_auth_user_id)
    or not exists (select 1 from public.branches where id = target_branch_id and active)
    or not exists (select 1 from public.roles where id = target_role_id and active) then
    raise exception 'inactive_or_missing_invite_target' using errcode = '23503';
  end if;

  insert into public.employees(auth_user_id, code, display_name)
  values (invited_auth_user_id, employee_code, employee_name)
  returning id into employee_id;

  insert into public.employee_branch_access(employee_id, branch_id, role_id)
  values (employee_id, target_branch_id, target_role_id)
  returning id into access_id;

  insert into public.audit_events(
    actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason
  ) values (
    (select auth.uid()), target_branch_id, 'employee.invite.register', 'employee', employee_id,
    operation_id, array['auth_user_id', 'code', 'display_name', 'role_id'], change_reason
  );

  return employee_id;
end
$function$

CREATE OR REPLACE FUNCTION public.register_purchase_invoice_source(target_payable_obligation_id uuid, target_document_number text, target_document_date date, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  obligation public.payable_obligations%rowtype;
  supplier_name text;
  source_type text;
  source_id uuid;
  evidence_id uuid;
  registry_id uuid;
  normalized_number text;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  perform private.lock_saved_command_intent(operation_id,'register_purchase_invoice_source');
  perform pg_advisory_xact_lock(hashtextextended('document:'||operation_id::text,0));
  select * into obligation from public.payable_obligations o where o.id = target_payable_obligation_id for update;
  if obligation.id is null or not private.has_permission(obligation.branch_id, 'finance.ap.adjust') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if obligation.supplier_id is null or (obligation.purchase_receipt_id is null and obligation.supplier_fulfillment_id is null) then
    raise exception 'purchase_invoice_source_invalid' using errcode = '23514';
  end if;
  normalized_number := nullif(trim(target_document_number), '');
  if normalized_number is not null and char_length(normalized_number) not between 2 and 100 then
    raise exception 'purchase_invoice_number_invalid' using errcode = '22023';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'obligation_id', target_payable_obligation_id, 'document_number', normalized_number, 'document_date', target_document_date
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = register_purchase_invoice_source.operation_id;
  if found then
    if receipt.command_name <> 'register_purchase_invoice_source' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  select s.name into supplier_name from public.suppliers s where s.id = obligation.supplier_id and s.branch_id = obligation.branch_id;
  if supplier_name is null then raise exception 'purchase_invoice_supplier_invalid' using errcode = '23503'; end if;
  if obligation.purchase_receipt_id is not null then
    source_type := 'PURCHASE_RECEIPT';
    source_id := obligation.purchase_receipt_id;
    select r.evidence_object_id into evidence_id from public.purchase_receipts r
      where r.id = source_id and r.branch_id = obligation.branch_id;
  else
    source_type := 'SUPPLIER_FULFILLMENT';
    source_id := obligation.supplier_fulfillment_id;
    select f.evidence_object_id into evidence_id from public.supplier_fulfillments f
      where f.id = source_id and f.branch_id = obligation.branch_id;
  end if;
  if evidence_id is not null and not exists (
    select 1 from public.evidence_objects e
    where e.id = evidence_id and e.branch_id = obligation.branch_id and e.upload_state = 'VERIFIED'
  ) then evidence_id := null; end if;
  insert into public.purchase_invoice_registry(
    branch_id, payable_obligation_id, supplier_id, supplier_name_snapshot,
    source_type, source_id, source_amount_vnd, supplier_document_number,
    supplier_document_date, evidence_object_id, document_state, created_by, operation_id
  ) values (
    obligation.branch_id, obligation.id, obligation.supplier_id, supplier_name,
    source_type, source_id, obligation.original_amount_vnd, normalized_number,
    target_document_date, evidence_id,
    case when evidence_id is null then 'PENDING_DOCUMENT' else 'SOURCE_EVIDENCE_ATTACHED' end,
    (select auth.uid()), operation_id
  ) returning id into registry_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'register_purchase_invoice_source', payload_hash, 'purchase_invoice_registry', registry_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), obligation.branch_id, 'purchase_invoice_source.registered', 'purchase_invoice_registry', registry_id, operation_id,
    array['source','supplier_document','evidence_state']);
  return registry_id;
end
$function$

CREATE OR REPLACE FUNCTION public.register_supplier_document(target_branch_id uuid, target_supplier_id uuid, target_document_kind text, target_document_number text, target_document_date date, declared_total_vnd bigint, document_lines jsonb, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.command_receipts%rowtype;h text;did uuid;item jsonb;src record;kind text;sid uuid;qty numeric;price numeric;value_amount bigint;computed bigint;result text;line_index integer:=0;sum_declared bigint:=0;sum_source bigint:=0;has_variance boolean:=false;
begin
 if not private.has_permission(target_branch_id,'finance.ap.adjust') then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'register_supplier_document');perform pg_advisory_xact_lock(hashtextextended('supplier_document:'||operation_id::text,0));
 if operation_id is null or target_document_kind is null or target_document_kind not in('INVOICE','CREDIT_NOTE') or target_document_number is null or char_length(trim(target_document_number)) not between 2 and 100 or target_document_date is null
 or declared_total_vnd is null or declared_total_vnd<0 or document_lines is null or jsonb_typeof(document_lines)<>'array' or jsonb_array_length(document_lines) not between 1 and 100
 then raise exception 'invalid_supplier_document' using errcode='22023';end if;
 h:=private.command_payload_hash(jsonb_build_array(target_branch_id,target_supplier_id,target_document_kind,trim(target_document_number),target_document_date,declared_total_vnd,document_lines));
 select * into r from public.command_receipts where command_receipts.operation_id=register_supplier_document.operation_id;
 if found then if r.command_name<>'register_supplier_document' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 perform 1 from public.suppliers where id=target_supplier_id and branch_id=target_branch_id;if not found then raise exception 'supplier_document_party_scope_mismatch' using errcode='42501';end if;
 insert into public.supplier_documents(branch_id,supplier_id,document_kind,document_number,document_date,declared_value_vnd,source_value_vnd,match_state,created_by)
 values(target_branch_id,target_supplier_id,target_document_kind,trim(target_document_number),target_document_date,declared_total_vnd,0,'VARIANCE_OPEN',auth.uid()) returning id into did;
 for item in select v from jsonb_array_elements(document_lines) v loop
  kind:=item->>'source_kind';sid:=(item->>'source_id')::uuid;qty:=(item->>'document_quantity')::numeric;price:=(item->>'document_unit_cost')::numeric;value_amount:=(item->>'document_value_vnd')::bigint;
  perform private.require_exact_quantity(qty);if price is null or price<0 or price>=100000000000000000000000000 or price>= 'Infinity'::numeric or(target_document_kind='INVOICE' and price=0) or price<>trunc(price,6) then raise exception 'document_price_invalid_or_precision_exceeds_six' using errcode='22023';end if;
  if kind is null or sid is null or value_amount is null or value_amount<0 or (target_document_kind='CREDIT_NOTE') is distinct from(kind='RETURN_CREDIT') then raise exception 'supplier_document_line_kind_invalid' using errcode='22023';end if;
  select * into src from private.supplier_document_source(kind,sid,target_branch_id,target_supplier_id);
  if src.purchase_line_id is null then raise exception 'supplier_document_source_scope_mismatch' using errcode='42501';end if;
  perform 1 from public.purchase_order_lines where id=src.purchase_line_id for update;
  computed:=round(qty*price)::bigint;
  result:=case when qty<>src.quantity then 'QUANTITY_VARIANCE'
   when target_document_kind='CREDIT_NOTE' and value_amount=src.value_vnd and((price=src.unit_cost and abs(computed-value_amount-src.return_charge_vnd)<=1) or computed=value_amount)
    then case when src.return_charge_vnd>0 then 'MATCHED_APPROVED_RETURN_CHARGE' else 'MATCHED' end
   when price<>src.unit_cost then 'PRICE_VARIANCE' when value_amount<>src.value_vnd then 'VALUE_VARIANCE' when abs(computed-value_amount)>1 then 'ARITHMETIC_VARIANCE' else 'MATCHED' end;
  has_variance:=has_variance or result not in('MATCHED','MATCHED_APPROVED_RETURN_CHARGE');line_index:=line_index+1;
  insert into public.supplier_document_lines(document_id,line_number,source_kind,source_id,purchase_order_line_id,material_id,document_uom_id,source_quantity,document_quantity,source_unit_cost,document_unit_cost,source_value_vnd,document_value_vnd,approved_return_charge_vnd,match_result)
  values(did,line_index,kind,sid,src.purchase_line_id,src.material_id,src.uom_id,src.quantity,qty,src.unit_cost,price,src.value_vnd,value_amount,src.return_charge_vnd,result);
  sum_declared:=sum_declared+value_amount;sum_source:=sum_source+src.value_vnd;
 end loop;
 if sum_declared<>declared_total_vnd then raise exception 'supplier_document_total_must_equal_lines' using errcode='23514';end if;
 update public.supplier_documents set source_value_vnd=sum_source,match_state=case when has_variance then 'VARIANCE_OPEN' else 'MATCHED' end where id=did;
 insert into public.command_receipts values(operation_id,auth.uid(),'register_supplier_document',h,'supplier_document',did,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields) values(auth.uid(),target_branch_id,'supplier_document.registered','supplier_document',did,operation_id,array['supplier_id','document_reference','source_line_coverage','match_state']);return did;
end $function$

CREATE OR REPLACE FUNCTION public.release_inventory_reservation(target_reservation_id uuid, expected_version integer, release_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare reservation public.inventory_reservations%rowtype; hash text; receipt public.command_receipts%rowtype;
begin
  select * into reservation from public.inventory_reservations where id = target_reservation_id for update;
  if reservation.id is null then raise exception 'reservation_not_found' using errcode = '23503'; end if;
  if not private.has_permission(reservation.branch_id, 'inventory.reserve') then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(trim(release_reason)) < 3 then raise exception 'release_reason_required' using errcode = '22023'; end if;
  hash := private.command_payload_hash(jsonb_build_object('reservation_id', target_reservation_id, 'version', expected_version, 'reason', trim(release_reason)));
  select * into receipt from public.command_receipts where command_receipts.operation_id = release_inventory_reservation.operation_id;
  if found then if receipt.command_name <> 'release_inventory_reservation' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if reservation.state <> 'ACTIVE' or reservation.version  IS DISTINCT FROM expected_version or reservation.delivery_line_id is not null then raise exception 'reservation_not_releasable' using errcode = 'PT409'; end if;
  update public.inventory_reservations set state = 'RELEASED', version = version + 1, finalized_at = now() where id = target_reservation_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'release_inventory_reservation', hash, 'inventory_reservation', target_reservation_id, now());
  return target_reservation_id;
end
$function$

CREATE OR REPLACE FUNCTION public.request_quotation_change(target_revision_id uuid, reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  revision_json jsonb;
  quotation_json jsonb;
  quotation_id uuid;
  customer_id uuid;
  payload_hash text;
  receipt public.command_receipts%rowtype;
  request_id uuid;
begin
  select to_jsonb(r) into revision_json from public.quotation_revisions r where r.id = target_revision_id;
  if revision_json is null then raise exception 'quotation_revision_not_found' using errcode = '23503'; end if;
  quotation_id := (revision_json->>'quotation_id')::uuid;
  select to_jsonb(q) into quotation_json from public.quotations q where q.id = quotation_id;
  customer_id := (quotation_json->>'customer_id')::uuid;
  if coalesce(private.portal_customer_role(customer_id), '') not in ('OWNER','FINANCE_CONTACT') then
    raise exception 'quotation_change_forbidden' using errcode = '42501';
  end if;
  if char_length(trim(reason)) not between 10 and 1000 then raise exception 'invalid_change_reason' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('revision', target_revision_id, 'reason', trim(reason)));
  select * into receipt from public.command_receipts r where r.operation_id = request_quotation_change.operation_id;
  if found then
    if receipt.command_name <> 'request_quotation_change' or receipt.payload_hash <> payload_hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  if nullif(quotation_json->>'current_revision_id', '')::uuid is distinct from target_revision_id then
    raise exception 'stale_quotation_revision' using errcode = 'PT409';
  end if;
  insert into public.quotation_change_requests(quotation_revision_id, quotation_id, customer_id, reason, requested_by)
  values(target_revision_id, quotation_id, customer_id, trim(reason), (select auth.uid()))
  returning id into request_id;
  insert into public.command_receipts
  values(operation_id, (select auth.uid()), 'request_quotation_change', payload_hash, 'quotation_change_request', request_id, now());
  return request_id;
end $function$

CREATE OR REPLACE FUNCTION public.reserve_inventory(target_sales_order_line_id uuid, target_warehouse_id uuid, requested_base_quantity numeric, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sale_line public.sales_order_lines%rowtype; sale_order public.sales_orders%rowtype; hash text;
  receipt public.command_receipts%rowtype; reservation_id uuid;
begin
  select * into sale_line from public.sales_order_lines where id = target_sales_order_line_id;
  select * into sale_order from public.sales_orders where id = sale_line.sales_order_id;
  if sale_order.id is null or sale_order.commercial_state <> 'CONFIRMED' or not private.has_permission(sale_order.branch_id, 'inventory.reserve') then raise exception 'forbidden_or_order_not_confirmed' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('sales_line_id', target_sales_order_line_id, 'warehouse_id', target_warehouse_id, 'quantity', requested_base_quantity));
  select * into receipt from public.command_receipts where command_receipts.operation_id = reserve_inventory.operation_id;
  if found then if receipt.command_name <> 'reserve_inventory' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  perform private.require_exact_quantity(requested_base_quantity,false);

  reservation_id := private.reserve_inventory_for_line(target_sales_order_line_id, null, target_warehouse_id, requested_base_quantity, (select auth.uid()));
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'reserve_inventory', hash, 'inventory_reservation', reservation_id, now());
  return reservation_id;
end
$function$

CREATE OR REPLACE FUNCTION public.resolve_commission_reconciliation(target_case_id uuid, resolution_kind text, target_unpaid_earning_id uuid, target_adjustment_rule_id uuid, expected_earning_version integer, resolution_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.commission_reconciliation_cases%rowtype; target public.earning_events%rowtype; rule public.compensation_rules%rowtype;
 receipt public.command_receipts%rowtype; hash text; resolution_id uuid:=gen_random_uuid(); basis uuid; adjustment uuid; payable uuid;
begin
 perform private.lock_saved_command_intent(operation_id,'resolve_commission_reconciliation');
 select * into c from public.commission_reconciliation_cases where id=target_case_id for update;
 if c.id is null or not private.has_permission(c.branch_id,'compensation.manage')
 then raise exception 'forbidden_or_commission_case_not_found' using errcode='42501';end if;
 if operation_id is null or resolution_kind not in('WAIVE','RECOVER_UNPAID_COMMISSION')
  or coalesce(length(trim(resolution_reason)),0) not between 3 and 500 then raise exception 'invalid_commission_resolution' using errcode='22023';end if;
 hash:=private.command_payload_hash(jsonb_build_object('case',target_case_id,'kind',resolution_kind,'earning',target_unpaid_earning_id,
  'rule',target_adjustment_rule_id,'version',expected_earning_version,'reason',trim(resolution_reason)));
 perform pg_advisory_xact_lock(hashtextextended(operation_id::text,0));
 select * into receipt from public.command_receipts r where r.operation_id=resolve_commission_reconciliation.operation_id;
 if found then
  if receipt.command_name<>'resolve_commission_reconciliation' or receipt.payload_hash<>hash or receipt.actor_auth_user_id is distinct from auth.uid()
  then raise exception 'operation_payload_conflict' using errcode='23505';end if;return receipt.result_entity_id;
 end if;
 if exists(select 1 from public.commission_review_resolutions where case_id=c.id)
 then raise exception 'commission_case_already_resolved' using errcode='55000';end if;
 if resolution_kind='WAIVE' then
  if not private.operational_owner(c.branch_id) or target_unpaid_earning_id is not null or target_adjustment_rule_id is not null or expected_earning_version is not null
  then raise exception 'commission_waiver_requires_owner' using errcode='42501';end if;
 else
  if not private.has_permission(c.branch_id,'compensation.approve') then raise exception 'commission_recovery_approval_required' using errcode='42501';end if;
  select * into target from public.earning_events where id=target_unpaid_earning_id for update;
  if target.id is null or target.branch_id<>c.branch_id or target.employee_id<>c.employee_id or target.classification<>'SALES_COMMISSION'
   or target.approval_state<>'APPROVED' or target.approved_amount_vnd<=0
  then raise exception 'commission_recovery_source_mismatch' using errcode='23514';end if;
  if target.version is distinct from expected_earning_version then raise exception 'commission_recovery_version_conflict' using errcode='PT409';end if;
  select id into payable from public.payable_obligations where earning_event_id=target.id for update;
  if payable is null or private.current_payable_outstanding(payable)<c.reduction_amount_vnd
  then raise exception 'commission_recovery_exceeds_unpaid' using errcode='23514';end if;
  select * into rule from public.compensation_rules where id=target_adjustment_rule_id;
  if rule.id is null or rule.branch_id<>c.branch_id or rule.earning_type<>'ADJUSTMENT' or rule.calculation_kind<>'FIXED_PER_BASIS'
   or rule.rate_vnd_per_unit<>1 or rule.classification<>'OPEX'
   or(rule.employee_id is not null and rule.employee_id<>c.employee_id)
  then raise exception 'commission_recovery_adjustment_rule_required' using errcode='23514';end if;
  basis:=public.record_compensation_basis(c.branch_id,c.employee_id,'ADJUSTMENT',-c.reduction_amount_vnd::numeric,
   current_date,current_date,trim(resolution_reason),target.id,null,gen_random_uuid());
  adjustment:=public.calculate_earning_event(rule.id,'MANUAL_BASIS',basis,gen_random_uuid());
  perform public.approve_earning_event(adjustment,-c.reduction_amount_vnd,current_date,1,gen_random_uuid());
 end if;
 insert into public.commission_review_resolutions(id,case_id,branch_id,employee_id,resolution_kind,reduction_amount_vnd,
  target_earning_event_id,adjustment_earning_event_id,reason,recorded_by)
 values(resolution_id,c.id,c.branch_id,c.employee_id,resolution_kind,c.reduction_amount_vnd,target_unpaid_earning_id,adjustment,trim(resolution_reason),auth.uid());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
 values(auth.uid(),c.branch_id,'commission.review_resolved','commission_review_resolution',resolution_id,operation_id,
  array['source_case','resolution','unpaid_commission_adjustment'],trim(resolution_reason));
 insert into public.command_receipts values(operation_id,auth.uid(),'resolve_commission_reconciliation',hash,'commission_review_resolution',resolution_id,now());
 return resolution_id;
end $function$

CREATE OR REPLACE FUNCTION public.resolve_return_case(target_return_case_id uuid, resolution text, target_warehouse_id uuid, resolution_reason text, target_evidence_id uuid, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare case_row public.return_cases%rowtype; line public.delivery_lines%rowtype; delivery public.deliveries%rowtype;
  verified_line public.delivery_verification_lines%rowtype; handoff_line public.delivery_handoff_lines%rowtype;
  unit_cost numeric; value_amount bigint; hash text; receipt public.command_receipts%rowtype;
begin
  select * into case_row from public.return_cases where id = target_return_case_id for update;
  select * into line from public.delivery_lines where id = case_row.delivery_line_id;
  select * into delivery from public.deliveries where id = line.delivery_id for update;
  select * into verified_line from public.delivery_verification_lines where id = case_row.delivery_verification_line_id;
  if case_row.id is null or not private.has_permission(case_row.branch_id, 'delivery.exception') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('return_case_id', target_return_case_id, 'resolution', resolution, 'warehouse_id', target_warehouse_id, 'reason', trim(resolution_reason), 'evidence_id', target_evidence_id, 'version', expected_version));
  select * into receipt from public.command_receipts where command_receipts.operation_id = resolve_return_case.operation_id;
  if found then if receipt.command_name <> 'resolve_return_case' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if resolution_reason is null or char_length(trim(resolution_reason)) not between 3 and 500 then raise exception 'return_resolution_reason_required' using errcode='22023';end if;
  if case_row.state <> 'OPEN' or case_row.version  IS DISTINCT FROM expected_version or char_length(trim(resolution_reason)) < 3 then raise exception 'return_case_version_conflict' using errcode = 'PT409'; end if;
  perform private.assert_verified_evidence(target_evidence_id, case_row.branch_id);
  select hl.* into handoff_line from public.delivery_handoff_lines hl join public.delivery_handoffs h on h.id = hl.delivery_handoff_id
    where h.delivery_id = delivery.id and hl.delivery_line_id = line.id;
  if line.source_mode = 'SUPPLIER_DIRECT' then
    select sum(sfl.payable_amount_vnd)::numeric / nullif(sum(sfl.supplier_base_quantity), 0)
      into unit_cost
    from public.supply_allocations sa
    join public.supplier_fulfillment_lines sfl
      on sfl.purchase_order_line_id = sa.purchase_order_line_id
      and sfl.sales_order_line_id = line.sales_order_line_id
    join public.supplier_fulfillments sf on sf.id = sfl.supplier_fulfillment_id
    where sa.id = line.supply_allocation_id and sf.branch_id = case_row.branch_id;
  else
    unit_cost := coalesce(verified_line.inventory_unit_cost_vnd_per_base, handoff_line.unit_cost_vnd_per_base);
  end if;
  if unit_cost is null or unit_cost <= 0 then raise exception 'return_cost_basis_missing' using errcode = '23514'; end if;
  value_amount := case when case_row.case_kind='CUSTOMER_RETURN'
    or(line.source_mode='SUPPLIER_DIRECT' and case_row.case_kind='TRANSIT_REMAINDER')
    then private.return_cost_portion(case_row.id) else round(case_row.base_quantity * unit_cost)::bigint end;
  if case_row.case_kind in ('TRANSIT_REMAINDER','TRANSIT_LOSS') then
    if line.source_mode='SUPPLIER_DIRECT' then
      if case_row.base_quantity>handoff_line.moved_base_quantity-verified_line.accepted_base_quantity
        -coalesce((select sum(r.base_quantity) from public.return_cases r where r.delivery_line_id=line.id
          and r.case_kind in('TRANSIT_REMAINDER','TRANSIT_LOSS') and r.state in('RETURNED','LOSS_APPROVED')),0)
      then raise exception 'return_exceeds_transit_position' using errcode='23514';end if;
      if value_amount<=0 then raise exception 'return_cost_below_currency_precision' using errcode='23514';end if;
    else
    if case_row.base_quantity > (select p.base_quantity from private.delivery_line_transit_position(line.id) p) then
      raise exception 'return_exceeds_transit_position' using errcode = '23514';
    end if;
    select case when case_row.base_quantity = p.base_quantity then p.inventory_value_vnd
      else value_amount end into value_amount from private.delivery_line_transit_position(line.id) p;
    if value_amount <= 0 then raise exception 'return_cost_below_currency_precision' using errcode = '23514'; end if;
    end if;
  end if;
  if case_row.case_kind in ('CUSTOMER_RETURN','TRANSIT_REMAINDER') then
    if resolution <> 'RETURNED' or not exists (select 1 from public.warehouses where id = target_warehouse_id and branch_id = case_row.branch_id and active) then raise exception 'invalid_return_resolution' using errcode = '22023'; end if;
    perform 1 from public.warehouses where id = target_warehouse_id for update;
    if case_row.case_kind = 'TRANSIT_REMAINDER' and line.source_mode<>'SUPPLIER_DIRECT' then
      insert into public.inventory_movements(branch_id, material_id, base_uom_id, location_kind, delivery_id,
        movement_type, base_quantity_delta, inventory_value_delta_vnd, unit_cost_vnd_per_base,
        source_return_case_id, occurred_at, recorded_by)
      values (case_row.branch_id, line.material_id, line.base_uom_id, 'IN_TRANSIT', delivery.id,
        'RETURN_TRANSFER', -case_row.base_quantity, -value_amount, unit_cost, case_row.id, now(), (select auth.uid()));
    end if;
    insert into public.inventory_movements(branch_id, material_id, base_uom_id, location_kind, warehouse_id,
      movement_type, base_quantity_delta, inventory_value_delta_vnd, unit_cost_vnd_per_base,
      source_return_case_id, occurred_at, recorded_by)
    values (case_row.branch_id, line.material_id, line.base_uom_id, 'WAREHOUSE', target_warehouse_id,
      case when case_row.case_kind = 'CUSTOMER_RETURN' then 'CUSTOMER_RETURN' else 'RETURN_TRANSFER' end,
      case_row.base_quantity, value_amount, unit_cost, case_row.id, now(), (select auth.uid()));
    if case_row.case_kind = 'CUSTOMER_RETURN' or(line.source_mode='SUPPLIER_DIRECT' and case_row.case_kind='TRANSIT_REMAINDER') then
      insert into public.direct_cost_entries(branch_id, sales_order_id, return_case_id, amount_delta_vnd, cost_kind, recorded_by)
      values (case_row.branch_id, delivery.sales_order_id, case_row.id, -value_amount, 'RETURN_REVERSAL', (select auth.uid()));
    end if;
    update public.return_cases set state = 'RETURNED', resolution_warehouse_id = target_warehouse_id,
      resolution_reason = trim(resolve_return_case.resolution_reason), evidence_object_id = coalesce(target_evidence_id, evidence_object_id),
      version = version + 1, resolved_by = (select auth.uid()), resolved_at = now() where id = case_row.id;
  elsif case_row.case_kind = 'TRANSIT_LOSS' then
    if resolution <> 'LOSS_APPROVED' then raise exception 'invalid_loss_resolution' using errcode = '22023'; end if;
    if line.source_mode<>'SUPPLIER_DIRECT' then
    insert into public.inventory_movements(branch_id, material_id, base_uom_id, location_kind, delivery_id,
      movement_type, base_quantity_delta, inventory_value_delta_vnd, unit_cost_vnd_per_base,
      source_return_case_id, occurred_at, recorded_by)
    values (case_row.branch_id, line.material_id, line.base_uom_id, 'IN_TRANSIT', delivery.id,
      'TRANSIT_LOSS', -case_row.base_quantity, -value_amount, unit_cost, case_row.id, now(), (select auth.uid()));
    insert into public.direct_cost_entries(branch_id, sales_order_id, return_case_id, amount_delta_vnd, cost_kind, recorded_by)
    values (case_row.branch_id, delivery.sales_order_id, case_row.id, value_amount, 'LOSS', (select auth.uid()));
    end if; -- Supplier-direct source cost already includes the lost units; do not post it twice.
    update public.return_cases set state = 'LOSS_APPROVED', resolution_reason = trim(resolve_return_case.resolution_reason),
      evidence_object_id = coalesce(target_evidence_id, evidence_object_id), version = version + 1,
      resolved_by = (select auth.uid()), resolved_at = now() where id = case_row.id;
  else raise exception 'invalid_return_resolution' using errcode = '22023'; end if;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
   values((select auth.uid()),case_row.branch_id,'delivery.return_resolved','return_case',case_row.id,operation_id,
    array['state','resolution_warehouse_id','physical_custody','source_cost'],trim(resolution_reason));
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'resolve_return_case', hash, 'return_case', case_row.id, now());
  return case_row.id;
end
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_credit_offset(target_offset_operation_id uuid, reversal_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.customer_credits%rowtype; settlement_row public.customer_credit_settlements%rowtype; allocation_row public.payment_allocations%rowtype;
 receipt public.command_receipts%rowtype; original_receipt public.command_receipts%rowtype; hash text; allocation_id uuid;
begin
 select * into original_receipt from public.command_receipts where command_receipts.operation_id=target_offset_operation_id and command_name='offset_customer_credit';
 select * into c from public.customer_credits where id=original_receipt.result_entity_id;
 if c.id is null or not private.has_permission(c.branch_id,'finance.payment.reverse') then raise exception 'forbidden_or_customer_credit_not_found' using errcode='42501';end if;
 hash:=private.command_payload_hash(jsonb_build_object('offset_operation_id',target_offset_operation_id,'reason',trim(reversal_reason)));
 perform private.lock_saved_command_intent(operation_id,'reverse_customer_credit_offset');
 select * into c from public.customer_credits where id=c.id for update;
 select * into receipt from public.command_receipts where command_receipts.operation_id=reverse_customer_credit_offset.operation_id;
 if found then if receipt.command_name<>'reverse_customer_credit_offset' or receipt.payload_hash<>hash then raise exception 'operation_payload_conflict' using errcode='23505';end if;return receipt.result_entity_id;end if;
 if coalesce(length(trim(reversal_reason)),0) not between 3 and 500 then raise exception 'reversal_reason_required' using errcode='22023';end if;
 perform 1 from public.payments p where p.id in(select source_payment_id from public.customer_credit_funds where credit_id=c.id) order by p.id for update;
 perform 1 from public.receivable_obligations o where o.id in(select a.receivable_obligation_id from public.customer_credit_settlements s
  join public.payment_allocations a on a.id=s.payment_allocation_id where s.source_operation_id=target_offset_operation_id) order by o.id for update;
 for settlement_row in select * from public.customer_credit_settlements where source_operation_id=target_offset_operation_id and amount_delta_vnd>0 order by id loop
  if exists(select 1 from public.customer_credit_settlements r where r.reversal_of_settlement_id=settlement_row.id)
  then raise exception 'customer_credit_offset_already_reversed' using errcode='55000';end if;
  if exists(select 1 from public.payment_allocations r where r.reversal_of_allocation_id=settlement_row.payment_allocation_id)
  then raise exception 'customer_credit_offset_has_downstream_credit' using errcode='55000';end if;
  select * into allocation_row from public.payment_allocations where id=settlement_row.payment_allocation_id;
  insert into public.payment_allocations(payment_id,receivable_obligation_id,amount_delta_vnd,reversal_of_allocation_id,allocated_by)
   values(allocation_row.payment_id,allocation_row.receivable_obligation_id,-allocation_row.amount_delta_vnd,allocation_row.id,(select auth.uid())) returning id into allocation_id;
  insert into public.customer_credit_settlements(credit_fund_id,settlement_kind,amount_delta_vnd,payment_allocation_id,reversal_of_settlement_id,source_operation_id,recorded_by)
   values(settlement_row.credit_fund_id,'OFFSET',-settlement_row.amount_delta_vnd,allocation_id,settlement_row.id,operation_id,(select auth.uid()));
 end loop;
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values((select auth.uid()),c.branch_id,'customer.credit_offset_reversed','customer_credit',c.id,operation_id,array['settlement_reversal','receivable_allocation'],trim(reversal_reason));
 insert into public.command_receipts values(operation_id,(select auth.uid()),'reverse_customer_credit_offset',hash,'customer_credit',c.id,now());
 return c.id;
end $function$

CREATE OR REPLACE FUNCTION public.reverse_payment(target_payment_id uuid, reversal_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare original public.payments%rowtype; payload_hash text; receipt public.command_receipts%rowtype; reversal_id uuid;
begin

  select * into original from public.payments where id=target_payment_id;
  if original.id is null or not private.has_permission(original.branch_id,'finance.payment.reverse') then raise exception 'forbidden_or_payment_not_found' using errcode='42501'; end if;
  if char_length(trim(reversal_reason)) not between 3 and 500 then raise exception 'reversal_reason_required' using errcode='22023'; end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('payment_id',target_payment_id,'reason',trim(reversal_reason)));
  select * into receipt from public.command_receipts where command_receipts.operation_id=reverse_payment.operation_id;
  if found then if receipt.command_name<>'reverse_payment' or receipt.payload_hash<>payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505'; end if; return receipt.result_entity_id; end if;
  if original.customer_credit_refund_id is not null then perform 1 from public.customer_credits where id=original.customer_credit_refund_id for update;end if;
  select * into original from public.payments where id=target_payment_id for update;
  if exists(select 1 from public.payments p where p.id=target_payment_id and p.supplier_credit_refund_id is not null) or exists(select 1 from public.supplier_credit_funds f where f.source_payment_id=target_payment_id) then raise exception 'payment_funds_supplier_credit_use_source_workflow' using errcode='23514';end if;
  if exists(select 1 from public.customer_credit_funds f where f.source_payment_id=original.id) then raise exception 'payment_funds_customer_credit_use_source_workflow' using errcode='55000';end if;
  if original.reversal_of_payment_id is not null or exists(select 1 from public.payments where reversal_of_payment_id=original.id) then raise exception 'payment_already_reversed_or_is_reversal' using errcode='55000'; end if;
  insert into public.payments(branch_id,payment_number,direction,customer_id,supplier_id,employee_id,account_id,amount_vnd,method,external_reference,effective_at,reversal_of_payment_id,reversal_reason,posted_by) values(original.branch_id,'REV-'||to_char((now() at time zone 'Asia/Ho_Chi_Minh')::date,'YYYYMM')||'-'||lpad(nextval('public.finance_payment_number_seq')::text,6,'0'),case when original.direction='RECEIPT' then 'DISBURSEMENT' else 'RECEIPT' end,original.customer_id,original.supplier_id,original.employee_id,original.account_id,original.amount_vnd,original.method,original.external_reference,now(),original.id,trim(reversal_reason),(select auth.uid())) returning id into reversal_id;
  insert into public.payment_allocations(payment_id,receivable_obligation_id,payable_obligation_id,amount_delta_vnd,reversal_of_allocation_id,allocated_by) select reversal_id,receivable_obligation_id,payable_obligation_id,-amount_delta_vnd,id,(select auth.uid()) from public.payment_allocations where payment_id=original.id and reversal_of_allocation_id is null;
  insert into public.advance_allocations(branch_id,advance_id,amount_delta_vnd,reversal_of_advance_allocation_id,source_reversal_payment_id,recorded_by)
  select branch_id,advance_id,-amount_delta_vnd,id,reversal_id,(select auth.uid()) from public.advance_allocations
  where advance_id in(select id from public.advances where payment_id=original.id and reversal_of_advance_id is null)
   and amount_delta_vnd>0;
  insert into public.advances(branch_id,payment_id,advance_side,customer_id,supplier_id,amount_delta_vnd,reversal_of_advance_id,recorded_by) select branch_id,reversal_id,advance_side,customer_id,supplier_id,-amount_delta_vnd,id,(select auth.uid()) from public.advances where payment_id=original.id and reversal_of_advance_id is null;
  if original.customer_credit_refund_id is not null then
    insert into public.customer_credit_settlements(credit_fund_id,settlement_kind,amount_delta_vnd,payment_id,
      reversal_of_settlement_id,source_reversal_payment_id,source_operation_id,recorded_by)
    select credit_fund_id,'REFUND',-amount_delta_vnd,payment_id,id,reversal_id,operation_id,(select auth.uid())
      from public.customer_credit_settlements where payment_id=original.id and amount_delta_vnd>0;
  end if;
  insert into public.command_receipts values(operation_id,(select auth.uid()),'reverse_payment',payload_hash,'payment',reversal_id,now());
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason) values((select auth.uid()),original.branch_id,'payment.reversed','payment',original.id,operation_id,array['reversal'],trim(reversal_reason));
  return reversal_id;
end $function$

CREATE OR REPLACE FUNCTION public.reverse_payment_notice_match(target_match_id uuid, reversal_reason text, expected_notice_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.payment_notice_matches%rowtype;n public.payment_notices%rowtype;r public.command_receipts%rowtype;h text;rid uuid;
begin
 select * into m from public.payment_notice_matches where id=target_match_id;
 if m.id is null or not private.has_permission(m.branch_id,'finance.payment_notice.review') or not private.has_permission(m.branch_id,'finance.reconcile') then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'reverse_payment_notice_match');perform pg_advisory_xact_lock(hashtextextended('notice_match:'||operation_id::text,0));
 h:=private.command_payload_hash(jsonb_build_array(target_match_id,trim(reversal_reason),expected_notice_version));select * into r from public.command_receipts where command_receipts.operation_id=reverse_payment_notice_match.operation_id;
 if found then if r.command_name<>'reverse_payment_notice_match' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 perform 1 from public.payments where id=m.payment_id for update;select * into n from public.payment_notices where id=m.notice_id for update;
 if n.version is distinct from expected_notice_version then raise exception 'stale_payment_notice_version' using errcode='PT409';end if;
 if operation_id is null or reversal_reason is null or char_length(trim(reversal_reason)) not between 3 and 500 then raise exception 'notice_reversal_reason_required' using errcode='22023';end if;
 insert into public.payment_notice_match_reversals(match_id,branch_id,reason,recorded_by,source_operation_id) values(m.id,m.branch_id,trim(reversal_reason),auth.uid(),operation_id) returning id into rid;
 update public.payment_notices set version=version+1 where id=n.id;
 insert into public.command_receipts values(operation_id,auth.uid(),'reverse_payment_notice_match',h,'payment_notice_match_reversal',rid,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason) values(auth.uid(),m.branch_id,'payment_notice.match_reversed','payment_notice',n.id,operation_id,array['source_match','matching_coverage','notice_version'],trim(reversal_reason));return rid;
end $function$

CREATE OR REPLACE FUNCTION public.review_payment_notice(target_payment_notice_id uuid, target_state text, target_review_note text, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  notice public.payment_notices%rowtype;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
 perform private.lock_saved_command_intent(operation_id,'review_payment_notice');
 perform pg_advisory_xact_lock(hashtextextended('finance_review:'||operation_id::text,0));
  select * into notice from public.payment_notices n where n.id = target_payment_notice_id;
  if notice.id is null or not private.has_permission(notice.branch_id, 'finance.payment_notice.review') then
    raise exception 'payment_notice_review_forbidden' using errcode = '42501';
  end if;
  if target_state not in ('UNDER_REVIEW','ACCEPTED','REJECTED') then raise exception 'invalid_review_state' using errcode = '22023'; end if;
  if nullif(trim(target_review_note), '') is not null and char_length(trim(target_review_note)) not between 3 and 500 then raise exception 'invalid_review_note' using errcode = '22023'; end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'notice', target_payment_notice_id, 'state', target_state, 'note', nullif(trim(target_review_note), ''), 'version', expected_version
  ));
  select * into receipt from public.command_receipts r where r.operation_id = review_payment_notice.operation_id;
  if found then
    if receipt.command_name <> 'review_payment_notice' or receipt.payload_hash <> payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode = '23505'; end if;
    return receipt.result_entity_id;
  end if;
  select * into notice from public.payment_notices n where n.id = target_payment_notice_id for update;
  if target_state<>'ACCEPTED' and exists(select 1 from public.payment_notice_matches m where m.notice_id=notice.id and not exists(select 1 from public.payment_notice_match_reversals rev where rev.match_id=m.id)) then raise exception 'notice_active_matches_require_source_correction' using errcode='23514';end if;
  if notice.version  IS DISTINCT FROM expected_version then raise exception 'stale_payment_notice_version' using errcode = 'PT409'; end if;
  insert into public.payment_notice_review_events(payment_notice_id, from_state, to_state, review_note, reviewed_by)
  values(notice.id, notice.review_state, target_state, nullif(trim(target_review_note), ''), (select auth.uid()));
  update public.payment_notices set
    review_state = target_state,
    version = version + 1,
    review_note = nullif(trim(target_review_note), ''),
    reviewed_by = case when target_state in ('ACCEPTED','REJECTED') then (select auth.uid()) else reviewed_by end,
    reviewed_at = case when target_state in ('ACCEPTED','REJECTED') then now() else reviewed_at end
  where id = notice.id;
  insert into public.command_receipts
  values(operation_id, (select auth.uid()), 'review_payment_notice', payload_hash, 'payment_notice', notice.id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason)
  values ((select auth.uid()), notice.branch_id,
    case target_state when 'REJECTED' then 'payment_notice.rejected'
      when 'ACCEPTED' then 'payment_notice.accepted' else 'payment_notice.under_review' end,
    'payment_notice', notice.id, operation_id, array['review_state', 'review_note'], nullif(trim(target_review_note), ''));
  return notice.id;
end $function$

CREATE OR REPLACE FUNCTION public.review_supplier_document(target_document_id uuid, review_decision text, review_reason text, expected_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.supplier_documents%rowtype;r public.command_receipts%rowtype;h text;
begin
 select * into d from public.supplier_documents where id=target_document_id;
 if d.id is null or not private.has_permission(d.branch_id,case when review_decision='CANCEL' then 'finance.ap.adjust' else 'finance.reconcile' end) then raise exception 'forbidden' using errcode='42501';end if;
 perform private.lock_saved_command_intent(operation_id,'review_supplier_document');perform pg_advisory_xact_lock(hashtextextended('supplier_document:'||operation_id::text,0));
 h:=private.command_payload_hash(jsonb_build_array(target_document_id,review_decision,trim(review_reason),expected_version));select * into r from public.command_receipts where command_receipts.operation_id=review_supplier_document.operation_id;
 if found then if r.command_name<>'review_supplier_document' or r.payload_hash<>h or r.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;return r.result_entity_id;end if;
 select * into d from public.supplier_documents where id=target_document_id for update;
 if d.version is distinct from expected_version or d.business_state<>'DRAFT' then raise exception 'supplier_document_version_conflict' using errcode='PT409';end if;
 if operation_id is null or review_decision is null or review_decision not in('APPROVE_MATCH','CANCEL') or review_reason is null or char_length(trim(review_reason)) not between 3 and 500 then raise exception 'invalid_supplier_document_review' using errcode='22023';end if;
 if review_decision='APPROVE_MATCH' and d.match_state<>'MATCHED' then raise exception 'supplier_document_variance_requires_correct_sources_or_document' using errcode='23514';end if;
 update public.supplier_documents set business_state=case when review_decision='CANCEL' then 'CANCELLED' else 'BUSINESS_APPROVED' end,version=version+1,reviewed_by=auth.uid(),reviewed_at=now(),review_reason=trim(review_supplier_document.review_reason) where id=d.id;
 if review_decision='CANCEL' then update public.supplier_document_lines set covered=false where document_id=d.id;end if;
 insert into public.command_receipts values(operation_id,auth.uid(),'review_supplier_document',h,'supplier_document',d.id,now());
 insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason) values(auth.uid(),d.branch_id,'supplier_document.'||lower(review_decision),'supplier_document',d.id,operation_id,array['business_state','version','source_coverage'],trim(review_reason));return d.id;
end $function$

CREATE OR REPLACE FUNCTION public.revoke_employee_access(target_access_id uuid, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  a public.employee_branch_access%rowtype;
begin
  select * into a from public.employee_branch_access where id = target_access_id for update;
  if auth.uid() is null or a.id is null
    or not private.has_permission(a.branch_id, 'roles.manage')
    or a.employee_id = private.current_employee_id()
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'reason_required' using errcode = '22023';
  end if;
  if not a.active then return a.id; end if;

  update public.employee_branch_access
  set active = false, revoked_at = now()
  where id = a.id;

  delete from public.employee_permission_grants
  where employee_id = a.employee_id and branch_id = a.branch_id;

  insert into public.audit_events(
    actor_auth_user_id, branch_id, action, entity_type, entity_id,
    trace_id, changed_fields, reason
  ) values (
    auth.uid(), a.branch_id, 'employee.access.revoke', 'employee_branch_access', a.id,
    operation_id, array['active', 'explicit_permissions'], trim(change_reason)
  );
  return a.id;
end
$function$

CREATE OR REPLACE FUNCTION public.sales_order_operational_snapshot(target_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.sales_orders%rowtype;required_qty numeric;accepted_qty numeric;cargo_qty numeric:=0;line record;running bigint;open_physical bigint;pending_return_credit bigint;pending_customer_money bigint;pending_vendor bigint;pending_commission bigint;open_work bigint;document_variance bigint;ar_count bigint;unpaid bigint;negative_debt bigint;delivery_state text;payment_state text;complete boolean;
begin
 select * into o from public.sales_orders where id=target_order_id;
 if o.id is null or not(private.has_permission(o.branch_id,'orders.read') or private.has_permission(o.branch_id,'delivery.read')) then raise exception 'forbidden_or_order_not_found' using errcode='42501';end if;
 select coalesce(sum(l.quantity*l.conversion_numerator/l.conversion_denominator),0) into required_qty from public.sales_order_lines l where l.sales_order_id=o.id;
 select coalesce(sum(v.accepted_base_quantity),0) into accepted_qty from public.delivery_verification_lines v join public.delivery_lines l on l.id=v.delivery_line_id join public.deliveries d on d.id=l.delivery_id where d.sales_order_id=o.id;
 for line in select l.* from public.delivery_lines l join public.deliveries d on d.id=l.delivery_id where d.sales_order_id=o.id loop
  if line.source_mode='SUPPLIER_DIRECT' then
   cargo_qty:=cargo_qty+greatest(0,coalesce(private.delivery_loaded_quantity(line.id),0)-coalesce((select sum(v.accepted_base_quantity) from public.delivery_verification_lines v where v.delivery_line_id=line.id),0)-coalesce((select sum(r.base_quantity) from public.return_cases r where r.delivery_line_id=line.id and r.case_kind in('TRANSIT_REMAINDER','TRANSIT_LOSS') and r.state in('RETURNED','LOSS_APPROVED')),0));
  else cargo_qty:=cargo_qty+greatest(0,(select p.base_quantity from private.delivery_line_transit_position(line.id)p));end if;
 end loop;
 select count(*) into running from public.deliveries d where d.sales_order_id=o.id and d.execution_state not in('VERIFIED','CANCELLED');
 select count(*) into open_physical from public.return_cases r join public.delivery_lines l on l.id=r.delivery_line_id join public.deliveries d on d.id=l.delivery_id where d.sales_order_id=o.id and r.state='OPEN';
 select count(*) into pending_return_credit from public.return_cases r join public.delivery_lines l on l.id=r.delivery_line_id join public.deliveries d on d.id=l.delivery_id
 where d.sales_order_id=o.id and r.case_kind='CUSTOMER_RETURN' and r.state='RETURNED' and not exists(select 1 from public.customer_credits c where c.return_case_id=r.id);
 select count(*) into pending_customer_money from public.customer_credits c join public.return_cases r on r.id=c.return_case_id join public.delivery_lines l on l.id=r.delivery_line_id join public.deliveries d on d.id=l.delivery_id
 where d.sales_order_id=o.id and private.customer_credit_remaining(c.id)>0;
 select count(*) into pending_vendor from public.supplier_return_cases c left join public.supplier_fulfillment_lines fl on fl.id=c.source_fulfillment_line_id left join public.purchase_receipt_lines rl on rl.id=c.source_receipt_line_id
 join public.purchase_order_lines pl on pl.id=coalesce(fl.purchase_order_line_id,rl.purchase_order_line_id) join public.sales_order_lines sol on sol.id=coalesce(fl.sales_order_line_id,pl.linked_sales_order_line_id)
 where sol.sales_order_id=o.id and(
  (not c.dispatch_closed and c.requested_base_quantity>coalesce((select sum(e.base_quantity) from public.supplier_return_events e where e.case_id=c.id and e.event_kind='PHYSICAL_RETURN'),0))
  or coalesce((select sum(e.base_quantity)filter(where e.event_kind='PHYSICAL_RETURN')-coalesce(sum(e.base_quantity)filter(where e.event_kind='SUPPLIER_ACCEPTANCE'),0) from public.supplier_return_events e where e.case_id=c.id),0)>0
  or exists(select 1 from public.supplier_return_events e where e.case_id=c.id and e.event_kind='SUPPLIER_ACCEPTANCE' and not exists(select 1 from public.supplier_return_credits credit where credit.acceptance_event_id=e.id))
  or exists(select 1 from public.supplier_return_credits credit where credit.case_id=c.id and private.supplier_credit_remaining(credit.id)>0));
 select count(*) into pending_commission from public.commission_reconciliation_cases c join public.earning_events e on e.id=c.original_earning_event_id where e.sales_order_id=o.id and not exists(select 1 from public.commission_review_resolutions r where r.case_id=c.id);
 select count(*),coalesce(sum(greatest(0,private.current_receivable_outstanding(r.id))),0)::bigint,count(*)filter(where private.current_receivable_outstanding(r.id)<0) into ar_count,unpaid,negative_debt
 from public.receivable_obligations r join public.delivery_verifications v on v.id=r.delivery_verification_id join public.deliveries d on d.id=v.delivery_id where d.sales_order_id=o.id;
 delivery_state:=case when running>0 or cargo_qty>0 then 'IN_PROGRESS' when o.commercial_state='CLOSED' then 'CLOSED_REMAINDER' when accepted_qty>=required_qty and required_qty>0 then 'FULFILLED' when accepted_qty>0 then 'PARTIAL' else 'NOT_STARTED' end;
 payment_state:=case when negative_debt>0 then 'RECONCILIATION_REQUIRED' when ar_count=0 then 'NOT_BILLED' when unpaid=0 then 'PAID' when exists(select 1 from public.payment_allocations a join public.receivable_obligations r on r.id=a.receivable_obligation_id join public.delivery_verifications v on v.id=r.delivery_verification_id join public.deliveries d on d.id=v.delivery_id where d.sales_order_id=o.id and a.amount_delta_vnd>0) then 'PARTIAL' else 'UNPAID' end;
 select count(*) into open_work from public.work_items w join public.deliveries dl on dl.id=w.delivery_id where dl.sales_order_id=o.id and w.execution_state not in('VERIFIED','CANCELLED');
 select count(distinct doc.id) into document_variance from public.supplier_documents doc join public.supplier_document_lines l on l.document_id=doc.id join public.purchase_order_lines pl on pl.id=l.purchase_order_line_id join public.sales_order_lines sol on sol.id=pl.linked_sales_order_line_id where sol.sales_order_id=o.id and doc.match_state='VARIANCE_OPEN' and doc.business_state<>'CANCELLED';
 complete:=o.commercial_state in('CONFIRMED','CLOSED') and delivery_state in('FULFILLED','CLOSED_REMAINDER') and payment_state='PAID' and cargo_qty=0 and open_physical=0 and pending_return_credit=0 and pending_customer_money=0 and pending_vendor=0 and pending_commission=0 and open_work=0 and document_variance=0;
 return jsonb_build_object('commercial_state',o.commercial_state,'delivery_state',delivery_state,'payment_state',payment_state,'operational_complete',complete,
 'exceptions',jsonb_build_object('cargo_remaining',cargo_qty>0,'physical_return_open',open_physical>0,'customer_credit_decision_pending',pending_return_credit>0,'customer_refund_offset_pending',pending_customer_money>0,'supplier_return_or_money_pending',pending_vendor>0,'paid_commission_review_pending',pending_commission>0,'legacy_debt_reconciliation_required',negative_debt>0,'work_item_open',open_work>0,'supplier_document_variance_open',document_variance>0),
 'delivery_model','ONE_SALES_ORDER_ONE_PICKUP_PER_DELIVERY','trip_grouping_supported',false);
end $function$

CREATE OR REPLACE FUNCTION public.save_branch_config(target_id uuid, source_branch_id uuid, values_json jsonb, expected_json jsonb, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row jsonb; field_name text; creator_role uuid; creator_employee uuid;
begin
  if auth.uid() is null or not private.has_permission(source_branch_id, 'roles.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if target_id is null or operation_id is null or jsonb_typeof(values_json) <> 'object'
    or char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  for field_name in select jsonb_object_keys(values_json) loop
    if field_name <> all(array['code', 'name', 'active']) then
      raise exception 'field_not_editable' using errcode = '42501';
    end if;
  end loop;
  select to_jsonb(b) into old_row from public.branches b where b.id = target_id for update;
  if old_row is null then
    if expected_json is not null then raise exception 'record_missing' using errcode = 'PT409'; end if;
    creator_employee := private.current_employee_id();
    select a.role_id into creator_role
    from public.employee_branch_access a
      join public.roles r on r.id = a.role_id and r.active
      join public.role_permissions rp on rp.role_id = a.role_id and rp.permission_code = 'roles.manage'
    where a.employee_id = creator_employee and a.branch_id = source_branch_id and a.active
    order by a.granted_at, a.id limit 1;
    if creator_role is null then raise exception 'admin_role_required' using errcode = '42501'; end if;
    insert into public.branches(id, code, name, active)
    values(target_id, values_json->>'code', values_json->>'name', coalesce((values_json->>'active')::boolean, true));
    insert into public.employee_branch_access(employee_id, branch_id, role_id)
    values(creator_employee, target_id, creator_role);
  else
    if not private.has_permission(target_id, 'roles.manage') then
      raise exception 'forbidden' using errcode = '42501';
    end if;
    if expected_json is null then raise exception 'record_already_exists' using errcode = '23505'; end if;
    for field_name in select jsonb_object_keys(values_json) loop
      if not expected_json ? field_name or old_row->field_name is distinct from expected_json->field_name then
        raise exception 'stale_record_reload' using errcode = 'PT409';
      end if;
    end loop;
    if values_json->>'active' = 'false' and old_row->>'active' = 'true' and not exists (
      select 1 from public.employee_branch_access a join public.branches b on b.id = a.branch_id
      where a.employee_id = private.current_employee_id() and a.active and b.active and b.id <> target_id
    ) then raise exception 'last_accessible_branch' using errcode = '23514'; end if;
    update public.branches b set
      code = case when values_json ? 'code' then values_json->>'code' else b.code end,
      name = case when values_json ? 'name' then values_json->>'name' else b.name end,
      active = case when values_json ? 'active' then (values_json->>'active')::boolean else b.active end
    where b.id = target_id;
  end if;
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type,
    entity_id, trace_id, changed_fields, reason)
  values(auth.uid(), target_id, 'branch.save', 'branches', target_id, operation_id,
    array(select jsonb_object_keys(values_json)), change_reason);
  return target_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_catalog_record(kind text, target_id uuid, target_branch_id uuid, values_json jsonb, expected_json jsonb, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tab text; allowed text[]; permission text; old_row jsonb; payload jsonb;
  cols text; vals text; assignments text; k text; parent_branch uuid;
begin
  case kind
  when 'materials' then tab:='materials'; permission:='catalog.manage'; allowed:=array['code','name','group_id','base_uom_id','specification','sale_enabled','purchase_enabled','active'];
  when 'units' then tab:='units_of_measure'; permission:='catalog.manage'; allowed:=array['code','name','symbol','decimal_scale','active'];
  when 'groups' then tab:='material_groups'; permission:='catalog.manage'; allowed:=array['code','name','active'];
  when 'customers' then tab:='customers'; permission:='customers.manage'; allowed:=array['code','display_name','customer_type','phone','email','address_text','tax_code','active'];
  when 'suppliers' then tab:='suppliers'; permission:='suppliers.manage'; allowed:=array['code','name','phone','email','address_text','tax_code','payment_terms_days','active'];
  when 'sites' then tab:='customer_sites'; permission:='customers.manage'; allowed:=array['customer_id','code','name','address_text','receiver_name','receiver_phone','access_note','receiving_window','active'];
  when 'warehouses' then tab:='warehouses'; permission:='roles.manage'; allowed:=array['code','name','address_text','active'];
  when 'vehicles' then tab:='vehicles'; permission:='roles.manage'; allowed:=array['code','plate_number','capacity_quantity','capacity_uom_id','capacity_source_note','active'];
  when 'machines' then tab:='machines'; permission:='roles.manage'; allowed:=array['code','name','machine_type','active'];
  when 'conversions' then tab:='material_uom_conversions'; permission:='catalog.manage'; allowed:=array['material_id','from_uom_id','to_uom_id','numerator','denominator','conversion_type','settlement_allowed','rounding_scale','rounding_mode','source_note','active'];
  else raise exception 'unsupported_catalog' using errcode='22023'; end case;
  if auth.uid() is null or not private.has_permission(target_branch_id,permission) then raise exception 'forbidden' using errcode='42501'; end if;
  if char_length(trim(coalesce(change_reason,''))) not between 3 and 500 or target_id is null or operation_id is null or jsonb_typeof(values_json)<>'object' then raise exception 'invalid_input' using errcode='22023'; end if;
  for k in select jsonb_object_keys(values_json) loop
    if not k=any(allowed) then raise exception 'field_not_editable' using errcode='42501'; end if;
  end loop;
  execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tab) into old_row using target_id;
  if old_row is not null then
    if expected_json is null then raise exception 'record_already_exists' using errcode='23505'; end if;
    if tab in ('customers','suppliers','warehouses','vehicles','machines') and (old_row->>'branch_id')::uuid<>target_branch_id then raise exception 'forbidden' using errcode='42501'; end if;
    if tab='customer_sites' then
      select branch_id into parent_branch from public.customers where id=(old_row->>'customer_id')::uuid;
      if parent_branch is distinct from target_branch_id or values_json->>'customer_id' is distinct from old_row->>'customer_id' then raise exception 'site_customer_immutable' using errcode='42501'; end if;
    end if;
    for k in select jsonb_object_keys(values_json) loop
      if not expected_json ? k or old_row->k is distinct from expected_json->k then raise exception 'stale_record_reload' using errcode='PT409'; end if;
    end loop;
    if tab='materials' and values_json->>'base_uom_id' is distinct from old_row->>'base_uom_id' then raise exception 'base_unit_immutable' using errcode='22023'; end if;
    if tab='material_uom_conversions' and (values_json - 'active') <> (expected_json - 'active') then raise exception 'create_new_conversion_version' using errcode='22023'; end if;
  elsif expected_json is not null then raise exception 'record_missing' using errcode='PT409';
  end if;
  if kind='vehicles' and (values_json ? 'capacity_quantity' or values_json ? 'capacity_uom_id' or values_json ? 'capacity_source_note') then
    if exists(select 1 from public.delivery_assignments a join public.deliveries d on d.id=a.delivery_id
      where a.vehicle_id=target_id and a.superseded_at is null and d.execution_state in('ASSIGNED','DISPATCHED','ARRIVED','RESULT_SUBMITTED'))
      and ((values_json->>'capacity_quantity')::numeric is distinct from (old_row->>'capacity_quantity')::numeric
        or (values_json->>'capacity_uom_id')::uuid is distinct from (old_row->>'capacity_uom_id')::uuid
        or coalesce((values_json->>'active')::boolean,true)=false) then
      raise exception 'vehicle_capacity_locked_by_assignment' using errcode='PT409';
    end if;
    if values_json->>'capacity_quantity' is not null then
      perform private.require_exact_quantity((values_json->>'capacity_quantity')::numeric,false);
      if nullif(trim(values_json->>'capacity_source_note'),'') is null or length(trim(values_json->>'capacity_source_note')) not between 3 and 500
      then raise exception 'vehicle_capacity_evidence_required' using errcode='22023';end if;
    end if;
  end if;
  payload:=values_json||jsonb_build_object('id',target_id);
  if tab in ('customers','suppliers','warehouses','vehicles','machines') then payload:=payload||jsonb_build_object('branch_id',target_branch_id); end if;
  if tab='customer_sites' then
    select branch_id into parent_branch from public.customers where id=(payload->>'customer_id')::uuid and active;
    if parent_branch is distinct from target_branch_id then raise exception 'customer_outside_branch' using errcode='42501'; end if;
  end if;
  if old_row is null then
    select string_agg(format('%I',key),','),string_agg(format('r.%I',key),',') into cols,vals from jsonb_object_keys(payload) key;
    execute format('insert into public.%I (%s) select %s from jsonb_populate_record(null::public.%I,$1) r',tab,cols,vals,tab) using payload;
  else
    select string_agg(format('%I=r.%I',key,key),',') into assignments from jsonb_object_keys(values_json) key;
    execute format('update public.%I t set %s from jsonb_populate_record(null::public.%I,$1) r where t.id=$2',tab,assignments,tab) using payload,target_id;
  end if;
  if kind='vehicles' and (values_json ? 'capacity_quantity' or values_json ? 'capacity_uom_id' or values_json ? 'capacity_source_note') then
    update public.vehicles set capacity_verified_at=case when capacity_quantity is null then null else now() end,
      capacity_verified_by=case when capacity_quantity is null then null else (select auth.uid()) end where id=target_id;
  end if;
  insert into public.audit_events(actor_auth_user_id,branch_id,action,entity_type,entity_id,trace_id,changed_fields,reason)
  values(auth.uid(),target_branch_id,'catalog.save',tab,target_id,operation_id,array(select jsonb_object_keys(values_json)),change_reason);
  return target_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_command_draft(target_operation_id uuid, target_command text, target_branch_id uuid, target_entries jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d private.command_drafts%rowtype; h text; permission text; entry jsonb;
begin
 if target_operation_id is null or target_command is null or target_command not in('post_payment','receive_purchase_order','verify_supplier_fulfillment','allocate_payment','adjust_return_receivable','refund_customer_credit','offset_customer_credit','reverse_customer_credit_offset','resolve_commission_reconciliation','create_delivery_expense','approve_expense','create_warehouse_transfer','record_warehouse_transfer_event','create_supplier_return','record_supplier_return_event','approve_supplier_return_credit','refund_supplier_credit','offset_supplier_credit','register_supplier_document','review_supplier_document','create_invoice_draft','approve_invoice_business','cancel_invoice_draft','create_invoice_adjustment_draft','register_purchase_invoice_source','match_payment_notice','review_payment_notice','record_payment_reconciliation','reverse_payment_notice_match')
 or target_entries is null or jsonb_typeof(target_entries) is distinct from 'array'
 or jsonb_array_length(target_entries)>200 or octet_length(target_entries::text)>65536
 then raise exception 'invalid_command_draft' using errcode='22023';end if;
 permission:=case target_command when 'post_payment' then 'finance.payment.post' when 'allocate_payment' then 'finance.payment.post' when 'adjust_return_receivable' then 'finance.ar.adjust' when 'refund_customer_credit' then 'finance.payment.post' when 'offset_customer_credit' then 'finance.payment.post' when 'reverse_customer_credit_offset' then 'finance.payment.reverse' when 'resolve_commission_reconciliation' then 'compensation.manage' when 'create_delivery_expense' then 'finance.expense.manage' when 'approve_expense' then 'finance.expense.manage' when 'create_warehouse_transfer' then 'inventory.read' when 'record_warehouse_transfer_event' then 'inventory.read' when 'create_supplier_return' then 'purchasing.create' when 'record_supplier_return_event' then case when private.has_permission(target_branch_id,'inventory.reserve') then 'inventory.reserve' when private.has_permission(target_branch_id,'purchasing.confirm') then 'purchasing.confirm' else 'purchasing.cancel' end when 'approve_supplier_return_credit' then 'finance.ap.adjust' when 'refund_supplier_credit' then 'finance.payment.post' when 'offset_supplier_credit' then 'finance.payment.post' when 'register_supplier_document' then 'finance.ap.adjust' when 'review_supplier_document' then 'finance.ap.read' when 'create_invoice_draft' then 'finance.ar.adjust' when 'approve_invoice_business' then 'finance.reconcile' when 'cancel_invoice_draft' then 'finance.ar.adjust' when 'create_invoice_adjustment_draft' then 'finance.ar.adjust' when 'register_purchase_invoice_source' then 'finance.ap.adjust' when 'review_payment_notice' then 'finance.payment_notice.review' when 'match_payment_notice' then 'finance.payment_notice.review' when 'record_payment_reconciliation' then 'finance.reconcile' when 'reverse_payment_notice_match' then 'finance.payment_notice.review' else 'inventory.receive' end;
 if not private.has_permission(target_branch_id,permission) then raise exception 'forbidden' using errcode='42501';end if;
 for entry in select value from jsonb_array_elements(target_entries) loop
  if jsonb_typeof(entry) is distinct from 'array' or jsonb_array_length(entry)<>2
  or jsonb_typeof(entry->0)<>'string' or jsonb_typeof(entry->1)<>'string'
  or entry->>0 ~* '(password|token|secret)' or left(entry->>0,1)='$'
  then raise exception 'invalid_command_draft_field' using errcode='22023';end if;
 end loop;
 h:=private.command_payload_hash(target_entries);
 insert into private.command_drafts(operation_id,actor_auth_user_id,branch_id,command_name,form_entries,payload_hash)
 values(target_operation_id,(select auth.uid()),target_branch_id,target_command,target_entries,h)
 on conflict(operation_id) do nothing;
 select * into d from private.command_drafts where operation_id=target_operation_id for update;
 if d.actor_auth_user_id is distinct from(select auth.uid()) or d.branch_id is distinct from target_branch_id
 or d.command_name is distinct from target_command or d.payload_hash is distinct from h
 then raise exception 'operation_payload_conflict' using errcode='23505';end if;
 return d.operation_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_customer_site_profile(kind text, target_id uuid, target_branch_id uuid, values_json jsonb, expected_json jsonb, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  previous jsonb;
  base_values jsonb;
  base_expected jsonb;
  extra_fields text[];
  field_name text;
  owner_id uuid;
  owner_allowed boolean;
begin
  if auth.uid() is null or not private.has_permission(target_branch_id, 'customers.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if kind = 'customers' then
    extra_fields := array['tier_code', 'payment_terms_days', 'internal_note', 'sales_owner_employee_id', 'credit_limit_vnd'];
    if values_json ? 'tier_code' and not private.has_permission(target_branch_id, 'pricing.manage') then
      raise exception 'pricing_permission_required' using errcode = '42501';
    end if;
    if values_json ? 'credit_limit_vnd' and not private.has_permission(target_branch_id, 'finance.ar.adjust') then
      raise exception 'credit_limit_permission_required' using errcode = '42501';
    end if;
    select to_jsonb(c) into previous from public.customers c where c.id = target_id for update;
  elsif kind = 'sites' then
    extra_fields := array['latitude', 'longitude', 'sales_owner_employee_id'];
    select to_jsonb(s) into previous from public.customer_sites s where s.id = target_id for update;
    if (values_json ? 'latitude') <> (values_json ? 'longitude') then
      raise exception 'coordinate_pair_required' using errcode = '22023';
    end if;
  else
    raise exception 'unsupported_profile' using errcode = '22023';
  end if;

  if values_json ? 'sales_owner_employee_id'
    and nullif(values_json->>'sales_owner_employee_id', '') is not null
    and (previous is null or previous->>'sales_owner_employee_id' is distinct from values_json->>'sales_owner_employee_id') then
    begin
      owner_id := (values_json->>'sales_owner_employee_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'invalid_sales_owner' using errcode = '22023';
    end;
    select exists(select 1 from public.employees e join public.employee_branch_access a on a.employee_id = e.id
      where e.id = owner_id and e.active and a.branch_id = target_branch_id and a.active)
      into owner_allowed;
    if not owner_allowed then raise exception 'sales_owner_outside_branch' using errcode = '42501'; end if;
  end if;

  if previous is not null then
    if expected_json is null then raise exception 'record_already_exists' using errcode = '23505'; end if;
    foreach field_name in array extra_fields loop
      if values_json ? field_name then
        if not expected_json ? field_name then raise exception 'stale_record_reload' using errcode = 'PT409'; end if;
        if field_name in ('latitude', 'longitude', 'payment_terms_days', 'credit_limit_vnd') then
          if (previous->>field_name)::numeric is distinct from (expected_json->>field_name)::numeric then
            raise exception 'stale_record_reload' using errcode = 'PT409';
          end if;
        elsif previous->>field_name is distinct from expected_json->>field_name then
          raise exception 'stale_record_reload' using errcode = 'PT409';
        end if;
      end if;
    end loop;
  elsif expected_json is not null then
    raise exception 'record_missing' using errcode = 'PT409';
  end if;

  base_values := values_json - extra_fields;
  base_expected := case when expected_json is null then null else expected_json - extra_fields end;
  begin
    perform public.save_catalog_record(kind, target_id, target_branch_id, base_values,
      base_expected, change_reason, operation_id);
  exception when sqlstate '40001' then
    raise exception 'stale_record_reload' using errcode = 'PT409';
  end;

  if kind = 'customers' then
    update public.customers c set
      tier_code = case when values_json ? 'tier_code' then nullif(values_json->>'tier_code', '') else c.tier_code end,
      payment_terms_days = case when values_json ? 'payment_terms_days' then (values_json->>'payment_terms_days')::integer else c.payment_terms_days end,
      internal_note = case when values_json ? 'internal_note' then nullif(values_json->>'internal_note', '') else c.internal_note end,
      sales_owner_employee_id = case when values_json ? 'sales_owner_employee_id' then nullif(values_json->>'sales_owner_employee_id', '')::uuid else c.sales_owner_employee_id end,
      credit_limit_vnd = case when values_json ? 'credit_limit_vnd' then nullif(values_json->>'credit_limit_vnd', '')::bigint else c.credit_limit_vnd end
    where c.id = target_id and c.branch_id = target_branch_id;
  else
    update public.customer_sites s set
      latitude = case when values_json ? 'latitude' then nullif(values_json->>'latitude', '')::numeric else s.latitude end,
      longitude = case when values_json ? 'longitude' then nullif(values_json->>'longitude', '')::numeric else s.longitude end,
      sales_owner_employee_id = case when values_json ? 'sales_owner_employee_id' then nullif(values_json->>'sales_owner_employee_id', '')::uuid else s.sales_owner_employee_id end
    where s.id = target_id;
  end if;

  if values_json ?| extra_fields then
    insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type,
      entity_id, trace_id, changed_fields, reason)
    values(auth.uid(), target_branch_id, 'profile.save',
      case when kind = 'customers' then 'customers' else 'customer_sites' end,
      target_id, operation_id,
      array(select key from jsonb_object_keys(values_json) as key where key = any(extra_fields)),
      change_reason);
  end if;
  return target_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_pricing_rule(target_id uuid, target_branch_id uuid, supersedes_id uuid, expected_version integer, values_json jsonb, change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  old_rule public.pricing_rules%rowtype; receipt public.command_receipts%rowtype; payload_hash text;
  field_name text; rule_scope text; rule_customer uuid; rule_material uuid; rule_group uuid;
  rule_tier text; rule_uom uuid; rule_price bigint; rule_source text;
  rule_from timestamptz; rule_to timestamptz; next_version integer;
begin
  if auth.uid() is null or not private.has_permission(target_branch_id, 'pricing.manage') then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if target_id is null or operation_id is null or jsonb_typeof(values_json) <> 'object'
    or char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  payload_hash:=private.command_payload_hash(jsonb_build_object('target',target_id,'branch',target_branch_id,'supersedes',supersedes_id,'version',expected_version,'values',values_json,'reason',change_reason));
  perform pg_advisory_xact_lock(hashtextextended(operation_id::text,0));
  select * into receipt from public.command_receipts r where r.operation_id=save_pricing_rule.operation_id;
  if found then
   if receipt.command_name<>'save_pricing_rule' or receipt.payload_hash<>payload_hash or receipt.actor_auth_user_id is distinct from auth.uid() then raise exception 'operation_payload_conflict' using errcode='23505';end if;
   return receipt.result_entity_id;
  end if;
  for field_name in select jsonb_object_keys(values_json) loop
    if field_name <> all(array['scope_type','customer_id','material_id','material_group_id','customer_tier_code','price_uom_id','unit_price_vnd','source_type','effective_from','effective_to']) then
      raise exception 'field_not_editable' using errcode = '42501';
    end if;
  end loop;
  rule_price := (values_json->>'unit_price_vnd')::bigint;
  rule_source := values_json->>'source_type';
  rule_from := (values_json->>'effective_from')::timestamptz;
  rule_to := (values_json->>'effective_to')::timestamptz;
  if rule_price is null or rule_price <= 0 or rule_source not in ('LIST','CONTRACT') or rule_from is null
    or (rule_to is not null and rule_to <= rule_from) then
    raise exception 'invalid_price_rule' using errcode = '22023';
  end if;
  if supersedes_id is not null then
    select * into old_rule from public.pricing_rules where id = supersedes_id and branch_id = target_branch_id for update;
    if old_rule.id is null or expected_version is null or old_rule.version  IS DISTINCT FROM expected_version or not old_rule.active then
      raise exception 'stale_price_rule' using errcode = 'PT409';
    end if;
    if values_json ?| array['scope_type','customer_id','material_id','material_group_id','customer_tier_code','price_uom_id'] then
      raise exception 'scope_immutable' using errcode = '22023';
    end if;
    rule_scope := old_rule.scope_type; rule_customer := old_rule.customer_id;
    rule_material := old_rule.material_id; rule_group := old_rule.material_group_id;
    rule_tier := old_rule.customer_tier_code; rule_uom := old_rule.price_uom_id;
    if rule_from < old_rule.effective_from then raise exception 'effective_date_before_previous' using errcode = '22023'; end if;
    if exists (
      select 1 from public.pricing_rules p where p.branch_id = target_branch_id and p.scope_type = rule_scope
        and p.customer_id is not distinct from rule_customer and p.material_id is not distinct from rule_material
        and p.material_group_id is not distinct from rule_group and p.customer_tier_code is not distinct from rule_tier
        and p.price_uom_id = rule_uom and p.version > old_rule.version
    ) then raise exception 'newer_price_version_exists' using errcode = 'PT409'; end if;
  else
    if expected_version is not null then raise exception 'unexpected_version' using errcode = '22023'; end if;
    rule_scope := values_json->>'scope_type';
    rule_customer := (values_json->>'customer_id')::uuid;
    rule_material := (values_json->>'material_id')::uuid;
    rule_group := (values_json->>'material_group_id')::uuid;
    rule_tier := nullif(trim(values_json->>'customer_tier_code'), '');
    rule_uom := (values_json->>'price_uom_id')::uuid;
  end if;
  if not ((rule_scope = 'CUSTOMER_MATERIAL' and rule_customer is not null and rule_material is not null and rule_group is null and rule_tier is null)
    or (rule_scope = 'CUSTOMER_GROUP' and rule_customer is not null and rule_material is null and rule_group is not null and rule_tier is null)
    or (rule_scope = 'CUSTOMER_TIER' and rule_customer is null and rule_material is not null and rule_group is null and rule_tier is not null and char_length(rule_tier) <= 40)
    or (rule_scope = 'DEFAULT' and rule_customer is null and rule_material is not null and rule_group is null and rule_tier is null)) then
    raise exception 'invalid_price_scope' using errcode = '22023';
  end if;
  if rule_customer is not null and not exists (select 1 from public.customers where id = rule_customer and branch_id = target_branch_id and active) then
    raise exception 'customer_outside_branch' using errcode = '42501';
  end if;
  if rule_material is not null and not exists (select 1 from public.materials where id = rule_material and active and sale_enabled) then raise exception 'material_inactive' using errcode = '22023'; end if;
  if rule_group is not null and not exists (select 1 from public.material_groups where id = rule_group and active) then raise exception 'group_inactive' using errcode = '22023'; end if;
  if not exists (select 1 from public.units_of_measure where id = rule_uom and active) then raise exception 'uom_inactive' using errcode = '22023'; end if;
  if supersedes_id is null and exists (
    select 1 from public.pricing_rules p where p.branch_id = target_branch_id and p.active and p.scope_type = rule_scope
      and p.customer_id is not distinct from rule_customer and p.material_id is not distinct from rule_material
      and p.material_group_id is not distinct from rule_group and p.customer_tier_code is not distinct from rule_tier
      and p.price_uom_id = rule_uom
  ) then raise exception 'active_rule_exists' using errcode = 'PT409'; end if;
  perform pg_advisory_xact_lock(hashtextextended(rule_scope||':'||coalesce(rule_customer::text,'')||':'||coalesce(rule_material::text,'')||':'||coalesce(rule_group::text,'')||':'||coalesce(rule_tier,'')||':'||rule_uom::text,0));
  if supersedes_id is null and exists(select 1 from public.pricing_rules p where p.branch_id=target_branch_id and p.active and p.scope_type=rule_scope and p.customer_id is not distinct from rule_customer and p.material_id is not distinct from rule_material and p.material_group_id is not distinct from rule_group and p.customer_tier_code is not distinct from rule_tier and p.price_uom_id=rule_uom) then raise exception 'active_rule_exists' using errcode='PT409';end if;
  select coalesce(max(p.version), 0) + 1 into next_version from public.pricing_rules p
    where p.scope_type = rule_scope and p.customer_id is not distinct from rule_customer
      and p.material_id is not distinct from rule_material and p.material_group_id is not distinct from rule_group
      and p.customer_tier_code is not distinct from rule_tier and p.price_uom_id = rule_uom;
  if supersedes_id is not null then
    update public.pricing_rules set
      effective_to = case when effective_from = rule_from then effective_to
        when effective_to is null or effective_to > rule_from then rule_from else effective_to end,
      active = case when effective_from = rule_from then false else active end
    where id = supersedes_id;
  end if;
  insert into public.pricing_rules(id, branch_id, scope_type, customer_id, material_id, material_group_id,
    customer_tier_code, price_uom_id, unit_price_vnd, version, source_type,
    effective_from, effective_to, active, created_by)
  values(target_id, target_branch_id, rule_scope, rule_customer, rule_material, rule_group,
    rule_tier, rule_uom, rule_price, next_version, rule_source,
    rule_from, rule_to, true, auth.uid());
  insert into public.command_receipts values(operation_id,auth.uid(),'save_pricing_rule',payload_hash,'pricing_rule',target_id,now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields, reason)
  values(auth.uid(), target_branch_id, 'pricing.save', 'pricing_rules', target_id, operation_id,
    array(select jsonb_object_keys(values_json)), change_reason);
  return target_id;
end $function$

