CREATE OR REPLACE FUNCTION public.send_message(target_conversation_id uuid, target_body text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  conversation public.conversations%rowtype;
  message_id uuid;
  normalized_body text;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  select * into conversation from public.conversations c where c.id = target_conversation_id for update;
  if conversation.id is null or not private.can_access_conversation(conversation.id) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  normalized_body := trim(target_body);
  if char_length(normalized_body) not between 1 and 4000 then
    raise exception 'message_body_invalid' using errcode = '22023';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object('conversation_id', target_conversation_id, 'body', normalized_body));
  select * into receipt from public.command_receipts where command_receipts.operation_id = send_message.operation_id;
  if found then
    if receipt.command_name <> 'send_message' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  insert into public.messages(conversation_id, sender_auth_user_id, body, operation_id)
  values (conversation.id, (select auth.uid()), normalized_body, operation_id)
  returning id into message_id;
  update public.conversations
    set last_message_id = message_id,
        last_message_preview = left(normalized_body, 240),
        last_message_at = now(),
        updated_at = now()
    where id = conversation.id;
  update public.conversation_participants
    set unread_count = case when auth_user_id = (select auth.uid()) then 0 else unread_count + 1 end,
        last_read_at = case when auth_user_id = (select auth.uid()) then now() else last_read_at end
    where conversation_id = conversation.id and active;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'send_message', payload_hash, 'message', message_id, now());
  return message_id;
end
$function$

CREATE OR REPLACE FUNCTION public.send_quote_revision(target_revision_id uuid, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare revision public.quotation_revisions%rowtype; quote public.quotations%rowtype; hash text; receipt public.command_receipts%rowtype;
begin
  select r.* into revision from public.quotation_revisions r where r.id = target_revision_id for update;
  select q.* into quote from public.quotations q where q.id = revision.quotation_id;
  if not private.has_permission(quote.branch_id, 'quotation.send') then raise exception 'forbidden' using errcode = '42501'; end if;
  hash := private.command_payload_hash(jsonb_build_object('revision_id', target_revision_id));
  select * into receipt from public.command_receipts where command_receipts.operation_id = send_quote_revision.operation_id;
  if found then if receipt.command_name <> 'send_quote_revision' or receipt.payload_hash <> hash then raise exception 'operation_payload_conflict' using errcode = '23505'; end if; return receipt.result_entity_id; end if;
  if revision.state <> 'DRAFT' or revision.total_vnd <= 0 then raise exception 'quote_revision_not_sendable' using errcode = '23514'; end if;
  update public.quotation_revisions set state = 'SENT', sent_at = now() where id = target_revision_id;
  insert into public.command_receipts values (operation_id, (select auth.uid()), 'send_quote_revision', hash, 'quotation_revision', target_revision_id, now());
  insert into public.audit_events(actor_auth_user_id, branch_id, action, entity_type, entity_id, trace_id, changed_fields)
  values ((select auth.uid()), quote.branch_id, 'quotation.send', 'quotation_revision', target_revision_id,
    operation_id, array['state', 'sent_at']);
  return target_revision_id;
end
$function$

CREATE OR REPLACE FUNCTION public.set_employee_explicit_permissions(target_employee_id uuid, target_branch_id uuid, permission_codes text[], change_reason text, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  access_id uuid;
  requested text[];
begin
  select coalesce(array_agg(distinct item.permission_code order by item.permission_code), '{}'::text[])
  into requested
  from unnest(coalesce(permission_codes, '{}'::text[])) as item(permission_code)
  where item.permission_code is not null and item.permission_code <> '';

  if auth.uid() is null
    or not private.has_permission(target_branch_id, 'roles.manage')
    or target_employee_id = private.current_employee_id()
  then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if char_length(trim(coalesce(change_reason, ''))) not between 3 and 500 then
    raise exception 'reason_required' using errcode = '22023';
  end if;

  select a.id into access_id
  from public.employee_branch_access a
  join public.employees e on e.id = a.employee_id and e.active
  where a.employee_id = target_employee_id
    and a.branch_id = target_branch_id
    and a.active
  for update of a;

  if access_id is null then
    raise exception 'active_access_required' using errcode = '23503';
  end if;
  if exists (
    select 1 from unnest(requested) as item(permission_code)
    left join public.permissions p on p.code = item.permission_code
    where p.code is null
  ) then
    raise exception 'invalid_permission' using errcode = '23503';
  end if;
  if exists (
    select 1 from unnest(requested) as item(permission_code)
    where not private.has_permission(target_branch_id, item.permission_code)
  ) then
    raise exception 'permission_exceeds_actor' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.employee_permission_grants current_grant
    where current_grant.employee_id = target_employee_id
      and current_grant.branch_id = target_branch_id
      and not private.has_permission(target_branch_id, current_grant.permission_code)
  ) then
    raise exception 'existing_permission_exceeds_actor' using errcode = '42501';
  end if;

  delete from public.employee_permission_grants
  where employee_id = target_employee_id and branch_id = target_branch_id;

  insert into public.employee_permission_grants(
    employee_id, branch_id, permission_code, granted_by
  )
  select target_employee_id, target_branch_id, item.permission_code, auth.uid()
  from unnest(requested) as item(permission_code);

  insert into public.audit_events(
    actor_auth_user_id, branch_id, action, entity_type, entity_id,
    trace_id, changed_fields, reason
  ) values (
    auth.uid(), target_branch_id, 'employee.permission.set', 'employee_branch_access', access_id,
    operation_id, array['explicit_permissions'], trim(change_reason)
  );
  return access_id;
end
$function$

CREATE OR REPLACE FUNCTION public.set_inventory_stock_threshold(target_branch_id uuid, target_warehouse_id uuid, target_material_id uuid, target_threshold_base_quantity numeric, target_active boolean)
 RETURNS TABLE(threshold_id uuid, threshold_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  saved public.inventory_stock_thresholds;
begin
  perform private.require_exact_quantity(target_threshold_base_quantity,true);

  if auth.uid() is null or not private.has_permission(target_branch_id, 'inventory.adjust') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if target_threshold_base_quantity is null or target_threshold_base_quantity < 0 then
    raise exception 'invalid_threshold' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.warehouses w
    where w.id = target_warehouse_id
      and w.branch_id = target_branch_id
      and w.active
  ) then
    raise exception 'warehouse_not_available' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.materials m
    where m.id = target_material_id
      and m.active
  ) then
    raise exception 'material_not_available' using errcode = '22023';
  end if;

  insert into public.inventory_stock_thresholds (
    branch_id,
    warehouse_id,
    material_id,
    threshold_base_quantity,
    active,
    created_by,
    updated_by
  )
  values (
    target_branch_id,
    target_warehouse_id,
    target_material_id,
    target_threshold_base_quantity,
    target_active,
    auth.uid(),
    auth.uid()
  )
  on conflict (branch_id, warehouse_id, material_id)
  do update set
    threshold_base_quantity = excluded.threshold_base_quantity,
    active = excluded.active,
    version = public.inventory_stock_thresholds.version + 1,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into saved;

  return query select saved.id, saved.version;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_gps_tracking(target_delivery_id uuid, target_assignment_version integer, operation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  delivery public.deliveries%rowtype;
  assignment public.delivery_assignments%rowtype;
  employee_id uuid;
  session_id uuid;
  payload_hash text;
  receipt public.command_receipts%rowtype;
begin
  employee_id := private.current_employee_id();
  if employee_id is null then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into delivery from public.deliveries d where d.id = target_delivery_id for update;
  select * into assignment from public.delivery_assignments a
    where a.delivery_id = target_delivery_id and a.superseded_at is null for update;
  if delivery.id is null or assignment.id is null or assignment.employee_id <> employee_id
    or assignment.assignment_version  IS DISTINCT FROM target_assignment_version
    or delivery.execution_state not in ('ASSIGNED','DISPATCHED','ARRIVED','RESULT_SUBMITTED') then
    raise exception 'gps_assignment_not_active' using errcode = '42501';
  end if;
  payload_hash := private.command_payload_hash(jsonb_build_object(
    'delivery_id', target_delivery_id,
    'assignment_version', target_assignment_version
  ));
  select * into receipt from public.command_receipts where command_receipts.operation_id = start_gps_tracking.operation_id;
  if found then
    if receipt.command_name <> 'start_gps_tracking' or receipt.payload_hash <> payload_hash then
      raise exception 'operation_payload_conflict' using errcode = '23505';
    end if;
    return receipt.result_entity_id;
  end if;
  select s.id into session_id from public.gps_tracking_sessions s
    where s.assignment_id = assignment.id and s.status = 'ACTIVE' for update;
  if session_id is null then
    update public.gps_tracking_sessions
      set status = 'REVOKED', stopped_at = now(), stop_reason = 'assignment_superseded'
      where delivery_id = delivery.id and status = 'ACTIVE';
    insert into public.gps_tracking_sessions(
      branch_id, delivery_id, assignment_id, assignment_version, employee_id, vehicle_id, started_by, start_operation_id
    ) values (
